/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Usage_TitleInputs */

const en_settings_usage_title = /** @type {(inputs: Settings_Usage_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Usage`)
};

const zh_cn2_settings_usage_title = /** @type {(inputs: Settings_Usage_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`用途`)
};

const ja_settings_usage_title = /** @type {(inputs: Settings_Usage_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`使用状況`)
};

/**
* | output |
* | --- |
* | "Usage" |
*
* @param {Settings_Usage_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage_title = /** @type {((inputs?: Settings_Usage_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Usage_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage_title(inputs)
	if (locale === "ja") return ja_settings_usage_title(inputs)
	return en_settings_usage_title(inputs)
});