/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Auth_Invite_InvitedasInputs */

const en_auth_invite_invitedas = /** @type {(inputs: Auth_Invite_InvitedasInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Invited as ${i?.email}`)
};

const zh_cn2_auth_invite_invitedas = /** @type {(inputs: Auth_Invite_InvitedasInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`受邀作为 ${i?.email}`)
};

const ja_auth_invite_invitedas = /** @type {(inputs: Auth_Invite_InvitedasInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.email} として招待されました`)
};

/**
* | output |
* | --- |
* | "Invited as {email}" |
*
* @param {Auth_Invite_InvitedasInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_invitedas = /** @type {((inputs: Auth_Invite_InvitedasInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_InvitedasInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_invitedas(inputs)
	if (locale === "ja") return ja_auth_invite_invitedas(inputs)
	return en_auth_invite_invitedas(inputs)
});