/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Languages_DescriptionInputs */

const en_settings_languages_description = /** @type {(inputs: Settings_Languages_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The languages this site is written in. Disabled languages stay editable in the dashboard but are hidden from the published site.`)
};

const zh_cn2_settings_languages_description = /** @type {(inputs: Settings_Languages_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`此网站所使用的语言。禁用的语言在仪表板中保持可编辑状态，但在已发布的网站中隐藏。`)
};

const ja_settings_languages_description = /** @type {(inputs: Settings_Languages_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このサイトが書かれている言語。無効な言語はダッシュボード内で編集可能なままですが、公開されたサイトでは非表示になります。`)
};

/**
* | output |
* | --- |
* | "The languages this site is written in. Disabled languages stay editable in the dashboard but are hidden from the published site." |
*
* @param {Settings_Languages_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_description = /** @type {((inputs?: Settings_Languages_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_description(inputs)
	if (locale === "ja") return ja_settings_languages_description(inputs)
	return en_settings_languages_description(inputs)
});