import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Members_SubtitleInputs */

const en_members_subtitle = /** @type {(inputs: Members_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Invite teammates to collaborate on documentation.`)
};

const zh_cn2_members_subtitle = /** @type {(inputs: Members_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`邀请团队成员协作处理文档。`)
};

const ja_members_subtitle = /** @type {(inputs: Members_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`チームメイトを招待してドキュメントを共同作成します。`)
};

/**
* | output |
* | --- |
* | "Invite teammates to collaborate on documentation." |
*
* @param {Members_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const members_subtitle = /** @type {((inputs?: Members_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Members_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_members_subtitle(inputs)
	if (locale === "ja") return ja_members_subtitle(inputs)
	return en_members_subtitle(inputs)
});