/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ label: NonNullable<unknown> }} Settings_Languages_EnabledtoggleInputs */

const en_settings_languages_enabledtoggle = /** @type {(inputs: Settings_Languages_EnabledtoggleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Serve ${i?.label} on the published site`)
};

const zh_cn2_settings_languages_enabledtoggle = /** @type {(inputs: Settings_Languages_EnabledtoggleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`在已发布的网站上提供 ${i?.label}`)
};

const ja_settings_languages_enabledtoggle = /** @type {(inputs: Settings_Languages_EnabledtoggleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`公開サイトで ${i?.label} を提供する`)
};

/**
* | output |
* | --- |
* | "Serve {label} on the published site" |
*
* @param {Settings_Languages_EnabledtoggleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_enabledtoggle = /** @type {((inputs: Settings_Languages_EnabledtoggleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_EnabledtoggleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_enabledtoggle(inputs)
	if (locale === "ja") return ja_settings_languages_enabledtoggle(inputs)
	return en_settings_languages_enabledtoggle(inputs)
});