/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Brand_MultilingualInputs */

const en_auth_brand_multilingual = /** @type {(inputs: Auth_Brand_MultilingualInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Multilingual and RTL-ready authoring`)
};

const zh_cn2_auth_brand_multilingual = /** @type {(inputs: Auth_Brand_MultilingualInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`多语言和 RTL 就绪创作`)
};

const ja_auth_brand_multilingual = /** @type {(inputs: Auth_Brand_MultilingualInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`多言語および RTL 対応のオーサリング`)
};

/**
* | output |
* | --- |
* | "Multilingual and RTL-ready authoring" |
*
* @param {Auth_Brand_MultilingualInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_brand_multilingual = /** @type {((inputs?: Auth_Brand_MultilingualInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Brand_MultilingualInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_brand_multilingual(inputs)
	if (locale === "ja") return ja_auth_brand_multilingual(inputs)
	return en_auth_brand_multilingual(inputs)
});