import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Legal_TermsInputs */

const en_auth_legal_terms = /** @type {(inputs: Auth_Legal_TermsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Terms of Service`)
};

const zh_cn2_auth_legal_terms = /** @type {(inputs: Auth_Legal_TermsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`服务条款`)
};

const ja_auth_legal_terms = /** @type {(inputs: Auth_Legal_TermsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`利用規約`)
};

/**
* | output |
* | --- |
* | "Terms of Service" |
*
* @param {Auth_Legal_TermsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_legal_terms = /** @type {((inputs?: Auth_Legal_TermsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Legal_TermsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_legal_terms(inputs)
	if (locale === "ja") return ja_auth_legal_terms(inputs)
	return en_auth_legal_terms(inputs)
});