import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_SharexInputs */

const en_blog_sharex = /** @type {(inputs: Blog_SharexInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Share on X`)
};

const zh_cn2_blog_sharex = /** @type {(inputs: Blog_SharexInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Share on X`)
};

const ja_blog_sharex = /** @type {(inputs: Blog_SharexInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Xで共有する`)
};

/**
* | output |
* | --- |
* | "Share on X" |
*
* @param {Blog_SharexInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_sharex = /** @type {((inputs?: Blog_SharexInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_SharexInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_sharex(inputs)
	if (locale === "ja") return ja_blog_sharex(inputs)
	return en_blog_sharex(inputs)
});