/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ site: NonNullable<unknown> }} Admin_Sites_ViewInputs */

const en_admin_sites_view = /** @type {(inputs: Admin_Sites_ViewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`View ${i?.site}`)
};

const zh_cn2_admin_sites_view = /** @type {(inputs: Admin_Sites_ViewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`View ${i?.site}`)
};

const ja_admin_sites_view = /** @type {(inputs: Admin_Sites_ViewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`__VAR_サイト__を見る ${i?.site}`)
};

/**
* | output |
* | --- |
* | "View {site}" |
*
* @param {Admin_Sites_ViewInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_sites_view = /** @type {((inputs: Admin_Sites_ViewInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Sites_ViewInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_sites_view(inputs)
	if (locale === "ja") return ja_admin_sites_view(inputs)
	return en_admin_sites_view(inputs)
});