/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ user: NonNullable<unknown> }} Admin_Users_ViewInputs */

const en_admin_users_view = /** @type {(inputs: Admin_Users_ViewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`View ${i?.user}`)
};

const zh_cn2_admin_users_view = /** @type {(inputs: Admin_Users_ViewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`View ${i?.user}`)
};

const ja_admin_users_view = /** @type {(inputs: Admin_Users_ViewInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.user} を表示する`)
};

/**
* | output |
* | --- |
* | "View {user}" |
*
* @param {Admin_Users_ViewInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_users_view = /** @type {((inputs: Admin_Users_ViewInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Users_ViewInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_users_view(inputs)
	if (locale === "ja") return ja_admin_users_view(inputs)
	return en_admin_users_view(inputs)
});