import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_BacktodashboardInputs */

const en_editor_backtodashboard = /** @type {(inputs: Editor_BacktodashboardInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Back to dashboard`)
};

const zh_cn2_editor_backtodashboard = /** @type {(inputs: Editor_BacktodashboardInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`返回仪表板`)
};

const ja_editor_backtodashboard = /** @type {(inputs: Editor_BacktodashboardInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ダッシュボードに戻る`)
};

/**
* | output |
* | --- |
* | "Back to dashboard" |
*
* @param {Editor_BacktodashboardInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_backtodashboard = /** @type {((inputs?: Editor_BacktodashboardInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_BacktodashboardInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_backtodashboard(inputs)
	if (locale === "ja") return ja_editor_backtodashboard(inputs)
	return en_editor_backtodashboard(inputs)
});