import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_SearchlabelInputs */

const en_blog_searchlabel = /** @type {(inputs: Blog_SearchlabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search articles`)
};

const zh_cn2_blog_searchlabel = /** @type {(inputs: Blog_SearchlabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search articles`)
};

const ja_blog_searchlabel = /** @type {(inputs: Blog_SearchlabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`記事を探す`)
};

/**
* | output |
* | --- |
* | "Search articles" |
*
* @param {Blog_SearchlabelInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_searchlabel = /** @type {((inputs?: Blog_SearchlabelInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_SearchlabelInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_searchlabel(inputs)
	if (locale === "ja") return ja_blog_searchlabel(inputs)
	return en_blog_searchlabel(inputs)
});