import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_ImportlanguageInputs */

const en_settings_git_importlanguage = /** @type {(inputs: Settings_Git_ImportlanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import into language`)
};

const zh_cn2_settings_git_importlanguage = /** @type {(inputs: Settings_Git_ImportlanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导入到语言中`)
};

const ja_settings_git_importlanguage = /** @type {(inputs: Settings_Git_ImportlanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語にインポートする`)
};

/**
* | output |
* | --- |
* | "Import into language" |
*
* @param {Settings_Git_ImportlanguageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_importlanguage = /** @type {((inputs?: Settings_Git_ImportlanguageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_ImportlanguageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_importlanguage(inputs)
	if (locale === "ja") return ja_settings_git_importlanguage(inputs)
	return en_settings_git_importlanguage(inputs)
});