/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_SuccessInputs */

const en_settings_import_success = /** @type {(inputs: Settings_Import_SuccessInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import finished`)
};

const zh_cn2_settings_import_success = /** @type {(inputs: Settings_Import_SuccessInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导入完成`)
};

const ja_settings_import_success = /** @type {(inputs: Settings_Import_SuccessInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`インポートが完了しました`)
};

/**
* | output |
* | --- |
* | "Import finished" |
*
* @param {Settings_Import_SuccessInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_success = /** @type {((inputs?: Settings_Import_SuccessInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_SuccessInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_success(inputs)
	if (locale === "ja") return ja_settings_import_success(inputs)
	return en_settings_import_success(inputs)
});