/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_ContentimportInputs */

const en_settings_contentimport = /** @type {(inputs: Settings_ContentimportInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import`)
};

const zh_cn2_settings_contentimport = /** @type {(inputs: Settings_ContentimportInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`进口`)
};

const ja_settings_contentimport = /** @type {(inputs: Settings_ContentimportInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`輸入`)
};

/**
* | output |
* | --- |
* | "Import" |
*
* @param {Settings_ContentimportInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_contentimport = /** @type {((inputs?: Settings_ContentimportInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_ContentimportInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_contentimport(inputs)
	if (locale === "ja") return ja_settings_contentimport(inputs)
	return en_settings_contentimport(inputs)
});