/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ code: NonNullable<unknown> }} Admin_Site_DefaultlanguagesuffixInputs */

const en_admin_site_defaultlanguagesuffix = /** @type {(inputs: Admin_Site_DefaultlanguagesuffixInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.code} (default)`)
};

const zh_cn2_admin_site_defaultlanguagesuffix = /** @type {(inputs: Admin_Site_DefaultlanguagesuffixInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.code}（默认）`)
};

const ja_admin_site_defaultlanguagesuffix = /** @type {(inputs: Admin_Site_DefaultlanguagesuffixInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.code} (デフォルト)`)
};

/**
* | output |
* | --- |
* | "{code} (default)" |
*
* @param {Admin_Site_DefaultlanguagesuffixInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_site_defaultlanguagesuffix = /** @type {((inputs: Admin_Site_DefaultlanguagesuffixInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Site_DefaultlanguagesuffixInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_site_defaultlanguagesuffix(inputs)
	if (locale === "ja") return ja_admin_site_defaultlanguagesuffix(inputs)
	return en_admin_site_defaultlanguagesuffix(inputs)
});