import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Dashboard_Search_PlaceholderInputs */

const en_dashboard_search_placeholder = /** @type {(inputs: Dashboard_Search_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search…`)
};

const zh_cn2_dashboard_search_placeholder = /** @type {(inputs: Dashboard_Search_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`搜索...`)
};

const ja_dashboard_search_placeholder = /** @type {(inputs: Dashboard_Search_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検索…`)
};

/**
* | output |
* | --- |
* | "Search…" |
*
* @param {Dashboard_Search_PlaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const dashboard_search_placeholder = /** @type {((inputs?: Dashboard_Search_PlaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Dashboard_Search_PlaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_dashboard_search_placeholder(inputs)
	if (locale === "ja") return ja_dashboard_search_placeholder(inputs)
	return en_dashboard_search_placeholder(inputs)
});