import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Banner_Scope_HintInputs */

const en_settings_banner_scope_hint = /** @type {(inputs: Settings_Banner_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose which language this banner applies to. Empty fields fall back to the default banner.`)
};

const zh_cn2_settings_banner_scope_hint = /** @type {(inputs: Settings_Banner_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择此横幅适用的语言。空字段会回退到默认横幅。`)
};

const ja_settings_banner_scope_hint = /** @type {(inputs: Settings_Banner_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このバナーが適用される言語を選択してください。空のフィールドはデフォルトのバナーに戻ります。`)
};

/**
* | output |
* | --- |
* | "Choose which language this banner applies to. Empty fields fall back to the default banner." |
*
* @param {Settings_Banner_Scope_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_banner_scope_hint = /** @type {((inputs?: Settings_Banner_Scope_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Banner_Scope_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_banner_scope_hint(inputs)
	if (locale === "ja") return ja_settings_banner_scope_hint(inputs)
	return en_settings_banner_scope_hint(inputs)
});