import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_Gitlab_DescriptionInputs */

const en_settings_integrations_gitlab_description = /** @type {(inputs: Settings_Integrations_Gitlab_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Connect a GitLab project to host content as files.`)
};

const zh_cn2_settings_integrations_gitlab_description = /** @type {(inputs: Settings_Integrations_Gitlab_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`连接一个 GitLab 项目, 将内容作为文件主机 。`)
};

const ja_settings_integrations_gitlab_description = /** @type {(inputs: Settings_Integrations_Gitlab_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`GitLab プロジェクトを接続して、コンテンツをファイルとしてホストします。`)
};

/**
* | output |
* | --- |
* | "Connect a GitLab project to host content as files." |
*
* @param {Settings_Integrations_Gitlab_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_gitlab_description = /** @type {((inputs?: Settings_Integrations_Gitlab_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_Gitlab_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_gitlab_description(inputs)
	if (locale === "ja") return ja_settings_integrations_gitlab_description(inputs)
	return en_settings_integrations_gitlab_description(inputs)
});