import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Pagesettings_TitleInputs */

const en_editor_pagesettings_title = /** @type {(inputs: Editor_Pagesettings_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Page settings`)
};

const zh_cn2_editor_pagesettings_title = /** @type {(inputs: Editor_Pagesettings_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`页面设置`)
};

const ja_editor_pagesettings_title = /** @type {(inputs: Editor_Pagesettings_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ページ設定`)
};

/**
* | output |
* | --- |
* | "Page settings" |
*
* @param {Editor_Pagesettings_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_pagesettings_title = /** @type {((inputs?: Editor_Pagesettings_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Pagesettings_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_pagesettings_title(inputs)
	if (locale === "ja") return ja_editor_pagesettings_title(inputs)
	return en_editor_pagesettings_title(inputs)
});