/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ url: NonNullable<unknown>, path: NonNullable<unknown> }} Settings_Addons_Issueurl_HintInputs */

const en_settings_addons_issueurl_hint = /** @type {(inputs: Settings_Addons_Issueurl_HintInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Use ${i?.url} or ${i?.path} to prefill the current page in an external issue form.`)
};

const zh_cn2_settings_addons_issueurl_hint = /** @type {(inputs: Settings_Addons_Issueurl_HintInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`使用 ${i?.url} 或 ${i?.path} 在外部问题表单中预填充当前页面。`)
};

const ja_settings_addons_issueurl_hint = /** @type {(inputs: Settings_Addons_Issueurl_HintInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.url} または ${i?.path} を使用して、外部の問題フォームに現在のページを事前に入力します。`)
};

/**
* | output |
* | --- |
* | "Use {url} or {path} to prefill the current page in an external issue form." |
*
* @param {Settings_Addons_Issueurl_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_addons_issueurl_hint = /** @type {((inputs: Settings_Addons_Issueurl_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Addons_Issueurl_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_addons_issueurl_hint(inputs)
	if (locale === "ja") return ja_settings_addons_issueurl_hint(inputs)
	return en_settings_addons_issueurl_hint(inputs)
});