/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Admin_Mutation_InvitationqueuedInputs */

const en_admin_mutation_invitationqueued = /** @type {(inputs: Admin_Mutation_InvitationqueuedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Owner invitation queued for ${i?.email}`)
};

const zh_cn2_admin_mutation_invitationqueued = /** @type {(inputs: Admin_Mutation_InvitationqueuedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Owner invitation queued for ${i?.email}`)
};

const ja_admin_mutation_invitationqueued = /** @type {(inputs: Admin_Mutation_InvitationqueuedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`所有者の招待状が ${i?.email} のキューに登録されました`)
};

/**
* | output |
* | --- |
* | "Owner invitation queued for {email}" |
*
* @param {Admin_Mutation_InvitationqueuedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_mutation_invitationqueued = /** @type {((inputs: Admin_Mutation_InvitationqueuedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Mutation_InvitationqueuedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_mutation_invitationqueued(inputs)
	if (locale === "ja") return ja_admin_mutation_invitationqueued(inputs)
	return en_admin_mutation_invitationqueued(inputs)
});