import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_SharelinkedinInputs */

const en_blog_sharelinkedin = /** @type {(inputs: Blog_SharelinkedinInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Share on LinkedIn`)
};

const zh_cn2_blog_sharelinkedin = /** @type {(inputs: Blog_SharelinkedinInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Share on LinkedIn`)
};

const ja_blog_sharelinkedin = /** @type {(inputs: Blog_SharelinkedinInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`LinkedIn で共有する`)
};

/**
* | output |
* | --- |
* | "Share on LinkedIn" |
*
* @param {Blog_SharelinkedinInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_sharelinkedin = /** @type {((inputs?: Blog_SharelinkedinInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_SharelinkedinInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_sharelinkedin(inputs)
	if (locale === "ja") return ja_blog_sharelinkedin(inputs)
	return en_blog_sharelinkedin(inputs)
});