/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_ViewsiteInputs */

const en_deploy_viewsite = /** @type {(inputs: Deploy_ViewsiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`View site`)
};

const zh_cn2_deploy_viewsite = /** @type {(inputs: Deploy_ViewsiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`查看网站`)
};

const ja_deploy_viewsite = /** @type {(inputs: Deploy_ViewsiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`サイトを見る`)
};

/**
* | output |
* | --- |
* | "View site" |
*
* @param {Deploy_ViewsiteInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_viewsite = /** @type {((inputs?: Deploy_ViewsiteInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_ViewsiteInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_viewsite(inputs)
	if (locale === "ja") return ja_deploy_viewsite(inputs)
	return en_deploy_viewsite(inputs)
});