/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ user: NonNullable<unknown> }} Admin_Users_SuspendtitleInputs */

const en_admin_users_suspendtitle = /** @type {(inputs: Admin_Users_SuspendtitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Suspend ${i?.user}?`)
};

const zh_cn2_admin_users_suspendtitle = /** @type {(inputs: Admin_Users_SuspendtitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Suspend ${i?.user}?`)
};

const ja_admin_users_suspendtitle = /** @type {(inputs: Admin_Users_SuspendtitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.user} を一時停止しますか?`)
};

/**
* | output |
* | --- |
* | "Suspend {user}?" |
*
* @param {Admin_Users_SuspendtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_users_suspendtitle = /** @type {((inputs: Admin_Users_SuspendtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Users_SuspendtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_users_suspendtitle(inputs)
	if (locale === "ja") return ja_admin_users_suspendtitle(inputs)
	return en_admin_users_suspendtitle(inputs)
});