/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ hours: NonNullable<unknown>, count: NonNullable<unknown> }} Admin_Overview_MedianpublishInputs */

const en_admin_overview_medianpublish = /** @type {(inputs: Admin_Overview_MedianpublishInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Median time to first successful publish: ${i?.hours}h. ${i?.count} sign-ups published successfully within 24h.`)
};

const zh_cn2_admin_overview_medianpublish = /** @type {(inputs: Admin_Overview_MedianpublishInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Median time to first successful publish: ${i?.hours}h. ${i?.count} sign-ups published successfully within 24h.`)
};

const ja_admin_overview_medianpublish = /** @type {(inputs: Admin_Overview_MedianpublishInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最初に公開が成功するまでの時間の中央値: ${i?.hours}h。 ${i?.count} 件のサインアップが 24 時間以内に正常に公開されました。`)
};

/**
* | output |
* | --- |
* | "Median time to first successful publish: {hours}h. {count} sign-ups published successfully within 24h." |
*
* @param {Admin_Overview_MedianpublishInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_overview_medianpublish = /** @type {((inputs: Admin_Overview_MedianpublishInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Overview_MedianpublishInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_overview_medianpublish(inputs)
	if (locale === "ja") return ja_admin_overview_medianpublish(inputs)
	return en_admin_overview_medianpublish(inputs)
});