/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Signin_SubtitleInputs */

const en_auth_signin_subtitle = /** @type {(inputs: Auth_Signin_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Log in to your workspace`)
};

const zh_cn2_auth_signin_subtitle = /** @type {(inputs: Auth_Signin_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`登录到您的工作区`)
};

const ja_auth_signin_subtitle = /** @type {(inputs: Auth_Signin_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ワークスペースにログインします`)
};

/**
* | output |
* | --- |
* | "Log in to your workspace" |
*
* @param {Auth_Signin_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_signin_subtitle = /** @type {((inputs?: Auth_Signin_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Signin_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_signin_subtitle(inputs)
	if (locale === "ja") return ja_auth_signin_subtitle(inputs)
	return en_auth_signin_subtitle(inputs)
});