import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Invite_SubtitleInputs */

const en_auth_invite_subtitle = /** @type {(inputs: Auth_Invite_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`You've been invited to a workspace`)
};

const zh_cn2_auth_invite_subtitle = /** @type {(inputs: Auth_Invite_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您已被邀请加入工作区`)
};

const ja_auth_invite_subtitle = /** @type {(inputs: Auth_Invite_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ワークスペースに招待されました`)
};

/**
* | output |
* | --- |
* | "You've been invited to a workspace" |
*
* @param {Auth_Invite_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_subtitle = /** @type {((inputs?: Auth_Invite_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_subtitle(inputs)
	if (locale === "ja") return ja_auth_invite_subtitle(inputs)
	return en_auth_invite_subtitle(inputs)
});