import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ExportInputs */

const en_settings_theme_export = /** @type {(inputs: Settings_Theme_ExportInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Export theme`)
};

const zh_cn2_settings_theme_export = /** @type {(inputs: Settings_Theme_ExportInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导出主题`)
};

const ja_settings_theme_export = /** @type {(inputs: Settings_Theme_ExportInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`テーマのエクスポート`)
};

/**
* | output |
* | --- |
* | "Export theme" |
*
* @param {Settings_Theme_ExportInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_export = /** @type {((inputs?: Settings_Theme_ExportInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ExportInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_export(inputs)
	if (locale === "ja") return ja_settings_theme_export(inputs)
	return en_settings_theme_export(inputs)
});