/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Members_Toast_InvitedInputs */

const en_members_toast_invited = /** @type {(inputs: Members_Toast_InvitedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Invited ${i?.email}`)
};

const zh_cn2_members_toast_invited = /** @type {(inputs: Members_Toast_InvitedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`已邀请 ${i?.email}`)
};

const ja_members_toast_invited = /** @type {(inputs: Members_Toast_InvitedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.email} を招待しました`)
};

/**
* | output |
* | --- |
* | "Invited {email}" |
*
* @param {Members_Toast_InvitedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const members_toast_invited = /** @type {((inputs: Members_Toast_InvitedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Members_Toast_InvitedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_members_toast_invited(inputs)
	if (locale === "ja") return ja_members_toast_invited(inputs)
	return en_members_toast_invited(inputs)
});