/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Editor_Branch_DialogdescInputs */

const en_editor_branch_dialogdesc = /** @type {(inputs: Editor_Branch_DialogdescInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Starts from the current version (${i?.name}). Publish includes every version so readers can switch between them.`)
};

const zh_cn2_editor_branch_dialogdesc = /** @type {(inputs: Editor_Branch_DialogdescInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`从当前版本 (${i?.name}) 开始。发布包括每个版本，以便读者可以在它们之间切换。`)
};

const ja_editor_branch_dialogdesc = /** @type {(inputs: Editor_Branch_DialogdescInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`現在のバージョン (${i?.name}) から開始します。 Publish にはすべてのバージョンが含まれているため、読者はバージョンを切り替えることができます。`)
};

/**
* | output |
* | --- |
* | "Starts from the current version ({name}). Publish includes every version so readers can switch between them." |
*
* @param {Editor_Branch_DialogdescInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_branch_dialogdesc = /** @type {((inputs: Editor_Branch_DialogdescInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Branch_DialogdescInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_branch_dialogdesc(inputs)
	if (locale === "ja") return ja_editor_branch_dialogdesc(inputs)
	return en_editor_branch_dialogdesc(inputs)
});