/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Langsettings_SaveerrorInputs */

const en_editor_langsettings_saveerror = /** @type {(inputs: Editor_Langsettings_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not save the language`)
};

const zh_cn2_editor_langsettings_saveerror = /** @type {(inputs: Editor_Langsettings_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法保存语言`)
};

const ja_editor_langsettings_saveerror = /** @type {(inputs: Editor_Langsettings_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を保存できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not save the language" |
*
* @param {Editor_Langsettings_SaveerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_langsettings_saveerror = /** @type {((inputs?: Editor_Langsettings_SaveerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Langsettings_SaveerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_langsettings_saveerror(inputs)
	if (locale === "ja") return ja_editor_langsettings_saveerror(inputs)
	return en_editor_langsettings_saveerror(inputs)
});