/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Dashboard_PagesInputs */

const en_dashboard_pages = /** @type {(inputs: Dashboard_PagesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} pages`)
};

const zh_cn2_dashboard_pages = /** @type {(inputs: Dashboard_PagesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 页`)
};

const ja_dashboard_pages = /** @type {(inputs: Dashboard_PagesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} ページ`)
};

/**
* | output |
* | --- |
* | "{count} pages" |
*
* @param {Dashboard_PagesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const dashboard_pages = /** @type {((inputs: Dashboard_PagesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Dashboard_PagesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_dashboard_pages(inputs)
	if (locale === "ja") return ja_dashboard_pages(inputs)
	return en_dashboard_pages(inputs)
});