import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Redirects_AddInputs */

const en_settings_redirects_add = /** @type {(inputs: Settings_Redirects_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add redirect`)
};

const zh_cn2_settings_redirects_add = /** @type {(inputs: Settings_Redirects_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`添加重定向`)
};

const ja_settings_redirects_add = /** @type {(inputs: Settings_Redirects_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`リダイレクトの追加`)
};

/**
* | output |
* | --- |
* | "Add redirect" |
*
* @param {Settings_Redirects_AddInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_redirects_add = /** @type {((inputs?: Settings_Redirects_AddInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Redirects_AddInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_redirects_add(inputs)
	if (locale === "ja") return ja_settings_redirects_add(inputs)
	return en_settings_redirects_add(inputs)
});