import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Chrome_Scope_DiscarddescriptionInputs */

const en_settings_chrome_scope_discarddescription = /** @type {(inputs: Settings_Chrome_Scope_DiscarddescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`You have unsaved changes in this scope. Switching to another language will discard them.`)
};

const zh_cn2_settings_chrome_scope_discarddescription = /** @type {(inputs: Settings_Chrome_Scope_DiscarddescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您在此范围内有未保存的更改。切换到另一种语言将会丢弃它们。`)
};

const ja_settings_chrome_scope_discarddescription = /** @type {(inputs: Settings_Chrome_Scope_DiscarddescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このスコープには保存されていない変更があります。別の言語に切り替えると、それらは破棄されます。`)
};

/**
* | output |
* | --- |
* | "You have unsaved changes in this scope. Switching to another language will discard them." |
*
* @param {Settings_Chrome_Scope_DiscarddescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_chrome_scope_discarddescription = /** @type {((inputs?: Settings_Chrome_Scope_DiscarddescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Chrome_Scope_DiscarddescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_chrome_scope_discarddescription(inputs)
	if (locale === "ja") return ja_settings_chrome_scope_discarddescription(inputs)
	return en_settings_chrome_scope_discarddescription(inputs)
});