/**
* | output |
* | --- |
* | "Private integration workers are not enabled yet. Use the Git settings tab for public repository imports." |
*
* @param {Settings_Integrations_SelfhostedunavailableInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_selfhostedunavailable = /** @type {((inputs?: Settings_Integrations_SelfhostedunavailableInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_SelfhostedunavailableInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_selfhostedunavailable(inputs)
	if (locale === "ja") return ja_settings_integrations_selfhostedunavailable(inputs)
	return en_settings_integrations_selfhostedunavailable(inputs)
});