import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_Import_PreviewerrorInputs */

const en_settings_theme_import_previewerror = /** @type {(inputs: Settings_Theme_Import_PreviewerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not validate the theme template`)
};

const zh_cn2_settings_theme_import_previewerror = /** @type {(inputs: Settings_Theme_Import_PreviewerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法验证主题模板`)
};

const ja_settings_theme_import_previewerror = /** @type {(inputs: Settings_Theme_Import_PreviewerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`テーマテンプレートを検証できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not validate the theme template" |
*
* @param {Settings_Theme_Import_PreviewerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_import_previewerror = /** @type {((inputs?: Settings_Theme_Import_PreviewerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_Import_PreviewerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_import_previewerror(inputs)
	if (locale === "ja") return ja_settings_theme_import_previewerror(inputs)
	return en_settings_theme_import_previewerror(inputs)
});