/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_PublishedInputs */

const en_blog_published = /** @type {(inputs: Blog_PublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Published`)
};

const zh_cn2_blog_published = /** @type {(inputs: Blog_PublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Published`)
};

const ja_blog_published = /** @type {(inputs: Blog_PublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`発行済み`)
};

/**
* | output |
* | --- |
* | "Published" |
*
* @param {Blog_PublishedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_published = /** @type {((inputs?: Blog_PublishedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_PublishedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_published(inputs)
	if (locale === "ja") return ja_blog_published(inputs)
	return en_blog_published(inputs)
});