/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_DescriptionInputs */

const en_settings_domain_description = /** @type {(inputs: Settings_Domain_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add your domain, follow the DNS steps, and cms will automatically provision and renew TLS.`)
};

const zh_cn2_settings_domain_description = /** @type {(inputs: Settings_Domain_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`添加您的域，按照 DNS 步骤操作，cms 将自动配置和续订 TLS。`)
};

const ja_settings_domain_description = /** @type {(inputs: Settings_Domain_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドメインを追加し、DNS 手順に従うと、cms が TLS を自動的にプロビジョニングして更新します。`)
};

/**
* | output |
* | --- |
* | "Add your domain, follow the DNS steps, and cms will automatically provision and renew TLS." |
*
* @param {Settings_Domain_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_description = /** @type {((inputs?: Settings_Domain_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_description(inputs)
	if (locale === "ja") return ja_settings_domain_description(inputs)
	return en_settings_domain_description(inputs)
});