/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ theme: NonNullable<unknown> }} Admin_Theme_SwitchInputs */

const en_admin_theme_switch = /** @type {(inputs: Admin_Theme_SwitchInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Switch to ${i?.theme} theme`)
};

const zh_cn2_admin_theme_switch = /** @type {(inputs: Admin_Theme_SwitchInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Switch to ${i?.theme} theme`)
};

const ja_admin_theme_switch = /** @type {(inputs: Admin_Theme_SwitchInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.theme} テーマに切り替える`)
};

/**
* | output |
* | --- |
* | "Switch to {theme} theme" |
*
* @param {Admin_Theme_SwitchInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_theme_switch = /** @type {((inputs: Admin_Theme_SwitchInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Theme_SwitchInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_theme_switch(inputs)
	if (locale === "ja") return ja_admin_theme_switch(inputs)
	return en_admin_theme_switch(inputs)
});