import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Admin_Support_DescriptionInputs */

const en_admin_support_description = /** @type {(inputs: Admin_Support_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`This creates a one-hour support session in the customer app. Your admin session remains separate and every start and stop is recorded.`)
};

const zh_cn2_admin_support_description = /** @type {(inputs: Admin_Support_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`This creates a one-hour support session in the customer app. Your admin session remains separate and every start and stop is recorded.`)
};

const ja_admin_support_description = /** @type {(inputs: Admin_Support_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`これにより、顧客のアプリに 1 時間のサポート セッションが作成されます。管理セッションは分離されたままとなり、すべての開始と停止が記録されます。`)
};

/**
* | output |
* | --- |
* | "This creates a one-hour support session in the customer app. Your admin session remains separate and every start and stop is recorded." |
*
* @param {Admin_Support_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_support_description = /** @type {((inputs?: Admin_Support_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Support_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_support_description(inputs)
	if (locale === "ja") return ja_admin_support_description(inputs)
	return en_admin_support_description(inputs)
});