/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_CheckingInputs */

const en_publish_checking = /** @type {(inputs: Publish_CheckingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Checking for changes…`)
};

const zh_cn2_publish_checking = /** @type {(inputs: Publish_CheckingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`检查更改...`)
};

const ja_publish_checking = /** @type {(inputs: Publish_CheckingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`変更を確認しています…`)
};

/**
* | output |
* | --- |
* | "Checking for changes…" |
*
* @param {Publish_CheckingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_checking = /** @type {((inputs?: Publish_CheckingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_CheckingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_checking(inputs)
	if (locale === "ja") return ja_publish_checking(inputs)
	return en_publish_checking(inputs)
});