import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_General_Description_HintInputs */

const en_settings_general_description_hint = /** @type {(inputs: Settings_General_Description_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Brief overview of the project. Used for SEO and AEO.`)
};

const zh_cn2_settings_general_description_hint = /** @type {(inputs: Settings_General_Description_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`该项目的简要概述。用于 SEO 和 AEO。`)
};

const ja_settings_general_description_hint = /** @type {(inputs: Settings_General_Description_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`プロジェクトの簡単な概要。 SEOやAEOに利用されます。`)
};

/**
* | output |
* | --- |
* | "Brief overview of the project. Used for SEO and AEO." |
*
* @param {Settings_General_Description_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_general_description_hint = /** @type {((inputs?: Settings_General_Description_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_General_Description_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_general_description_hint(inputs)
	if (locale === "ja") return ja_settings_general_description_hint(inputs)
	return en_settings_general_description_hint(inputs)
});