import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ trigger: NonNullable<unknown>, attempts: NonNullable<unknown> }} Admin_Operations_ExportsummaryInputs */

const en_admin_operations_exportsummary = /** @type {(inputs: Admin_Operations_ExportsummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.trigger} export · ${i?.attempts} attempts`)
};

const zh_cn2_admin_operations_exportsummary = /** @type {(inputs: Admin_Operations_ExportsummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.trigger} export · ${i?.attempts} attempts`)
};

const ja_admin_operations_exportsummary = /** @type {(inputs: Admin_Operations_ExportsummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.trigger} エクスポート · ${i?.attempts} 試行`)
};

/**
* | output |
* | --- |
* | "{trigger} export · {attempts} attempts" |
*
* @param {Admin_Operations_ExportsummaryInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_operations_exportsummary = /** @type {((inputs: Admin_Operations_ExportsummaryInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Operations_ExportsummaryInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_operations_exportsummary(inputs)
	if (locale === "ja") return ja_admin_operations_exportsummary(inputs)
	return en_admin_operations_exportsummary(inputs)
});