/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_ViewsiteInputs */

const en_overview_viewsite = /** @type {(inputs: Overview_ViewsiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`View live site`)
};

const zh_cn2_overview_viewsite = /** @type {(inputs: Overview_ViewsiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`查看现场直播`)
};

const ja_overview_viewsite = /** @type {(inputs: Overview_ViewsiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ライブサイトを見る`)
};

/**
* | output |
* | --- |
* | "View live site" |
*
* @param {Overview_ViewsiteInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_viewsite = /** @type {((inputs?: Overview_ViewsiteInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_ViewsiteInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_viewsite(inputs)
	if (locale === "ja") return ja_overview_viewsite(inputs)
	return en_overview_viewsite(inputs)
});