/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Signin_ErrorInputs */

const en_auth_signin_error = /** @type {(inputs: Auth_Signin_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not log in`)
};

const zh_cn2_auth_signin_error = /** @type {(inputs: Auth_Signin_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法登录`)
};

const ja_auth_signin_error = /** @type {(inputs: Auth_Signin_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ログインできませんでした`)
};

/**
* | output |
* | --- |
* | "Could not log in" |
*
* @param {Auth_Signin_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_signin_error = /** @type {((inputs?: Auth_Signin_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Signin_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_signin_error(inputs)
	if (locale === "ja") return ja_auth_signin_error(inputs)
	return en_auth_signin_error(inputs)
});