/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Apikeys_LoaderrorInputs */

const en_settings_apikeys_loaderror = /** @type {(inputs: Settings_Apikeys_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not load API keys. Try again.`)
};

const zh_cn2_settings_apikeys_loaderror = /** @type {(inputs: Settings_Apikeys_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法加载 API 密钥。请重试。`)
};

const ja_settings_apikeys_loaderror = /** @type {(inputs: Settings_Apikeys_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`API キーをロードできませんでした。もう一度やり直してください。`)
};

/**
* | output |
* | --- |
* | "Could not load API keys. Try again." |
*
* @param {Settings_Apikeys_LoaderrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_apikeys_loaderror = /** @type {((inputs?: Settings_Apikeys_LoaderrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Apikeys_LoaderrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_apikeys_loaderror(inputs)
	if (locale === "ja") return ja_settings_apikeys_loaderror(inputs)
	return en_settings_apikeys_loaderror(inputs)
});