/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Redirects_DescriptionInputs */

const en_settings_redirects_description = /** @type {(inputs: Settings_Redirects_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Forward old paths to new ones so saved links keep working.`)
};

const zh_cn2_settings_redirects_description = /** @type {(inputs: Settings_Redirects_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`将旧路径转发到新路径，以便保存的链接继续工作。`)
};

const ja_settings_redirects_description = /** @type {(inputs: Settings_Redirects_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`保存されたリンクが機能し続けるように、古いパスを新しいパスに転送します。`)
};

/**
* | output |
* | --- |
* | "Forward old paths to new ones so saved links keep working." |
*
* @param {Settings_Redirects_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_redirects_description = /** @type {((inputs?: Settings_Redirects_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Redirects_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_redirects_description(inputs)
	if (locale === "ja") return ja_settings_redirects_description(inputs)
	return en_settings_redirects_description(inputs)
});