import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_TitleInputs */

const en_settings_import_ghost_title = /** @type {(inputs: Settings_Import_Ghost_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ghost`)
};

const zh_cn2_settings_import_ghost_title = /** @type {(inputs: Settings_Import_Ghost_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`幽灵`)
};

const ja_settings_import_ghost_title = /** @type {(inputs: Settings_Import_Ghost_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`おばけ`)
};

/**
* | output |
* | --- |
* | "Ghost" |
*
* @param {Settings_Import_Ghost_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_title = /** @type {((inputs?: Settings_Import_Ghost_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_title(inputs)
	if (locale === "ja") return ja_settings_import_ghost_title(inputs)
	return en_settings_import_ghost_title(inputs)
});