import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_TestmessageInputs */

const en_settings_integrations_testmessage = /** @type {(inputs: Settings_Integrations_TestmessageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms integration verification succeeded.`)
};

const zh_cn2_settings_integrations_testmessage = /** @type {(inputs: Settings_Integrations_TestmessageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms整合核查成功.`)
};

const ja_settings_integrations_testmessage = /** @type {(inputs: Settings_Integrations_TestmessageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms統合検証に成功しました。`)
};

/**
* | output |
* | --- |
* | "cms integration verification succeeded." |
*
* @param {Settings_Integrations_TestmessageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_testmessage = /** @type {((inputs?: Settings_Integrations_TestmessageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_TestmessageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_testmessage(inputs)
	if (locale === "ja") return ja_settings_integrations_testmessage(inputs)
	return en_settings_integrations_testmessage(inputs)
});