import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Branding_Favicon_HintInputs */

const en_settings_branding_favicon_hint = /** @type {(inputs: Settings_Branding_Favicon_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Shown in the browser tab. A 48×48 PNG or SVG works best.`)
};

const zh_cn2_settings_branding_favicon_hint = /** @type {(inputs: Settings_Branding_Favicon_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`显示在浏览器选项卡中。 48×48 PNG 或 SVG 效果最佳。`)
};

const ja_settings_branding_favicon_hint = /** @type {(inputs: Settings_Branding_Favicon_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ブラウザのタブに表示されます。 48×48 の PNG または SVG が最適です。`)
};

/**
* | output |
* | --- |
* | "Shown in the browser tab. A 48×48 PNG or SVG works best." |
*
* @param {Settings_Branding_Favicon_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_branding_favicon_hint = /** @type {((inputs?: Settings_Branding_Favicon_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Branding_Favicon_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_branding_favicon_hint(inputs)
	if (locale === "ja") return ja_settings_branding_favicon_hint(inputs)
	return en_settings_branding_favicon_hint(inputs)
});