import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Link_OpenInputs */

const en_editor_link_open = /** @type {(inputs: Editor_Link_OpenInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Open in new tab`)
};

const zh_cn2_editor_link_open = /** @type {(inputs: Editor_Link_OpenInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`在新选项卡中打开`)
};

const ja_editor_link_open = /** @type {(inputs: Editor_Link_OpenInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新しいタブで開く`)
};

/**
* | output |
* | --- |
* | "Open in new tab" |
*
* @param {Editor_Link_OpenInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_link_open = /** @type {((inputs?: Editor_Link_OpenInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Link_OpenInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_link_open(inputs)
	if (locale === "ja") return ja_editor_link_open(inputs)
	return en_editor_link_open(inputs)
});