import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown> }} Settings_Exports_Workflow_PublishedversionInputs */

const en_settings_exports_workflow_publishedversion = /** @type {(inputs: Settings_Exports_Workflow_PublishedversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Published v${i?.version}`)
};

const zh_cn2_settings_exports_workflow_publishedversion = /** @type {(inputs: Settings_Exports_Workflow_PublishedversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`已发布 v${i?.version}`)
};

const ja_settings_exports_workflow_publishedversion = /** @type {(inputs: Settings_Exports_Workflow_PublishedversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} を公開しました`)
};

/**
* | output |
* | --- |
* | "Published v{version}" |
*
* @param {Settings_Exports_Workflow_PublishedversionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_exports_workflow_publishedversion = /** @type {((inputs: Settings_Exports_Workflow_PublishedversionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Exports_Workflow_PublishedversionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_exports_workflow_publishedversion(inputs)
	if (locale === "ja") return ja_settings_exports_workflow_publishedversion(inputs)
	return en_settings_exports_workflow_publishedversion(inputs)
});