import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Command_Dialog_TitleInputs */

const en_command_dialog_title = /** @type {(inputs: Command_Dialog_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Command palette`)
};

const zh_cn2_command_dialog_title = /** @type {(inputs: Command_Dialog_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`命令面板`)
};

const ja_command_dialog_title = /** @type {(inputs: Command_Dialog_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コマンドパレット`)
};

/**
* | output |
* | --- |
* | "Command palette" |
*
* @param {Command_Dialog_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const command_dialog_title = /** @type {((inputs?: Command_Dialog_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Command_Dialog_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_command_dialog_title(inputs)
	if (locale === "ja") return ja_command_dialog_title(inputs)
	return en_command_dialog_title(inputs)
});