/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_TitleInputs */

const en_settings_domain_title = /** @type {(inputs: Settings_Domain_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Custom domain`)
};

const zh_cn2_settings_domain_title = /** @type {(inputs: Settings_Domain_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`自定义域`)
};

const ja_settings_domain_title = /** @type {(inputs: Settings_Domain_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`カスタムドメイン`)
};

/**
* | output |
* | --- |
* | "Custom domain" |
*
* @param {Settings_Domain_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_title = /** @type {((inputs?: Settings_Domain_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_title(inputs)
	if (locale === "ja") return ja_settings_domain_title(inputs)
	return en_settings_domain_title(inputs)
});