import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_ResendInputs */

const en_auth_verify_resend = /** @type {(inputs: Auth_Verify_ResendInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Resend code`)
};

const zh_cn2_auth_verify_resend = /** @type {(inputs: Auth_Verify_ResendInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`重新发送代码`)
};

const ja_auth_verify_resend = /** @type {(inputs: Auth_Verify_ResendInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コードを再送信する`)
};

/**
* | output |
* | --- |
* | "Resend code" |
*
* @param {Auth_Verify_ResendInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_resend = /** @type {((inputs?: Auth_Verify_ResendInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_ResendInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_resend(inputs)
	if (locale === "ja") return ja_auth_verify_resend(inputs)
	return en_auth_verify_resend(inputs)
});