/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_WhatchangedInputs */

const en_publish_whatchanged = /** @type {(inputs: Publish_WhatchangedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`What changed?`)
};

const zh_cn2_publish_whatchanged = /** @type {(inputs: Publish_WhatchangedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`发生了什么变化？`)
};

const ja_publish_whatchanged = /** @type {(inputs: Publish_WhatchangedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`何が変わったのでしょうか？`)
};

/**
* | output |
* | --- |
* | "What changed?" |
*
* @param {Publish_WhatchangedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_whatchanged = /** @type {((inputs?: Publish_WhatchangedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_WhatchangedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_whatchanged(inputs)
	if (locale === "ja") return ja_publish_whatchanged(inputs)
	return en_publish_whatchanged(inputs)
});