import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ days: NonNullable<unknown> }} Admin_Overview_ActivationbodyInputs */

const en_admin_overview_activationbody = /** @type {(inputs: Admin_Overview_ActivationbodyInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Last ${i?.days} days — sign-up to first successful publish (starter auto-publishes excluded)`)
};

const zh_cn2_admin_overview_activationbody = /** @type {(inputs: Admin_Overview_ActivationbodyInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Last ${i?.days} days — sign-up to first successful publish (starter auto-publishes excluded)`)
};

const ja_admin_overview_activationbody = /** @type {(inputs: Admin_Overview_ActivationbodyInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`過去 ${i?.days} 日間 — 最初に成功した公開までのサインアップ (スターター自動公開は除く)`)
};

/**
* | output |
* | --- |
* | "Last {days} days — sign-up to first successful publish (starter auto-publishes excluded)" |
*
* @param {Admin_Overview_ActivationbodyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_overview_activationbody = /** @type {((inputs: Admin_Overview_ActivationbodyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Overview_ActivationbodyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_overview_activationbody(inputs)
	if (locale === "ja") return ja_admin_overview_activationbody(inputs)
	return en_admin_overview_activationbody(inputs)
});