import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Otp_DifferentemailInputs */

const en_auth_otp_differentemail = /** @type {(inputs: Auth_Otp_DifferentemailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Change email`)
};

const zh_cn2_auth_otp_differentemail = /** @type {(inputs: Auth_Otp_DifferentemailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`更改电子邮件`)
};

const ja_auth_otp_differentemail = /** @type {(inputs: Auth_Otp_DifferentemailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`メールアドレスを変更する`)
};

/**
* | output |
* | --- |
* | "Change email" |
*
* @param {Auth_Otp_DifferentemailInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_otp_differentemail = /** @type {((inputs?: Auth_Otp_DifferentemailInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Otp_DifferentemailInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_otp_differentemail(inputs)
	if (locale === "ja") return ja_auth_otp_differentemail(inputs)
	return en_auth_otp_differentemail(inputs)
});