import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Config_HeadingInputs */

const en_editor_config_heading = /** @type {(inputs: Editor_Config_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Site settings`)
};

const zh_cn2_editor_config_heading = /** @type {(inputs: Editor_Config_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`站点设置`)
};

const ja_editor_config_heading = /** @type {(inputs: Editor_Config_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`サイト設定`)
};

/**
* | output |
* | --- |
* | "Site settings" |
*
* @param {Editor_Config_HeadingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_config_heading = /** @type {((inputs?: Editor_Config_HeadingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Config_HeadingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_config_heading(inputs)
	if (locale === "ja") return ja_editor_config_heading(inputs)
	return en_editor_config_heading(inputs)
});