/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ subject: NonNullable<unknown> }} Admin_Support_TitleInputs */

const en_admin_support_title = /** @type {(inputs: Admin_Support_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Open ${i?.subject} as a customer?`)
};

const zh_cn2_admin_support_title = /** @type {(inputs: Admin_Support_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Open ${i?.subject} as a customer?`)
};

const ja_admin_support_title = /** @type {(inputs: Admin_Support_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`顧客として ${i?.subject} を開きますか?`)
};

/**
* | output |
* | --- |
* | "Open {subject} as a customer?" |
*
* @param {Admin_Support_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_support_title = /** @type {((inputs: Admin_Support_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Support_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_support_title(inputs)
	if (locale === "ja") return ja_admin_support_title(inputs)
	return en_admin_support_title(inputs)
});