/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Editor_Branch_MergedInputs */

const en_editor_branch_merged = /** @type {(inputs: Editor_Branch_MergedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Promoted “${i?.name}” into main`)
};

const zh_cn2_editor_branch_merged = /** @type {(inputs: Editor_Branch_MergedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`将“${i?.name}”提升到主干`)
};

const ja_editor_branch_merged = /** @type {(inputs: Editor_Branch_MergedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`「${i?.name}」をメインに昇格しました`)
};

/**
* | output |
* | --- |
* | "Promoted “{name}” into main" |
*
* @param {Editor_Branch_MergedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_branch_merged = /** @type {((inputs: Editor_Branch_MergedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Branch_MergedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_branch_merged(inputs)
	if (locale === "ja") return ja_editor_branch_merged(inputs)
	return en_editor_branch_merged(inputs)
});