/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_FailedInputs */

const en_deploy_failed = /** @type {(inputs: Deploy_FailedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Deploy failed`)
};

const zh_cn2_deploy_failed = /** @type {(inputs: Deploy_FailedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`部署失败`)
};

const ja_deploy_failed = /** @type {(inputs: Deploy_FailedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`デプロイに失敗しました`)
};

/**
* | output |
* | --- |
* | "Deploy failed" |
*
* @param {Deploy_FailedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_failed = /** @type {((inputs?: Deploy_FailedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_FailedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_failed(inputs)
	if (locale === "ja") return ja_deploy_failed(inputs)
	return en_deploy_failed(inputs)
});