/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_PublishedInputs */

const en_deploy_published = /** @type {(inputs: Deploy_PublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Published — your site is live`)
};

const zh_cn2_deploy_published = /** @type {(inputs: Deploy_PublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已发布 — 您的网站已上线`)
};

const ja_deploy_published = /** @type {(inputs: Deploy_PublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公開済み — サイトは公開中です`)
};

/**
* | output |
* | --- |
* | "Published — your site is live" |
*
* @param {Deploy_PublishedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_published = /** @type {((inputs?: Deploy_PublishedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_PublishedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_published(inputs)
	if (locale === "ja") return ja_deploy_published(inputs)
	return en_deploy_published(inputs)
});