import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ImportplaceholderInputs */

const en_settings_theme_importplaceholder = /** @type {(inputs: Settings_Theme_ImportplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Paste a cms-theme JSON template to inspect it…`)
};

const zh_cn2_settings_theme_importplaceholder = /** @type {(inputs: Settings_Theme_ImportplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`粘贴 cms 主题 JSON 模板来检查它......`)
};

const ja_settings_theme_importplaceholder = /** @type {(inputs: Settings_Theme_ImportplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms-theme の JSON テンプレートを貼り付けて検査します…`)
};

/**
* | output |
* | --- |
* | "Paste a cms-theme JSON template to inspect it…" |
*
* @param {Settings_Theme_ImportplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_importplaceholder = /** @type {((inputs?: Settings_Theme_ImportplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ImportplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_importplaceholder(inputs)
	if (locale === "ja") return ja_settings_theme_importplaceholder(inputs)
	return en_settings_theme_importplaceholder(inputs)
});