/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_PublishhintInputs */

const en_settings_import_publishhint = /** @type {(inputs: Settings_Import_PublishhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Imported content is not live yet — publish from the editor to update your site.`)
};

const zh_cn2_settings_import_publishhint = /** @type {(inputs: Settings_Import_PublishhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导入的内容尚未生效 - 从编辑器发布以更新您的网站。`)
};

const ja_settings_import_publishhint = /** @type {(inputs: Settings_Import_PublishhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`インポートされたコンテンツはまだ公開されていません。エディターから公開してサイトを更新してください。`)
};

/**
* | output |
* | --- |
* | "Imported content is not live yet — publish from the editor to update your site." |
*
* @param {Settings_Import_PublishhintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_publishhint = /** @type {((inputs?: Settings_Import_PublishhintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_PublishhintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_publishhint(inputs)
	if (locale === "ja") return ja_settings_import_publishhint(inputs)
	return en_settings_import_publishhint(inputs)
});