import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_AddInputs */

const en_settings_domain_add = /** @type {(inputs: Settings_Domain_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add domain`)
};

const zh_cn2_settings_domain_add = /** @type {(inputs: Settings_Domain_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`添加域名`)
};

const ja_settings_domain_add = /** @type {(inputs: Settings_Domain_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドメインの追加`)
};

/**
* | output |
* | --- |
* | "Add domain" |
*
* @param {Settings_Domain_AddInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_add = /** @type {((inputs?: Settings_Domain_AddInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_AddInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_add(inputs)
	if (locale === "ja") return ja_settings_domain_add(inputs)
	return en_settings_domain_add(inputs)
});