import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Addons_LoaderrorInputs */

const en_settings_addons_loaderror = /** @type {(inputs: Settings_Addons_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add-ons could not be loaded. Try again.`)
};

const zh_cn2_settings_addons_loaderror = /** @type {(inputs: Settings_Addons_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法加载附加功能。请重试。`)
};

const ja_settings_addons_loaderror = /** @type {(inputs: Settings_Addons_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`アドオンをロードできませんでした。もう一度やり直してください。`)
};

/**
* | output |
* | --- |
* | "Add-ons could not be loaded. Try again." |
*
* @param {Settings_Addons_LoaderrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_addons_loaderror = /** @type {((inputs?: Settings_Addons_LoaderrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Addons_LoaderrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_addons_loaderror(inputs)
	if (locale === "ja") return ja_settings_addons_loaderror(inputs)
	return en_settings_addons_loaderror(inputs)
});