import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Command_SearchplaceholderInputs */

const en_command_searchplaceholder = /** @type {(inputs: Command_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search projects and actions…`)
};

const zh_cn2_command_searchplaceholder = /** @type {(inputs: Command_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`搜索项目和行动...`)
};

const ja_command_searchplaceholder = /** @type {(inputs: Command_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`プロジェクトとアクションを検索…`)
};

/**
* | output |
* | --- |
* | "Search projects and actions…" |
*
* @param {Command_SearchplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const command_searchplaceholder = /** @type {((inputs?: Command_SearchplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Command_SearchplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_command_searchplaceholder(inputs)
	if (locale === "ja") return ja_command_searchplaceholder(inputs)
	return en_command_searchplaceholder(inputs)
});