import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_SummaryhintInputs */

const en_settings_import_summaryhint = /** @type {(inputs: Settings_Import_SummaryhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Pages are added or updated in this project — nothing is deleted, and re-running the import is safe.`)
};

const zh_cn2_settings_import_summaryhint = /** @type {(inputs: Settings_Import_SummaryhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`在此项目中添加或更新页面 - 不会删除任何内容，并且重新运行导入是安全的。`)
};

const ja_settings_import_summaryhint = /** @type {(inputs: Settings_Import_SummaryhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このプロジェクトではページが追加または更新されます。何も削除されず、インポートを再実行しても安全です。`)
};

/**
* | output |
* | --- |
* | "Pages are added or updated in this project — nothing is deleted, and re-running the import is safe." |
*
* @param {Settings_Import_SummaryhintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_summaryhint = /** @type {((inputs?: Settings_Import_SummaryhintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_SummaryhintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_summaryhint(inputs)
	if (locale === "ja") return ja_settings_import_summaryhint(inputs)
	return en_settings_import_summaryhint(inputs)
});