import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Settings_Languages_Coverage_SourcepagesInputs */

const en_settings_languages_coverage_sourcepages = /** @type {(inputs: Settings_Languages_Coverage_SourcepagesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} source pages`)
};

const zh_cn2_settings_languages_coverage_sourcepages = /** @type {(inputs: Settings_Languages_Coverage_SourcepagesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 源页面`)
};

const ja_settings_languages_coverage_sourcepages = /** @type {(inputs: Settings_Languages_Coverage_SourcepagesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} ソース ページ`)
};

/**
* | output |
* | --- |
* | "{count} source pages" |
*
* @param {Settings_Languages_Coverage_SourcepagesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_coverage_sourcepages = /** @type {((inputs: Settings_Languages_Coverage_SourcepagesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_Coverage_SourcepagesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_coverage_sourcepages(inputs)
	if (locale === "ja") return ja_settings_languages_coverage_sourcepages(inputs)
	return en_settings_languages_coverage_sourcepages(inputs)
});