/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Signup_ErrorInputs */

const en_auth_signup_error = /** @type {(inputs: Auth_Signup_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not create account`)
};

const zh_cn2_auth_signup_error = /** @type {(inputs: Auth_Signup_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法创建帐户`)
};

const ja_auth_signup_error = /** @type {(inputs: Auth_Signup_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`アカウントを作成できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not create account" |
*
* @param {Auth_Signup_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_signup_error = /** @type {((inputs?: Auth_Signup_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Signup_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_signup_error(inputs)
	if (locale === "ja") return ja_auth_signup_error(inputs)
	return en_auth_signup_error(inputs)
});