import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Newsite_CreatedInputs */

const en_newsite_created = /** @type {(inputs: Newsite_CreatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Project created`)
};

const zh_cn2_newsite_created = /** @type {(inputs: Newsite_CreatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`项目已创建`)
};

const ja_newsite_created = /** @type {(inputs: Newsite_CreatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`プロジェクトが作成されました`)
};

/**
* | output |
* | --- |
* | "Project created" |
*
* @param {Newsite_CreatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const newsite_created = /** @type {((inputs?: Newsite_CreatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Newsite_CreatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_newsite_created(inputs)
	if (locale === "ja") return ja_newsite_created(inputs)
	return en_newsite_created(inputs)
});