/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Import_ErrorInputs */

const en_settings_git_import_error = /** @type {(inputs: Settings_Git_Import_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not import from Git`)
};

const zh_cn2_settings_git_import_error = /** @type {(inputs: Settings_Git_Import_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法从 Git 导入`)
};

const ja_settings_git_import_error = /** @type {(inputs: Settings_Git_Import_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Git からインポートできませんでした`)
};

/**
* | output |
* | --- |
* | "Could not import from Git" |
*
* @param {Settings_Git_Import_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_import_error = /** @type {((inputs?: Settings_Git_Import_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Import_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_import_error(inputs)
	if (locale === "ja") return ja_settings_git_import_error(inputs)
	return en_settings_git_import_error(inputs)
});