/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Addlanguage_ErrorInputs */

const en_editor_addlanguage_error = /** @type {(inputs: Editor_Addlanguage_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not add the language.`)
};

const zh_cn2_editor_addlanguage_error = /** @type {(inputs: Editor_Addlanguage_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法添加语言。`)
};

const ja_editor_addlanguage_error = /** @type {(inputs: Editor_Addlanguage_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を追加できませんでした。`)
};

/**
* | output |
* | --- |
* | "Could not add the language." |
*
* @param {Editor_Addlanguage_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_addlanguage_error = /** @type {((inputs?: Editor_Addlanguage_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Addlanguage_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_addlanguage_error(inputs)
	if (locale === "ja") return ja_editor_addlanguage_error(inputs)
	return en_editor_addlanguage_error(inputs)
});