import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Admin_Data_UnavailableInputs */

const en_admin_data_unavailable = /** @type {(inputs: Admin_Data_UnavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Unable to load data`)
};

const zh_cn2_admin_data_unavailable = /** @type {(inputs: Admin_Data_UnavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Unable to load data`)
};

const ja_admin_data_unavailable = /** @type {(inputs: Admin_Data_UnavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`データをロードできません`)
};

/**
* | output |
* | --- |
* | "Unable to load data" |
*
* @param {Admin_Data_UnavailableInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_data_unavailable = /** @type {((inputs?: Admin_Data_UnavailableInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Data_UnavailableInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_data_unavailable(inputs)
	if (locale === "ja") return ja_admin_data_unavailable(inputs)
	return en_admin_data_unavailable(inputs)
});