/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ReplaceInputs */

const en_settings_theme_replace = /** @type {(inputs: Settings_Theme_ReplaceInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Replace theme`)
};

const zh_cn2_settings_theme_replace = /** @type {(inputs: Settings_Theme_ReplaceInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`更换主题`)
};

const ja_settings_theme_replace = /** @type {(inputs: Settings_Theme_ReplaceInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`テーマを置き換える`)
};

/**
* | output |
* | --- |
* | "Replace theme" |
*
* @param {Settings_Theme_ReplaceInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_replace = /** @type {((inputs?: Settings_Theme_ReplaceInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ReplaceInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_replace(inputs)
	if (locale === "ja") return ja_settings_theme_replace(inputs)
	return en_settings_theme_replace(inputs)
});