/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ tags: NonNullable<unknown> }} Editor_Unsupportedmdx_BannerInputs */

const en_editor_unsupportedmdx_banner = /** @type {(inputs: Editor_Unsupportedmdx_BannerInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Unsupported MDX blocks (${i?.tags}) are read-only in place and their source is preserved. The rest of the page and anchored comments remain editable.`)
};

const zh_cn2_editor_unsupportedmdx_banner = /** @type {(inputs: Editor_Unsupportedmdx_BannerInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`不支持的 MDX 块 (${i?.tags}) 是只读的，并且它们的源被保留。页面的其余部分和锚定评论仍然可编辑。`)
};

const ja_editor_unsupportedmdx_banner = /** @type {(inputs: Editor_Unsupportedmdx_BannerInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`サポートされていない MDX ブロック (${i?.tags}) は読み取り専用であり、そのソースは保持されます。ページの残りの部分とアンカーされたコメントは編集可能なままです。`)
};

/**
* | output |
* | --- |
* | "Unsupported MDX blocks ({tags}) are read-only in place and their source is preserved. The rest of the page and anchored comments remain editable." |
*
* @param {Editor_Unsupportedmdx_BannerInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_unsupportedmdx_banner = /** @type {((inputs: Editor_Unsupportedmdx_BannerInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Unsupportedmdx_BannerInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_unsupportedmdx_banner(inputs)
	if (locale === "ja") return ja_editor_unsupportedmdx_banner(inputs)
	return en_editor_unsupportedmdx_banner(inputs)
});