/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Addlanguage_PlaceholderInputs */

const en_editor_addlanguage_placeholder = /** @type {(inputs: Editor_Addlanguage_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Select a language…`)
};

const zh_cn2_editor_addlanguage_placeholder = /** @type {(inputs: Editor_Addlanguage_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择一种语言...`)
};

const ja_editor_addlanguage_placeholder = /** @type {(inputs: Editor_Addlanguage_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を選択してください…`)
};

/**
* | output |
* | --- |
* | "Select a language…" |
*
* @param {Editor_Addlanguage_PlaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_addlanguage_placeholder = /** @type {((inputs?: Editor_Addlanguage_PlaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Addlanguage_PlaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_addlanguage_placeholder(inputs)
	if (locale === "ja") return ja_editor_addlanguage_placeholder(inputs)
	return en_editor_addlanguage_placeholder(inputs)
});