/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Newsite_TitleInputs */

const en_newsite_title = /** @type {(inputs: Newsite_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`New documentation site`)
};

const zh_cn2_newsite_title = /** @type {(inputs: Newsite_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新文档站点`)
};

const ja_newsite_title = /** @type {(inputs: Newsite_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新しいドキュメント サイト`)
};

/**
* | output |
* | --- |
* | "New documentation site" |
*
* @param {Newsite_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const newsite_title = /** @type {((inputs?: Newsite_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Newsite_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_newsite_title(inputs)
	if (locale === "ja") return ja_newsite_title(inputs)
	return en_newsite_title(inputs)
});