import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Admin_LabelInputs */

const en_admin_label = /** @type {(inputs: Admin_LabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Admin`)
};

const zh_cn2_admin_label = /** @type {(inputs: Admin_LabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Admin`)
};

const ja_admin_label = /** @type {(inputs: Admin_LabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`管理者`)
};

/**
* | output |
* | --- |
* | "Admin" |
*
* @param {Admin_LabelInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_label = /** @type {((inputs?: Admin_LabelInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_LabelInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_label(inputs)
	if (locale === "ja") return ja_admin_label(inputs)
	return en_admin_label(inputs)
});