/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Otp_HintInputs */

const en_auth_otp_hint = /** @type {(inputs: Auth_Otp_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The code expires in 10 minutes and can be used once.`)
};

const zh_cn2_auth_otp_hint = /** @type {(inputs: Auth_Otp_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`该代码10分钟后过期，只能使用一次。`)
};

const ja_auth_otp_hint = /** @type {(inputs: Auth_Otp_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コードの有効期限は 10 分で、使用できるのは 1 回だけです。`)
};

/**
* | output |
* | --- |
* | "The code expires in 10 minutes and can be used once." |
*
* @param {Auth_Otp_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_otp_hint = /** @type {((inputs?: Auth_Otp_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Otp_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_otp_hint(inputs)
	if (locale === "ja") return ja_auth_otp_hint(inputs)
	return en_auth_otp_hint(inputs)
});