import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Admin_Site_FailedattemptsInputs */

const en_admin_site_failedattempts = /** @type {(inputs: Admin_Site_FailedattemptsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} failed attempts are visible in this 30-deployment window.`)
};

const zh_cn2_admin_site_failedattempts = /** @type {(inputs: Admin_Site_FailedattemptsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最近 30 次部署中有 ${i?.count} 次失败尝试。`)
};

const ja_admin_site_failedattempts = /** @type {(inputs: Admin_Site_FailedattemptsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`この 30 の展開ウィンドウには、失敗した試行 ${i?.count} 件が表示されます。`)
};

/**
* | output |
* | --- |
* | "{count} failed attempts are visible in this 30-deployment window." |
*
* @param {Admin_Site_FailedattemptsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_site_failedattempts = /** @type {((inputs: Admin_Site_FailedattemptsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Site_FailedattemptsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_site_failedattempts(inputs)
	if (locale === "ja") return ja_admin_site_failedattempts(inputs)
	return en_admin_site_failedattempts(inputs)
});