/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Validation_EmailrequiredInputs */

const en_validation_emailrequired = /** @type {(inputs: Validation_EmailrequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Email is required`)
};

const zh_cn2_validation_emailrequired = /** @type {(inputs: Validation_EmailrequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`电子邮件为必填项`)
};

const ja_validation_emailrequired = /** @type {(inputs: Validation_EmailrequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`メールアドレスは必須です`)
};

/**
* | output |
* | --- |
* | "Email is required" |
*
* @param {Validation_EmailrequiredInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const validation_emailrequired = /** @type {((inputs?: Validation_EmailrequiredInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Validation_EmailrequiredInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_validation_emailrequired(inputs)
	if (locale === "ja") return ja_validation_emailrequired(inputs)
	return en_validation_emailrequired(inputs)
});