/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Account_Language_DescriptionInputs */

const en_account_language_description = /** @type {(inputs: Account_Language_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose the language used for navigation, forms, and actions.`)
};

const zh_cn2_account_language_description = /** @type {(inputs: Account_Language_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择用于导航、表单和操作的语言。`)
};

const ja_account_language_description = /** @type {(inputs: Account_Language_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ナビゲーション、フォーム、アクションに使用する言語を選択します。`)
};

/**
* | output |
* | --- |
* | "Choose the language used for navigation, forms, and actions." |
*
* @param {Account_Language_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const account_language_description = /** @type {((inputs?: Account_Language_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Account_Language_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_account_language_description(inputs)
	if (locale === "ja") return ja_account_language_description(inputs)
	return en_account_language_description(inputs)
});