/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ minutes: NonNullable<unknown> }} Blog_ReadingminutesInputs */

const en_blog_readingminutes = /** @type {(inputs: Blog_ReadingminutesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.minutes} min read`)
};

const zh_cn2_blog_readingminutes = /** @type {(inputs: Blog_ReadingminutesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.minutes} min read`)
};

const ja_blog_readingminutes = /** @type {(inputs: Blog_ReadingminutesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`__VAR_ minutes__ 分の読み取り時間 ${i?.minutes}`)
};

/**
* | output |
* | --- |
* | "{minutes} min read" |
*
* @param {Blog_ReadingminutesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_readingminutes = /** @type {((inputs: Blog_ReadingminutesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_ReadingminutesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_readingminutes(inputs)
	if (locale === "ja") return ja_blog_readingminutes(inputs)
	return en_blog_readingminutes(inputs)
});