import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Seo_Allowindex_TitleInputs */

const en_settings_seo_allowindex_title = /** @type {(inputs: Settings_Seo_Allowindex_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Allow search engines`)
};

const zh_cn2_settings_seo_allowindex_title = /** @type {(inputs: Settings_Seo_Allowindex_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`允许搜索引擎`)
};

const ja_settings_seo_allowindex_title = /** @type {(inputs: Settings_Seo_Allowindex_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検索エンジンを許可する`)
};

/**
* | output |
* | --- |
* | "Allow search engines" |
*
* @param {Settings_Seo_Allowindex_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_seo_allowindex_title = /** @type {((inputs?: Settings_Seo_Allowindex_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Seo_Allowindex_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_seo_allowindex_title(inputs)
	if (locale === "ja") return ja_settings_seo_allowindex_title(inputs)
	return en_settings_seo_allowindex_title(inputs)
});