/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Command_NoresultsInputs */

const en_command_noresults = /** @type {(inputs: Command_NoresultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No results found.`)
};

const zh_cn2_command_noresults = /** @type {(inputs: Command_NoresultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`没有找到结果。`)
};

const ja_command_noresults = /** @type {(inputs: Command_NoresultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`結果が見つかりませんでした。`)
};

/**
* | output |
* | --- |
* | "No results found." |
*
* @param {Command_NoresultsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const command_noresults = /** @type {((inputs?: Command_NoresultsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Command_NoresultsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_command_noresults(inputs)
	if (locale === "ja") return ja_command_noresults(inputs)
	return en_command_noresults(inputs)
});