/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_NopageselectedInputs */

const en_editor_nopageselected = /** @type {(inputs: Editor_NopageselectedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No page selected`)
};

const zh_cn2_editor_nopageselected = /** @type {(inputs: Editor_NopageselectedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`未选择页面`)
};

const ja_editor_nopageselected = /** @type {(inputs: Editor_NopageselectedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ページが選択されていません`)
};

/**
* | output |
* | --- |
* | "No page selected" |
*
* @param {Editor_NopageselectedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_nopageselected = /** @type {((inputs?: Editor_NopageselectedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_NopageselectedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_nopageselected(inputs)
	if (locale === "ja") return ja_editor_nopageselected(inputs)
	return en_editor_nopageselected(inputs)
});