/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Preview_DisabledInputs */

const en_preview_disabled = /** @type {(inputs: Preview_DisabledInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Preview deployments are disabled for this site.`)
};

const zh_cn2_preview_disabled = /** @type {(inputs: Preview_DisabledInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`此站点禁用预览部署。`)
};

const ja_preview_disabled = /** @type {(inputs: Preview_DisabledInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このサイトではプレビュー展開が無効になっています。`)
};

/**
* | output |
* | --- |
* | "Preview deployments are disabled for this site." |
*
* @param {Preview_DisabledInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const preview_disabled = /** @type {((inputs?: Preview_DisabledInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Preview_DisabledInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_preview_disabled(inputs)
	if (locale === "ja") return ja_preview_disabled(inputs)
	return en_preview_disabled(inputs)
});