/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_UntitledInputs */

const en_editor_untitled = /** @type {(inputs: Editor_UntitledInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Untitled`)
};

const zh_cn2_editor_untitled = /** @type {(inputs: Editor_UntitledInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无标题`)
};

const ja_editor_untitled = /** @type {(inputs: Editor_UntitledInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`無題`)
};

/**
* | output |
* | --- |
* | "Untitled" |
*
* @param {Editor_UntitledInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_untitled = /** @type {((inputs?: Editor_UntitledInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_UntitledInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_untitled(inputs)
	if (locale === "ja") return ja_editor_untitled(inputs)
	return en_editor_untitled(inputs)
});