/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Editor_Opaquemdx_TooltipInputs */

const en_editor_opaquemdx_tooltip = /** @type {(inputs: Editor_Opaquemdx_TooltipInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.name}: source preserved; edit in Markdown mode`)
};

const zh_cn2_editor_opaquemdx_tooltip = /** @type {(inputs: Editor_Opaquemdx_TooltipInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.name}：已保留源码；请在 Markdown 模式下编辑`)
};

const ja_editor_opaquemdx_tooltip = /** @type {(inputs: Editor_Opaquemdx_TooltipInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.name}: source preserved;マークダウンモードで編集する`)
};

/**
* | output |
* | --- |
* | "{name}: source preserved; edit in Markdown mode" |
*
* @param {Editor_Opaquemdx_TooltipInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_opaquemdx_tooltip = /** @type {((inputs: Editor_Opaquemdx_TooltipInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Opaquemdx_TooltipInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_opaquemdx_tooltip(inputs)
	if (locale === "ja") return ja_editor_opaquemdx_tooltip(inputs)
	return en_editor_opaquemdx_tooltip(inputs)
});