import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_General_Translations_TitleInputs */

const en_settings_general_translations_title = /** @type {(inputs: Settings_General_Translations_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Translations`)
};

const zh_cn2_settings_general_translations_title = /** @type {(inputs: Settings_General_Translations_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`翻译`)
};

const ja_settings_general_translations_title = /** @type {(inputs: Settings_General_Translations_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`翻訳`)
};

/**
* | output |
* | --- |
* | "Translations" |
*
* @param {Settings_General_Translations_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_general_translations_title = /** @type {((inputs?: Settings_General_Translations_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_General_Translations_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_general_translations_title(inputs)
	if (locale === "ja") return ja_settings_general_translations_title(inputs)
	return en_settings_general_translations_title(inputs)
});