import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Settings_Danger_Delete_ConfirmInputs */

const en_settings_danger_delete_confirm = /** @type {(inputs: Settings_Danger_Delete_ConfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Delete “${i?.name}” and all its content? This cannot be undone.`)
};

const zh_cn2_settings_danger_delete_confirm = /** @type {(inputs: Settings_Danger_Delete_ConfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`删除“${i?.name}”及其所有内容？此操作无法撤消。`)
};

const ja_settings_danger_delete_confirm = /** @type {(inputs: Settings_Danger_Delete_ConfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`「${i?.name}」とそのすべてのコンテンツを削除しますか?これを元に戻すことはできません。`)
};

/**
* | output |
* | --- |
* | "Delete “{name}” and all its content? This cannot be undone." |
*
* @param {Settings_Danger_Delete_ConfirmInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_danger_delete_confirm = /** @type {((inputs: Settings_Danger_Delete_ConfirmInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Danger_Delete_ConfirmInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_danger_delete_confirm(inputs)
	if (locale === "ja") return ja_settings_danger_delete_confirm(inputs)
	return en_settings_danger_delete_confirm(inputs)
});