import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_OpeneditorInputs */

const en_overview_openeditor = /** @type {(inputs: Overview_OpeneditorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Open editor`)
};

const zh_cn2_overview_openeditor = /** @type {(inputs: Overview_OpeneditorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`打开编辑器`)
};

const ja_overview_openeditor = /** @type {(inputs: Overview_OpeneditorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`エディタを開く`)
};

/**
* | output |
* | --- |
* | "Open editor" |
*
* @param {Overview_OpeneditorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_openeditor = /** @type {((inputs?: Overview_OpeneditorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_OpeneditorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_openeditor(inputs)
	if (locale === "ja") return ja_overview_openeditor(inputs)
	return en_overview_openeditor(inputs)
});