import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Usage_NolimitInputs */

const en_settings_usage_nolimit = /** @type {(inputs: Settings_Usage_NolimitInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No limit during beta`)
};

const zh_cn2_settings_usage_nolimit = /** @type {(inputs: Settings_Usage_NolimitInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`测试期间没有限制`)
};

const ja_settings_usage_nolimit = /** @type {(inputs: Settings_Usage_NolimitInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ベータ期間中は制限なし`)
};

/**
* | output |
* | --- |
* | "No limit during beta" |
*
* @param {Settings_Usage_NolimitInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage_nolimit = /** @type {((inputs?: Settings_Usage_NolimitInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Usage_NolimitInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage_nolimit(inputs)
	if (locale === "ja") return ja_settings_usage_nolimit(inputs)
	return en_settings_usage_nolimit(inputs)
});