import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Variables_AddInputs */

const en_settings_variables_add = /** @type {(inputs: Settings_Variables_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add variable`)
};

const zh_cn2_settings_variables_add = /** @type {(inputs: Settings_Variables_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`添加变量`)
};

const ja_settings_variables_add = /** @type {(inputs: Settings_Variables_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`変数の追加`)
};

/**
* | output |
* | --- |
* | "Add variable" |
*
* @param {Settings_Variables_AddInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_variables_add = /** @type {((inputs?: Settings_Variables_AddInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Variables_AddInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_variables_add(inputs)
	if (locale === "ja") return ja_settings_variables_add(inputs)
	return en_settings_variables_add(inputs)
});