import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_CtabodyInputs */

const en_blog_ctabody = /** @type {(inputs: Blog_CtabodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Start free on cms Cloud, or run the public AGPL release on your own infrastructure.`)
};

const zh_cn2_blog_ctabody = /** @type {(inputs: Blog_CtabodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Start free on cms Cloud, or run the public AGPL release on your own infrastructure.`)
};

const ja_blog_ctabody = /** @type {(inputs: Blog_CtabodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms クラウドで無料で開始するか、独自のインフラストラクチャでパブリック AGPL リリースを実行します。`)
};

/**
* | output |
* | --- |
* | "Start free on cms Cloud, or run the public AGPL release on your own infrastructure." |
*
* @param {Blog_CtabodyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_ctabody = /** @type {((inputs?: Blog_CtabodyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_CtabodyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_ctabody(inputs)
	if (locale === "ja") return ja_blog_ctabody(inputs)
	return en_blog_ctabody(inputs)
});