/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_General_Translations_HintInputs */

const en_settings_general_translations_hint = /** @type {(inputs: Settings_General_Translations_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Localized site name and description for each additional language, shown on the published site in that language.`)
};

const zh_cn2_settings_general_translations_hint = /** @type {(inputs: Settings_General_Translations_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`每种附加语言的本地化站点名称和说明，以该语言显示在已发布的站点上。`)
};

const ja_settings_general_translations_hint = /** @type {(inputs: Settings_General_Translations_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`追加言語ごとにローカライズされたサイト名と説明。公開サイトにその言語で表示されます。`)
};

/**
* | output |
* | --- |
* | "Localized site name and description for each additional language, shown on the published site in that language." |
*
* @param {Settings_General_Translations_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_general_translations_hint = /** @type {((inputs?: Settings_General_Translations_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_General_Translations_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_general_translations_hint(inputs)
	if (locale === "ja") return ja_settings_general_translations_hint(inputs)
	return en_settings_general_translations_hint(inputs)
});