/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Dashboard_Empty_CtaInputs */

const en_dashboard_empty_cta = /** @type {(inputs: Dashboard_Empty_CtaInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Create your first site`)
};

const zh_cn2_dashboard_empty_cta = /** @type {(inputs: Dashboard_Empty_CtaInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`创建您的第一个网站`)
};

const ja_dashboard_empty_cta = /** @type {(inputs: Dashboard_Empty_CtaInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`最初のサイトを作成する`)
};

/**
* | output |
* | --- |
* | "Create your first site" |
*
* @param {Dashboard_Empty_CtaInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const dashboard_empty_cta = /** @type {((inputs?: Dashboard_Empty_CtaInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Dashboard_Empty_CtaInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_dashboard_empty_cta(inputs)
	if (locale === "ja") return ja_dashboard_empty_cta(inputs)
	return en_dashboard_empty_cta(inputs)
});