/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_ExpandInputs */

const en_editor_expand = /** @type {(inputs: Editor_ExpandInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Expand`)
};

const zh_cn2_editor_expand = /** @type {(inputs: Editor_ExpandInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`展开`)
};

const ja_editor_expand = /** @type {(inputs: Editor_ExpandInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`拡大する`)
};

/**
* | output |
* | --- |
* | "Expand" |
*
* @param {Editor_ExpandInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_expand = /** @type {((inputs?: Editor_ExpandInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_ExpandInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_expand(inputs)
	if (locale === "ja") return ja_editor_expand(inputs)
	return en_editor_expand(inputs)
});