/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Google_SigninInputs */

const en_auth_google_signin = /** @type {(inputs: Auth_Google_SigninInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Log in with Google`)
};

const zh_cn2_auth_google_signin = /** @type {(inputs: Auth_Google_SigninInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`使用 Google 登录`)
};

const ja_auth_google_signin = /** @type {(inputs: Auth_Google_SigninInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Googleでログイン`)
};

/**
* | output |
* | --- |
* | "Log in with Google" |
*
* @param {Auth_Google_SigninInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_google_signin = /** @type {((inputs?: Auth_Google_SigninInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Google_SigninInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_google_signin(inputs)
	if (locale === "ja") return ja_auth_google_signin(inputs)
	return en_auth_google_signin(inputs)
});