/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_EmptyInputs */

const en_settings_domain_empty = /** @type {(inputs: Settings_Domain_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No custom domains yet.`)
};

const zh_cn2_settings_domain_empty = /** @type {(inputs: Settings_Domain_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`还没有自定义域。`)
};

const ja_settings_domain_empty = /** @type {(inputs: Settings_Domain_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`カスタム ドメインはまだありません。`)
};

/**
* | output |
* | --- |
* | "No custom domains yet." |
*
* @param {Settings_Domain_EmptyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_empty = /** @type {((inputs?: Settings_Domain_EmptyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_EmptyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_empty(inputs)
	if (locale === "ja") return ja_settings_domain_empty(inputs)
	return en_settings_domain_empty(inputs)
});