import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ExporttitleInputs */

const en_settings_theme_exporttitle = /** @type {(inputs: Settings_Theme_ExporttitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Export and share`)
};

const zh_cn2_settings_theme_exporttitle = /** @type {(inputs: Settings_Theme_ExporttitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导出并分享`)
};

const ja_settings_theme_exporttitle = /** @type {(inputs: Settings_Theme_ExporttitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`エクスポートして共有する`)
};

/**
* | output |
* | --- |
* | "Export and share" |
*
* @param {Settings_Theme_ExporttitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_exporttitle = /** @type {((inputs?: Settings_Theme_ExporttitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ExporttitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_exporttitle(inputs)
	if (locale === "ja") return ja_settings_theme_exporttitle(inputs)
	return en_settings_theme_exporttitle(inputs)
});