/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Brand_DescriptionInputs */

const en_auth_brand_description = /** @type {(inputs: Auth_Brand_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms Cloud gives teams a polished Markdown workflow, instant search, analytics, custom domains, and managed infrastructure.`)
};

const zh_cn2_auth_brand_description = /** @type {(inputs: Auth_Brand_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms 云为团队提供了完善的 Markdown 工作流程、即时搜索、分析、自定义域和托管基础设施。`)
};

const ja_auth_brand_description = /** @type {(inputs: Auth_Brand_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms クラウドは、チームに洗練された Markdown ワークフロー、インスタント検索、分析、カスタム ドメイン、およびマネージド インフラストラクチャを提供します。`)
};

/**
* | output |
* | --- |
* | "cms Cloud gives teams a polished Markdown workflow, instant search, analytics, custom domains, and managed infrastructure." |
*
* @param {Auth_Brand_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_brand_description = /** @type {((inputs?: Auth_Brand_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Brand_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_brand_description(inputs)
	if (locale === "ja") return ja_auth_brand_description(inputs)
	return en_auth_brand_description(inputs)
});