/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown> }} Deploy_Rollback_SuccessInputs */

const en_deploy_rollback_success = /** @type {(inputs: Deploy_Rollback_SuccessInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Rolled back to v${i?.version}`)
};

const zh_cn2_deploy_rollback_success = /** @type {(inputs: Deploy_Rollback_SuccessInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`回滚到 v${i?.version}`)
};

const ja_deploy_rollback_success = /** @type {(inputs: Deploy_Rollback_SuccessInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} にロールバックされました`)
};

/**
* | output |
* | --- |
* | "Rolled back to v{version}" |
*
* @param {Deploy_Rollback_SuccessInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_rollback_success = /** @type {((inputs: Deploy_Rollback_SuccessInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_Rollback_SuccessInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_rollback_success(inputs)
	if (locale === "ja") return ja_deploy_rollback_success(inputs)
	return en_deploy_rollback_success(inputs)
});