/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Languages_AddInputs */

const en_settings_languages_add = /** @type {(inputs: Settings_Languages_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add language`)
};

const zh_cn2_settings_languages_add = /** @type {(inputs: Settings_Languages_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`添加语言`)
};

const ja_settings_languages_add = /** @type {(inputs: Settings_Languages_AddInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を追加する`)
};

/**
* | output |
* | --- |
* | "Add language" |
*
* @param {Settings_Languages_AddInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_add = /** @type {((inputs?: Settings_Languages_AddInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_AddInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_add(inputs)
	if (locale === "ja") return ja_settings_languages_add(inputs)
	return en_settings_languages_add(inputs)
});