/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ label: NonNullable<unknown> }} Settings_Languages_Deleteconfirm_TitleInputs */

const en_settings_languages_deleteconfirm_title = /** @type {(inputs: Settings_Languages_Deleteconfirm_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Delete ${i?.label}?`)
};

const zh_cn2_settings_languages_deleteconfirm_title = /** @type {(inputs: Settings_Languages_Deleteconfirm_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`删除${i?.label}？`)
};

const ja_settings_languages_deleteconfirm_title = /** @type {(inputs: Settings_Languages_Deleteconfirm_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.label} を削除しますか?`)
};

/**
* | output |
* | --- |
* | "Delete {label}?" |
*
* @param {Settings_Languages_Deleteconfirm_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_deleteconfirm_title = /** @type {((inputs: Settings_Languages_Deleteconfirm_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_Deleteconfirm_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_deleteconfirm_title(inputs)
	if (locale === "ja") return ja_settings_languages_deleteconfirm_title(inputs)
	return en_settings_languages_deleteconfirm_title(inputs)
});