import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_UrlInputs */

const en_settings_import_ghost_url = /** @type {(inputs: Settings_Import_Ghost_UrlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ghost site URL`)
};

const zh_cn2_settings_import_ghost_url = /** @type {(inputs: Settings_Import_Ghost_UrlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`幽灵网站网址`)
};

const ja_settings_import_ghost_url = /** @type {(inputs: Settings_Import_Ghost_UrlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ゴーストサイトのURL`)
};

/**
* | output |
* | --- |
* | "Ghost site URL" |
*
* @param {Settings_Import_Ghost_UrlInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_url = /** @type {((inputs?: Settings_Import_Ghost_UrlInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_UrlInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_url(inputs)
	if (locale === "ja") return ja_settings_import_ghost_url(inputs)
	return en_settings_import_ghost_url(inputs)
});