import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Redirects_InvalidInputs */

const en_settings_redirects_invalid = /** @type {(inputs: Settings_Redirects_InvalidInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Fix these redirect rules before saving`)
};

const zh_cn2_settings_redirects_invalid = /** @type {(inputs: Settings_Redirects_InvalidInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`保存前修复这些重定向规则`)
};

const ja_settings_redirects_invalid = /** @type {(inputs: Settings_Redirects_InvalidInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`保存する前にこれらのリダイレクト ルールを修正してください`)
};

/**
* | output |
* | --- |
* | "Fix these redirect rules before saving" |
*
* @param {Settings_Redirects_InvalidInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_redirects_invalid = /** @type {((inputs?: Settings_Redirects_InvalidInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Redirects_InvalidInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_redirects_invalid(inputs)
	if (locale === "ja") return ja_settings_redirects_invalid(inputs)
	return en_settings_redirects_invalid(inputs)
});