/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Dashboard_SubtitleInputs */

const en_dashboard_subtitle = /** @type {(inputs: Dashboard_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`All your documentation sites — each with its own settings, members, and plan.`)
};

const zh_cn2_dashboard_subtitle = /** @type {(inputs: Dashboard_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您的所有文档站点 — 每个站点都有自己的设置、成员和计划。`)
};

const ja_dashboard_subtitle = /** @type {(inputs: Dashboard_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`すべてのドキュメント サイト - それぞれに独自の設定、メンバー、プランがあります。`)
};

/**
* | output |
* | --- |
* | "All your documentation sites — each with its own settings, members, and plan." |
*
* @param {Dashboard_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const dashboard_subtitle = /** @type {((inputs?: Dashboard_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Dashboard_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_dashboard_subtitle(inputs)
	if (locale === "ja") return ja_dashboard_subtitle(inputs)
	return en_dashboard_subtitle(inputs)
});