/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_Activity_EmptyInputs */

const en_overview_activity_empty = /** @type {(inputs: Overview_Activity_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No deployments yet.`)
};

const zh_cn2_overview_activity_empty = /** @type {(inputs: Overview_Activity_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`尚未部署。`)
};

const ja_overview_activity_empty = /** @type {(inputs: Overview_Activity_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだ展開はありません。`)
};

/**
* | output |
* | --- |
* | "No deployments yet." |
*
* @param {Overview_Activity_EmptyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_activity_empty = /** @type {((inputs?: Overview_Activity_EmptyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_Activity_EmptyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_activity_empty(inputs)
	if (locale === "ja") return ja_overview_activity_empty(inputs)
	return en_overview_activity_empty(inputs)
});