import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_LinkcopiedInputs */

const en_blog_linkcopied = /** @type {(inputs: Blog_LinkcopiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Link copied`)
};

const zh_cn2_blog_linkcopied = /** @type {(inputs: Blog_LinkcopiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Link copied`)
};

const ja_blog_linkcopied = /** @type {(inputs: Blog_LinkcopiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`リンクがコピーされました`)
};

/**
* | output |
* | --- |
* | "Link copied" |
*
* @param {Blog_LinkcopiedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_linkcopied = /** @type {((inputs?: Blog_LinkcopiedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_LinkcopiedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_linkcopied(inputs)
	if (locale === "ja") return ja_blog_linkcopied(inputs)
	return en_blog_linkcopied(inputs)
});