/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ pages: NonNullable<unknown>, languages: NonNullable<unknown> }} Admin_Sites_ContentsummaryInputs */

const en_admin_sites_contentsummary = /** @type {(inputs: Admin_Sites_ContentsummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.pages} pages · ${i?.languages} languages`)
};

const zh_cn2_admin_sites_contentsummary = /** @type {(inputs: Admin_Sites_ContentsummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.pages} pages · ${i?.languages} languages`)
};

const ja_admin_sites_contentsummary = /** @type {(inputs: Admin_Sites_ContentsummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.pages} ページ · __VAR_langages__ 言語 ${i?.languages}`)
};

/**
* | output |
* | --- |
* | "{pages} pages · {languages} languages" |
*
* @param {Admin_Sites_ContentsummaryInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_sites_contentsummary = /** @type {((inputs: Admin_Sites_ContentsummaryInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Sites_ContentsummaryInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_sites_contentsummary(inputs)
	if (locale === "ja") return ja_admin_sites_contentsummary(inputs)
	return en_admin_sites_contentsummary(inputs)
});