import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown> }} Settings_Git_Pipeline_BuildingInputs */

const en_settings_git_pipeline_building = /** @type {(inputs: Settings_Git_Pipeline_BuildingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Building v${i?.version}…`)
};

const zh_cn2_settings_git_pipeline_building = /** @type {(inputs: Settings_Git_Pipeline_BuildingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`构建 v${i?.version}...`)
};

const ja_settings_git_pipeline_building = /** @type {(inputs: Settings_Git_Pipeline_BuildingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} を構築中…`)
};

/**
* | output |
* | --- |
* | "Building v{version}…" |
*
* @param {Settings_Git_Pipeline_BuildingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_pipeline_building = /** @type {((inputs: Settings_Git_Pipeline_BuildingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Pipeline_BuildingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_pipeline_building(inputs)
	if (locale === "ja") return ja_settings_git_pipeline_building(inputs)
	return en_settings_git_pipeline_building(inputs)
});