/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ words: NonNullable<unknown>, characters: NonNullable<unknown> }} Editor_WordcountInputs */

const en_editor_wordcount = /** @type {(inputs: Editor_WordcountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Words: ${i?.words} · Characters: ${i?.characters}`)
};

const zh_cn2_editor_wordcount = /** @type {(inputs: Editor_WordcountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`单词：${i?.words} · 字符：${i?.characters}`)
};

const ja_editor_wordcount = /** @type {(inputs: Editor_WordcountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`単語: ${i?.words} · 文字: ${i?.characters}`)
};

/**
* | output |
* | --- |
* | "Words: {words} · Characters: {characters}" |
*
* @param {Editor_WordcountInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_wordcount = /** @type {((inputs: Editor_WordcountInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_WordcountInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_wordcount(inputs)
	if (locale === "ja") return ja_editor_wordcount(inputs)
	return en_editor_wordcount(inputs)
});