/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_General_TitleInputs */

const en_settings_general_title = /** @type {(inputs: Settings_General_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`General`)
};

const zh_cn2_settings_general_title = /** @type {(inputs: Settings_General_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`一般`)
};

const ja_settings_general_title = /** @type {(inputs: Settings_General_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`一般`)
};

/**
* | output |
* | --- |
* | "General" |
*
* @param {Settings_General_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_general_title = /** @type {((inputs?: Settings_General_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_General_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_general_title(inputs)
	if (locale === "ja") return ja_settings_general_title(inputs)
	return en_settings_general_title(inputs)
});