/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_SubtitleInputs */

const en_overview_subtitle = /** @type {(inputs: Overview_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Everything for this site in one place.`)
};

const zh_cn2_overview_subtitle = /** @type {(inputs: Overview_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`该网站的所有内容都集中在一处。`)
};

const ja_overview_subtitle = /** @type {(inputs: Overview_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このサイトのすべてが 1 か所にまとめられています。`)
};

/**
* | output |
* | --- |
* | "Everything for this site in one place." |
*
* @param {Overview_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_subtitle = /** @type {((inputs?: Overview_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_subtitle(inputs)
	if (locale === "ja") return ja_overview_subtitle(inputs)
	return en_overview_subtitle(inputs)
});