import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Git_DescriptionInputs */

const en_settings_import_git_description = /** @type {(inputs: Settings_Import_Git_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Markdown in any public GitHub, GitLab, or plain Git repository — configure and run it from the Git settings.`)
};

const zh_cn2_settings_import_git_description = /** @type {(inputs: Settings_Import_Git_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`任何公共 GitHub、GitLab 或普通 Git 存储库中的 Markdown — 从 Git 设置配置并运行它。`)
};

const ja_settings_import_git_description = /** @type {(inputs: Settings_Import_Git_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`パブリック GitHub、GitLab、またはプレーン Git リポジトリの Markdown — Git 設定から構成して実行します。`)
};

/**
* | output |
* | --- |
* | "Markdown in any public GitHub, GitLab, or plain Git repository — configure and run it from the Git settings." |
*
* @param {Settings_Import_Git_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_git_description = /** @type {((inputs?: Settings_Import_Git_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Git_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_git_description(inputs)
	if (locale === "ja") return ja_settings_import_git_description(inputs)
	return en_settings_import_git_description(inputs)
});