/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Nav_SiteInputs */

const en_nav_site = /** @type {(inputs: Nav_SiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Website`)
};

const zh_cn2_nav_site = /** @type {(inputs: Nav_SiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`网站`)
};

const ja_nav_site = /** @type {(inputs: Nav_SiteInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Webサイト`)
};

/**
* | output |
* | --- |
* | "Website" |
*
* @param {Nav_SiteInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const nav_site = /** @type {((inputs?: Nav_SiteInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Nav_SiteInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_nav_site(inputs)
	if (locale === "ja") return ja_nav_site(inputs)
	return en_nav_site(inputs)
});