/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_TitleInputs */

const en_publish_title = /** @type {(inputs: Publish_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Publish to production`)
};

const zh_cn2_publish_title = /** @type {(inputs: Publish_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`发布到生产环境`)
};

const ja_publish_title = /** @type {(inputs: Publish_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`運用環境に公開する`)
};

/**
* | output |
* | --- |
* | "Publish to production" |
*
* @param {Publish_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_title = /** @type {((inputs?: Publish_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_title(inputs)
	if (locale === "ja") return ja_publish_title(inputs)
	return en_publish_title(inputs)
});