import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Langsettings_MetatitlehintInputs */

const en_editor_langsettings_metatitlehint = /** @type {(inputs: Editor_Langsettings_MetatitlehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Used in the “Page — Site” title pattern for this language.`)
};

const zh_cn2_editor_langsettings_metatitlehint = /** @type {(inputs: Editor_Langsettings_MetatitlehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`用于该语言的“页面 - 站点”标题模式。`)
};

const ja_editor_langsettings_metatitlehint = /** @type {(inputs: Editor_Langsettings_MetatitlehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`この言語の「ページ — サイト」タイトル パターンで使用されます。`)
};

/**
* | output |
* | --- |
* | "Used in the “Page — Site” title pattern for this language." |
*
* @param {Editor_Langsettings_MetatitlehintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_langsettings_metatitlehint = /** @type {((inputs?: Editor_Langsettings_MetatitlehintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Langsettings_MetatitlehintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_langsettings_metatitlehint(inputs)
	if (locale === "ja") return ja_editor_langsettings_metatitlehint(inputs)
	return en_editor_langsettings_metatitlehint(inputs)
});