/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_NowInputs */

const en_publish_now = /** @type {(inputs: Publish_NowInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Publish now`)
};

const zh_cn2_publish_now = /** @type {(inputs: Publish_NowInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`立即发布`)
};

const ja_publish_now = /** @type {(inputs: Publish_NowInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`今すぐ公開`)
};

/**
* | output |
* | --- |
* | "Publish now" |
*
* @param {Publish_NowInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_now = /** @type {((inputs?: Publish_NowInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_NowInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_now(inputs)
	if (locale === "ja") return ja_publish_now(inputs)
	return en_publish_now(inputs)
});