import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_General_Url_HintInputs */

const en_settings_general_url_hint = /** @type {(inputs: Settings_General_Url_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Your free cms subdomain. Use 1-63 lowercase letters, numbers, and hyphens. Add a custom domain below to override it.`)
};

const zh_cn2_settings_general_url_hint = /** @type {(inputs: Settings_General_Url_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您的免费 cms 子域。使用 1-63 个小写字母、数字和连字符。在下面添加一个自定义域来覆盖它。`)
};

const ja_settings_general_url_hint = /** @type {(inputs: Settings_General_Url_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`無料の cms サブドメイン。 1 ～ 63 文字の小文字、数字、ハイフンを使用します。以下にカスタム ドメインを追加して上書きします。`)
};

/**
* | output |
* | --- |
* | "Your free cms subdomain. Use 1-63 lowercase letters, numbers, and hyphens. Add a custom domain below to override it." |
*
* @param {Settings_General_Url_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_general_url_hint = /** @type {((inputs?: Settings_General_Url_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_General_Url_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_general_url_hint(inputs)
	if (locale === "ja") return ja_settings_general_url_hint(inputs)
	return en_settings_general_url_hint(inputs)
});