import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_NoemailInputs */

const en_auth_verify_noemail = /** @type {(inputs: Auth_Verify_NoemailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No email address to send to.`)
};

const zh_cn2_auth_verify_noemail = /** @type {(inputs: Auth_Verify_NoemailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`没有要发送到的电子邮件地址。`)
};

const ja_auth_verify_noemail = /** @type {(inputs: Auth_Verify_NoemailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`送信先の電子メール アドレスがありません。`)
};

/**
* | output |
* | --- |
* | "No email address to send to." |
*
* @param {Auth_Verify_NoemailInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_noemail = /** @type {((inputs?: Auth_Verify_NoemailInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_NoemailInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_noemail(inputs)
	if (locale === "ja") return ja_auth_verify_noemail(inputs)
	return en_auth_verify_noemail(inputs)
});