import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_TeamInputs */

const en_blog_team = /** @type {(inputs: Blog_TeamInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The cms team`)
};

const zh_cn2_blog_team = /** @type {(inputs: Blog_TeamInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The cms team`)
};

const ja_blog_team = /** @type {(inputs: Blog_TeamInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cmsチーム`)
};

/**
* | output |
* | --- |
* | "The cms team" |
*
* @param {Blog_TeamInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_team = /** @type {((inputs?: Blog_TeamInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_TeamInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_team(inputs)
	if (locale === "ja") return ja_blog_team(inputs)
	return en_blog_team(inputs)
});