/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_Import_ApplyerrorInputs */

const en_settings_theme_import_applyerror = /** @type {(inputs: Settings_Theme_Import_ApplyerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not apply the theme template`)
};

const zh_cn2_settings_theme_import_applyerror = /** @type {(inputs: Settings_Theme_Import_ApplyerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法应用主题模板`)
};

const ja_settings_theme_import_applyerror = /** @type {(inputs: Settings_Theme_Import_ApplyerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`テーマテンプレートを適用できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not apply the theme template" |
*
* @param {Settings_Theme_Import_ApplyerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_import_applyerror = /** @type {((inputs?: Settings_Theme_Import_ApplyerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_Import_ApplyerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_import_applyerror(inputs)
	if (locale === "ja") return ja_settings_theme_import_applyerror(inputs)
	return en_settings_theme_import_applyerror(inputs)
});