/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Members_DescriptionInputs */

const en_settings_members_description = /** @type {(inputs: Settings_Members_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`People who can access and edit this site. Each site has its own members and roles.`)
};

const zh_cn2_settings_members_description = /** @type {(inputs: Settings_Members_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`可以访问和编辑此网站的人员。每个站点都有自己的成员和角色。`)
};

const ja_settings_members_description = /** @type {(inputs: Settings_Members_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このサイトにアクセスして編集できる人。各サイトには独自のメンバーと役割があります。`)
};

/**
* | output |
* | --- |
* | "People who can access and edit this site. Each site has its own members and roles." |
*
* @param {Settings_Members_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_members_description = /** @type {((inputs?: Settings_Members_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Members_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_members_description(inputs)
	if (locale === "ja") return ja_settings_members_description(inputs)
	return en_settings_members_description(inputs)
});