/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_ModifiedInputs */

const en_publish_modified = /** @type {(inputs: Publish_ModifiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Edited`)
};

const zh_cn2_publish_modified = /** @type {(inputs: Publish_ModifiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已编辑`)
};

const ja_publish_modified = /** @type {(inputs: Publish_ModifiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`編集済み`)
};

/**
* | output |
* | --- |
* | "Edited" |
*
* @param {Publish_ModifiedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_modified = /** @type {((inputs?: Publish_ModifiedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_ModifiedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_modified(inputs)
	if (locale === "ja") return ja_publish_modified(inputs)
	return en_publish_modified(inputs)
});