/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Newsite_ErrorInputs */

const en_newsite_error = /** @type {(inputs: Newsite_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not create project`)
};

const zh_cn2_newsite_error = /** @type {(inputs: Newsite_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法创建项目`)
};

const ja_newsite_error = /** @type {(inputs: Newsite_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`プロジェクトを作成できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not create project" |
*
* @param {Newsite_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const newsite_error = /** @type {((inputs?: Newsite_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Newsite_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_newsite_error(inputs)
	if (locale === "ja") return ja_newsite_error(inputs)
	return en_newsite_error(inputs)
});