import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown>, percent: NonNullable<unknown> }} Admin_Overview_ReadypercentInputs */

const en_admin_overview_readypercent = /** @type {(inputs: Admin_Overview_ReadypercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} ready · ${i?.percent}`)
};

const zh_cn2_admin_overview_readypercent = /** @type {(inputs: Admin_Overview_ReadypercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} ready · ${i?.percent}`)
};

const ja_admin_overview_readypercent = /** @type {(inputs: Admin_Overview_ReadypercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 準備完了 · ${i?.percent}`)
};

/**
* | output |
* | --- |
* | "{count} ready · {percent}" |
*
* @param {Admin_Overview_ReadypercentInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_overview_readypercent = /** @type {((inputs: Admin_Overview_ReadypercentInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Overview_ReadypercentInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_overview_readypercent(inputs)
	if (locale === "ja") return ja_admin_overview_readypercent(inputs)
	return en_admin_overview_readypercent(inputs)
});