/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Langsettings_TitleInputs */

const en_editor_langsettings_title = /** @type {(inputs: Editor_Langsettings_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Language settings`)
};

const zh_cn2_editor_langsettings_title = /** @type {(inputs: Editor_Langsettings_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`语言设置`)
};

const ja_editor_langsettings_title = /** @type {(inputs: Editor_Langsettings_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語設定`)
};

/**
* | output |
* | --- |
* | "Language settings" |
*
* @param {Editor_Langsettings_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_langsettings_title = /** @type {((inputs?: Editor_Langsettings_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Langsettings_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_langsettings_title(inputs)
	if (locale === "ja") return ja_editor_langsettings_title(inputs)
	return en_editor_langsettings_title(inputs)
});