/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_SubtitleInputs */

const en_settings_integrations_subtitle = /** @type {(inputs: Settings_Integrations_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Connect cms to the tools your team already uses.`)
};

const zh_cn2_settings_integrations_subtitle = /** @type {(inputs: Settings_Integrations_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`将 cms 连接到团队已在使用的工具。`)
};

const ja_settings_integrations_subtitle = /** @type {(inputs: Settings_Integrations_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms をチームがすでに使用しているツールに接続します。`)
};

/**
* | output |
* | --- |
* | "Connect cms to the tools your team already uses." |
*
* @param {Settings_Integrations_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_subtitle = /** @type {((inputs?: Settings_Integrations_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_subtitle(inputs)
	if (locale === "ja") return ja_settings_integrations_subtitle(inputs)
	return en_settings_integrations_subtitle(inputs)
});