import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_RedirectsInputs */

const en_settings_redirects = /** @type {(inputs: Settings_RedirectsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Redirects`)
};

const zh_cn2_settings_redirects = /** @type {(inputs: Settings_RedirectsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`重定向`)
};

const ja_settings_redirects = /** @type {(inputs: Settings_RedirectsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`リダイレクト`)
};

/**
* | output |
* | --- |
* | "Redirects" |
*
* @param {Settings_RedirectsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_redirects = /** @type {((inputs?: Settings_RedirectsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_RedirectsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_redirects(inputs)
	if (locale === "ja") return ja_settings_redirects(inputs)
	return en_settings_redirects(inputs)
});