/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ label: NonNullable<unknown>, min: NonNullable<unknown> }} Validation_MinlengthInputs */

const en_validation_minlength = /** @type {(inputs: Validation_MinlengthInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.label} must be at least ${i?.min} characters`)
};

const zh_cn2_validation_minlength = /** @type {(inputs: Validation_MinlengthInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.label} 必须至少有 ${i?.min} 个字符`)
};

const ja_validation_minlength = /** @type {(inputs: Validation_MinlengthInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.label} は少なくとも ${i?.min} 文字である必要があります`)
};

/**
* | output |
* | --- |
* | "{label} must be at least {min} characters" |
*
* @param {Validation_MinlengthInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const validation_minlength = /** @type {((inputs: Validation_MinlengthInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Validation_MinlengthInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_validation_minlength(inputs)
	if (locale === "ja") return ja_validation_minlength(inputs)
	return en_validation_minlength(inputs)
});