import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_NavigationInputs */

const en_editor_navigation = /** @type {(inputs: Editor_NavigationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Navigation`)
};

const zh_cn2_editor_navigation = /** @type {(inputs: Editor_NavigationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导航`)
};

const ja_editor_navigation = /** @type {(inputs: Editor_NavigationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ナビゲーション`)
};

/**
* | output |
* | --- |
* | "Navigation" |
*
* @param {Editor_NavigationInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_navigation = /** @type {((inputs?: Editor_NavigationInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_NavigationInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_navigation(inputs)
	if (locale === "ja") return ja_editor_navigation(inputs)
	return en_editor_navigation(inputs)
});