/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_AddlanguageInputs */

const en_editor_addlanguage = /** @type {(inputs: Editor_AddlanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add language`)
};

const zh_cn2_editor_addlanguage = /** @type {(inputs: Editor_AddlanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`添加语言`)
};

const ja_editor_addlanguage = /** @type {(inputs: Editor_AddlanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を追加する`)
};

/**
* | output |
* | --- |
* | "Add language" |
*
* @param {Editor_AddlanguageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_addlanguage = /** @type {((inputs?: Editor_AddlanguageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_AddlanguageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_addlanguage(inputs)
	if (locale === "ja") return ja_editor_addlanguage(inputs)
	return en_editor_addlanguage(inputs)
});