/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ seconds: NonNullable<unknown> }} Auth_Otp_ResendinInputs */

const en_auth_otp_resendin = /** @type {(inputs: Auth_Otp_ResendinInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Resend in ${i?.seconds}s`)
};

const zh_cn2_auth_otp_resendin = /** @type {(inputs: Auth_Otp_ResendinInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`在 ${i?.seconds}s 后重新发送`)
};

const ja_auth_otp_resendin = /** @type {(inputs: Auth_Otp_ResendinInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`__VAR_秒__秒以内に再送信します ${i?.seconds}`)
};

/**
* | output |
* | --- |
* | "Resend in {seconds}s" |
*
* @param {Auth_Otp_ResendinInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_otp_resendin = /** @type {((inputs: Auth_Otp_ResendinInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Otp_ResendinInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_otp_resendin(inputs)
	if (locale === "ja") return ja_auth_otp_resendin(inputs)
	return en_auth_otp_resendin(inputs)
});