import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_BrandingInputs */

const en_settings_branding = /** @type {(inputs: Settings_BrandingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Branding`)
};

const zh_cn2_settings_branding = /** @type {(inputs: Settings_BrandingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`品牌推广`)
};

const ja_settings_branding = /** @type {(inputs: Settings_BrandingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ブランディング`)
};

/**
* | output |
* | --- |
* | "Branding" |
*
* @param {Settings_BrandingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_branding = /** @type {((inputs?: Settings_BrandingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_BrandingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_branding(inputs)
	if (locale === "ja") return ja_settings_branding(inputs)
	return en_settings_branding(inputs)
});