import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Ai_InstructionplaceholderInputs */

const en_editor_ai_instructionplaceholder = /** @type {(inputs: Editor_Ai_InstructionplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ask the assistant to write something specific…`)
};

const zh_cn2_editor_ai_instructionplaceholder = /** @type {(inputs: Editor_Ai_InstructionplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`请助理写一些具体的东西...`)
};

const ja_editor_ai_instructionplaceholder = /** @type {(inputs: Editor_Ai_InstructionplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`アシスタントに具体的な内容を書いてもらいます...`)
};

/**
* | output |
* | --- |
* | "Ask the assistant to write something specific…" |
*
* @param {Editor_Ai_InstructionplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_ai_instructionplaceholder = /** @type {((inputs?: Editor_Ai_InstructionplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Ai_InstructionplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_ai_instructionplaceholder(inputs)
	if (locale === "ja") return ja_editor_ai_instructionplaceholder(inputs)
	return en_editor_ai_instructionplaceholder(inputs)
});