import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_General_Visibility_HintInputs */

const en_settings_general_visibility_hint = /** @type {(inputs: Settings_General_Visibility_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Public sites are indexable. Private sites require a login.`)
};

const zh_cn2_settings_general_visibility_hint = /** @type {(inputs: Settings_General_Visibility_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公共站点是可索引的。私人网站需要登录。`)
};

const ja_settings_general_visibility_hint = /** @type {(inputs: Settings_General_Visibility_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公開サイトはインデックス可能です。プライベート サイトにはログインが必要です。`)
};

/**
* | output |
* | --- |
* | "Public sites are indexable. Private sites require a login." |
*
* @param {Settings_General_Visibility_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_general_visibility_hint = /** @type {((inputs?: Settings_General_Visibility_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_General_Visibility_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_general_visibility_hint(inputs)
	if (locale === "ja") return ja_settings_general_visibility_hint(inputs)
	return en_settings_general_visibility_hint(inputs)
});