/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Mintlify_DescriptionInputs */

const en_settings_import_mintlify_description = /** @type {(inputs: Settings_Import_Mintlify_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import a public Mintlify docs repo from GitHub (docs.json or mint.json) — navigation, pages, and site branding.`)
};

const zh_cn2_settings_import_mintlify_description = /** @type {(inputs: Settings_Import_Mintlify_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`从 GitHub（docs.json 或 mint.json）导入公共 Mintlify 文档存储库 — 导航、页面和网站品牌。`)
};

const ja_settings_import_mintlify_description = /** @type {(inputs: Settings_Import_Mintlify_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`GitHub からパブリック Mintlify ドキュメント リポジトリ (docs.json または mint.json) をインポートします (ナビゲーション、ページ、サイトのブランディング)。`)
};

/**
* | output |
* | --- |
* | "Import a public Mintlify docs repo from GitHub (docs.json or mint.json) — navigation, pages, and site branding." |
*
* @param {Settings_Import_Mintlify_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_mintlify_description = /** @type {((inputs?: Settings_Import_Mintlify_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Mintlify_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_mintlify_description(inputs)
	if (locale === "ja") return ja_settings_import_mintlify_description(inputs)
	return en_settings_import_mintlify_description(inputs)
});