/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Auth_Verify_SenttoastInputs */

const en_auth_verify_senttoast = /** @type {(inputs: Auth_Verify_SenttoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`A new verification code was sent to ${i?.email}`)
};

const zh_cn2_auth_verify_senttoast = /** @type {(inputs: Auth_Verify_SenttoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`新的验证码已发送至 ${i?.email}`)
};

const ja_auth_verify_senttoast = /** @type {(inputs: Auth_Verify_SenttoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`新しい確認コードが ${i?.email} に送信されました`)
};

/**
* | output |
* | --- |
* | "A new verification code was sent to {email}" |
*
* @param {Auth_Verify_SenttoastInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_senttoast = /** @type {((inputs: Auth_Verify_SenttoastInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_SenttoastInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_senttoast(inputs)
	if (locale === "ja") return ja_auth_verify_senttoast(inputs)
	return en_auth_verify_senttoast(inputs)
});