/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ whole: NonNullable<unknown>, fraction: NonNullable<unknown> }} Settings_Usage_DecimalInputs */

const en_settings_usage_decimal = /** @type {(inputs: Settings_Usage_DecimalInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.whole}.${i?.fraction}`)
};

const zh_cn2_settings_usage_decimal = /** @type {(inputs: Settings_Usage_DecimalInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.whole}.${i?.fraction}`)
};

const ja_settings_usage_decimal = /** @type {(inputs: Settings_Usage_DecimalInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`__VAR_全体__.__VAR_部分__ ${i?.whole} ${i?.fraction}`)
};

/**
* | output |
* | --- |
* | "{whole}.{fraction}" |
*
* @param {Settings_Usage_DecimalInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage_decimal = /** @type {((inputs: Settings_Usage_DecimalInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Usage_DecimalInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage_decimal(inputs)
	if (locale === "ja") return ja_settings_usage_decimal(inputs)
	return en_settings_usage_decimal(inputs)
});