import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_NopagesyetInputs */

const en_editor_nopagesyet = /** @type {(inputs: Editor_NopagesyetInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No pages yet`)
};

const zh_cn2_editor_nopagesyet = /** @type {(inputs: Editor_NopagesyetInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`还没有页面`)
};

const ja_editor_nopagesyet = /** @type {(inputs: Editor_NopagesyetInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだページがありません`)
};

/**
* | output |
* | --- |
* | "No pages yet" |
*
* @param {Editor_NopagesyetInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_nopagesyet = /** @type {((inputs?: Editor_NopagesyetInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_NopagesyetInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_nopagesyet(inputs)
	if (locale === "ja") return ja_editor_nopagesyet(inputs)
	return en_editor_nopagesyet(inputs)
});