import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Redirects_TolabelInputs */

const en_settings_redirects_tolabel = /** @type {(inputs: Settings_Redirects_TolabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Redirect to path`)
};

const zh_cn2_settings_redirects_tolabel = /** @type {(inputs: Settings_Redirects_TolabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`重定向到路径`)
};

const ja_settings_redirects_tolabel = /** @type {(inputs: Settings_Redirects_TolabelInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`パスにリダイレクト`)
};

/**
* | output |
* | --- |
* | "Redirect to path" |
*
* @param {Settings_Redirects_TolabelInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_redirects_tolabel = /** @type {((inputs?: Settings_Redirects_TolabelInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Redirects_TolabelInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_redirects_tolabel(inputs)
	if (locale === "ja") return ja_settings_redirects_tolabel(inputs)
	return en_settings_redirects_tolabel(inputs)
});