/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Command_Dialog_DescriptionInputs */

const en_command_dialog_description = /** @type {(inputs: Command_Dialog_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search for a site or action to jump to.`)
};

const zh_cn2_command_dialog_description = /** @type {(inputs: Command_Dialog_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`搜索要跳转到的站点或操作。`)
};

const ja_command_dialog_description = /** @type {(inputs: Command_Dialog_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ジャンプ先のサイトまたはアクションを検索します。`)
};

/**
* | output |
* | --- |
* | "Search for a site or action to jump to." |
*
* @param {Command_Dialog_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const command_dialog_description = /** @type {((inputs?: Command_Dialog_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Command_Dialog_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_command_dialog_description(inputs)
	if (locale === "ja") return ja_command_dialog_description(inputs)
	return en_command_dialog_description(inputs)
});