/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_FilehintInputs */

const en_settings_import_ghost_filehint = /** @type {(inputs: Settings_Import_Ghost_FilehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose the JSON file exported from Ghost Labs.`)
};

const zh_cn2_settings_import_ghost_filehint = /** @type {(inputs: Settings_Import_Ghost_FilehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择从 Ghost Labs 导出的 JSON 文件。`)
};

const ja_settings_import_ghost_filehint = /** @type {(inputs: Settings_Import_Ghost_FilehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ghost Labs からエクスポートした JSON ファイルを選択します。`)
};

/**
* | output |
* | --- |
* | "Choose the JSON file exported from Ghost Labs." |
*
* @param {Settings_Import_Ghost_FilehintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_filehint = /** @type {((inputs?: Settings_Import_Ghost_FilehintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_FilehintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_filehint(inputs)
	if (locale === "ja") return ja_settings_import_ghost_filehint(inputs)
	return en_settings_import_ghost_filehint(inputs)
});