/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ site: NonNullable<unknown> }} Admin_Site_OpenliveInputs */

const en_admin_site_openlive = /** @type {(inputs: Admin_Site_OpenliveInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Open Live ${i?.site}`)
};

const zh_cn2_admin_site_openlive = /** @type {(inputs: Admin_Site_OpenliveInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Open Live ${i?.site}`)
};

const ja_admin_site_openlive = /** @type {(inputs: Admin_Site_OpenliveInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`ライブ ${i?.site} を開く`)
};

/**
* | output |
* | --- |
* | "Open Live {site}" |
*
* @param {Admin_Site_OpenliveInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_site_openlive = /** @type {((inputs: Admin_Site_OpenliveInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Site_OpenliveInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_site_openlive(inputs)
	if (locale === "ja") return ja_admin_site_openlive(inputs)
	return en_admin_site_openlive(inputs)
});