import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Invite_ErrorInputs */

const en_auth_invite_error = /** @type {(inputs: Auth_Invite_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not accept this invitation. It may have expired.`)
};

const zh_cn2_auth_invite_error = /** @type {(inputs: Auth_Invite_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法接受此邀请。它可能已经过期了。`)
};

const ja_auth_invite_error = /** @type {(inputs: Auth_Invite_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`この招待を承諾できませんでした。有効期限が切れている可能性があります。`)
};

/**
* | output |
* | --- |
* | "Could not accept this invitation. It may have expired." |
*
* @param {Auth_Invite_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_error = /** @type {((inputs?: Auth_Invite_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_error(inputs)
	if (locale === "ja") return ja_auth_invite_error(inputs)
	return en_auth_invite_error(inputs)
});