/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ imported: NonNullable<unknown>, skipped: NonNullable<unknown> }} Settings_Import_AssetsresultInputs */

const en_settings_import_assetsresult = /** @type {(inputs: Settings_Import_AssetsresultInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Copied ${i?.imported} images into project storage; ${i?.skipped} remained at their source URL.`)
};

const zh_cn2_settings_import_assetsresult = /** @type {(inputs: Settings_Import_AssetsresultInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`将 ${i?.imported} 图像复制到项目存储中； ${i?.skipped} 保留在其源 URL 上。`)
};

const ja_settings_import_assetsresult = /** @type {(inputs: Settings_Import_AssetsresultInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.imported} イメージをプロジェクト ストレージにコピーしました。 ${i?.skipped} はソース URL に残りました。`)
};

/**
* | output |
* | --- |
* | "Copied {imported} images into project storage; {skipped} remained at their source URL." |
*
* @param {Settings_Import_AssetsresultInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_assetsresult = /** @type {((inputs: Settings_Import_AssetsresultInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_AssetsresultInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_assetsresult(inputs)
	if (locale === "ja") return ja_settings_import_assetsresult(inputs)
	return en_settings_import_assetsresult(inputs)
});