import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Seo_UploaderrorInputs */

const en_settings_seo_uploaderror = /** @type {(inputs: Settings_Seo_UploaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Upload failed`)
};

const zh_cn2_settings_seo_uploaderror = /** @type {(inputs: Settings_Seo_UploaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`上传失败`)
};

const ja_settings_seo_uploaderror = /** @type {(inputs: Settings_Seo_UploaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`アップロードに失敗しました`)
};

/**
* | output |
* | --- |
* | "Upload failed" |
*
* @param {Settings_Seo_UploaderrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_seo_uploaderror = /** @type {((inputs?: Settings_Seo_UploaderrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Seo_UploaderrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_seo_uploaderror(inputs)
	if (locale === "ja") return ja_settings_seo_uploaderror(inputs)
	return en_settings_seo_uploaderror(inputs)
});