import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Workflow_TitleInputs */

const en_settings_git_workflow_title = /** @type {(inputs: Settings_Git_Workflow_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Two-way Git workflow`)
};

const zh_cn2_settings_git_workflow_title = /** @type {(inputs: Settings_Git_Workflow_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`双向 Git 工作流程`)
};

const ja_settings_git_workflow_title = /** @type {(inputs: Settings_Git_Workflow_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`双方向の Git ワークフロー`)
};

/**
* | output |
* | --- |
* | "Two-way Git workflow" |
*
* @param {Settings_Git_Workflow_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_workflow_title = /** @type {((inputs?: Settings_Git_Workflow_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Workflow_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_workflow_title(inputs)
	if (locale === "ja") return ja_settings_git_workflow_title(inputs)
	return en_settings_git_workflow_title(inputs)
});