/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown>, pages: NonNullable<unknown> }} Settings_Git_Pipeline_BuiltInputs */

const en_settings_git_pipeline_built = /** @type {(inputs: Settings_Git_Pipeline_BuiltInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} · pages: ${i?.pages}`)
};

const zh_cn2_settings_git_pipeline_built = /** @type {(inputs: Settings_Git_Pipeline_BuiltInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} · 页数：${i?.pages}`)
};

const ja_settings_git_pipeline_built = /** @type {(inputs: Settings_Git_Pipeline_BuiltInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} · ページ: ${i?.pages}`)
};

/**
* | output |
* | --- |
* | "v{version} · pages: {pages}" |
*
* @param {Settings_Git_Pipeline_BuiltInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_pipeline_built = /** @type {((inputs: Settings_Git_Pipeline_BuiltInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Pipeline_BuiltInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_pipeline_built(inputs)
	if (locale === "ja") return ja_settings_git_pipeline_built(inputs)
	return en_settings_git_pipeline_built(inputs)
});