/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_LanguagetutorialInputs */

const en_settings_import_ghost_languagetutorial = /** @type {(inputs: Settings_Import_Ghost_LanguagetutorialInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Before exporting from Ghost, add exactly one language tag to every post and page. The tag slug must match a language code in this project — for example, en for English or ja for Japanese. The importer places each item in that language tree and stops if a tagged language is missing from the project.`)
};

const zh_cn2_settings_import_ghost_languagetutorial = /** @type {(inputs: Settings_Import_Ghost_LanguagetutorialInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`从 Ghost 导出之前，请向每个帖子和页面添加一个语言标签。标签段必须与该项目中的语言代码匹配 - 例如，en 代表英语，ja 代表日语。导入器将每个项目放入该语言树中，如果项目中缺少标记的语言，则导入器会停止。`)
};

const ja_settings_import_ghost_languagetutorial = /** @type {(inputs: Settings_Import_Ghost_LanguagetutorialInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ghost からエクスポートする前に、すべての投稿とページに言語タグを 1 つだけ追加します。タグ スラッグは、このプロジェクトの言語コードと一致する必要があります。たとえば、英語の場合は en、アラビア語の場合は ar です。インポーターは各項目をその言語ツリーに配置し、タグ付けされた言語がプロジェクトにない場合は停止します。`)
};

/**
* | output |
* | --- |
* | "Before exporting from Ghost, add exactly one language tag to every post and page. The tag slug must match a language code in this project — for example, en f..." |
*
* @param {Settings_Import_Ghost_LanguagetutorialInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_languagetutorial = /** @type {((inputs?: Settings_Import_Ghost_LanguagetutorialInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_LanguagetutorialInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_languagetutorial(inputs)
	if (locale === "ja") return ja_settings_import_ghost_languagetutorial(inputs)
	return en_settings_import_ghost_languagetutorial(inputs)
});