import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ date: NonNullable<unknown> }} Admin_User_CustomersinceInputs */

const en_admin_user_customersince = /** @type {(inputs: Admin_User_CustomersinceInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Customer Since ${i?.date}`)
};

const zh_cn2_admin_user_customersince = /** @type {(inputs: Admin_User_CustomersinceInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Customer Since ${i?.date}`)
};

const ja_admin_user_customersince = /** @type {(inputs: Admin_User_CustomersinceInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.date}以降の顧客`)
};

/**
* | output |
* | --- |
* | "Customer Since {date}" |
*
* @param {Admin_User_CustomersinceInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_user_customersince = /** @type {((inputs: Admin_User_CustomersinceInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_User_CustomersinceInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_user_customersince(inputs)
	if (locale === "ja") return ja_admin_user_customersince(inputs)
	return en_admin_user_customersince(inputs)
});