/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_BackInputs */

const en_settings_import_back = /** @type {(inputs: Settings_Import_BackInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Back`)
};

const zh_cn2_settings_import_back = /** @type {(inputs: Settings_Import_BackInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`返回`)
};

const ja_settings_import_back = /** @type {(inputs: Settings_Import_BackInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`戻る`)
};

/**
* | output |
* | --- |
* | "Back" |
*
* @param {Settings_Import_BackInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_back = /** @type {((inputs?: Settings_Import_BackInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_BackInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_back(inputs)
	if (locale === "ja") return ja_settings_import_back(inputs)
	return en_settings_import_back(inputs)
});