/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Settings_Languages_Coverage_MissingInputs */

const en_settings_languages_coverage_missing = /** @type {(inputs: Settings_Languages_Coverage_MissingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} missing`)
};

const zh_cn2_settings_languages_coverage_missing = /** @type {(inputs: Settings_Languages_Coverage_MissingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 缺失`)
};

const ja_settings_languages_coverage_missing = /** @type {(inputs: Settings_Languages_Coverage_MissingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} がありません`)
};

/**
* | output |
* | --- |
* | "{count} missing" |
*
* @param {Settings_Languages_Coverage_MissingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_coverage_missing = /** @type {((inputs: Settings_Languages_Coverage_MissingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_Coverage_MissingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_coverage_missing(inputs)
	if (locale === "ja") return ja_settings_languages_coverage_missing(inputs)
	return en_settings_languages_coverage_missing(inputs)
});