import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_Nudge_TitleInputs */

const en_overview_nudge_title = /** @type {(inputs: Overview_Nudge_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Your docs are not live yet`)
};

const zh_cn2_overview_nudge_title = /** @type {(inputs: Overview_Nudge_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您的文档尚未上线`)
};

const ja_overview_nudge_title = /** @type {(inputs: Overview_Nudge_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドキュメントはまだ公開されていません`)
};

/**
* | output |
* | --- |
* | "Your docs are not live yet" |
*
* @param {Overview_Nudge_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_nudge_title = /** @type {((inputs?: Overview_Nudge_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_Nudge_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_nudge_title(inputs)
	if (locale === "ja") return ja_overview_nudge_title(inputs)
	return en_overview_nudge_title(inputs)
});