/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_DeployingInputs */

const en_deploy_deploying = /** @type {(inputs: Deploy_DeployingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Deploying…`)
};

const zh_cn2_deploy_deploying = /** @type {(inputs: Deploy_DeployingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`正在部署...`)
};

const ja_deploy_deploying = /** @type {(inputs: Deploy_DeployingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`導入中…`)
};

/**
* | output |
* | --- |
* | "Deploying…" |
*
* @param {Deploy_DeployingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_deploying = /** @type {((inputs?: Deploy_DeployingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_DeployingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_deploying(inputs)
	if (locale === "ja") return ja_deploy_deploying(inputs)
	return en_deploy_deploying(inputs)
});