/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_SearchplaceholderInputs */

const en_blog_searchplaceholder = /** @type {(inputs: Blog_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search articles…`)
};

const zh_cn2_blog_searchplaceholder = /** @type {(inputs: Blog_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search articles…`)
};

const ja_blog_searchplaceholder = /** @type {(inputs: Blog_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`記事を検索…`)
};

/**
* | output |
* | --- |
* | "Search articles…" |
*
* @param {Blog_SearchplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_searchplaceholder = /** @type {((inputs?: Blog_SearchplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_SearchplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_searchplaceholder(inputs)
	if (locale === "ja") return ja_blog_searchplaceholder(inputs)
	return en_blog_searchplaceholder(inputs)
});