import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_UsageInputs */

const en_settings_usage = /** @type {(inputs: Settings_UsageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Usage`)
};

const zh_cn2_settings_usage = /** @type {(inputs: Settings_UsageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`用途`)
};

const ja_settings_usage = /** @type {(inputs: Settings_UsageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`使用法`)
};

/**
* | output |
* | --- |
* | "Usage" |
*
* @param {Settings_UsageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage = /** @type {((inputs?: Settings_UsageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_UsageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage(inputs)
	if (locale === "ja") return ja_settings_usage(inputs)
	return en_settings_usage(inputs)
});