import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Analytics_SubtitleInputs */

const en_analytics_subtitle = /** @type {(inputs: Analytics_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Traffic and search activity across all your documentation sites.`)
};

const zh_cn2_analytics_subtitle = /** @type {(inputs: Analytics_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`所有文档站点的流量和搜索活动。`)
};

const ja_analytics_subtitle = /** @type {(inputs: Analytics_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`すべてのドキュメント サイトにわたるトラフィックと検索アクティビティ。`)
};

/**
* | output |
* | --- |
* | "Traffic and search activity across all your documentation sites." |
*
* @param {Analytics_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const analytics_subtitle = /** @type {((inputs?: Analytics_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Analytics_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_analytics_subtitle(inputs)
	if (locale === "ja") return ja_analytics_subtitle(inputs)
	return en_analytics_subtitle(inputs)
});