import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_NewpageInputs */

const en_editor_newpage = /** @type {(inputs: Editor_NewpageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`New page`)
};

const zh_cn2_editor_newpage = /** @type {(inputs: Editor_NewpageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新页面`)
};

const ja_editor_newpage = /** @type {(inputs: Editor_NewpageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新しいページ`)
};

/**
* | output |
* | --- |
* | "New page" |
*
* @param {Editor_NewpageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_newpage = /** @type {((inputs?: Editor_NewpageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_NewpageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_newpage(inputs)
	if (locale === "ja") return ja_editor_newpage(inputs)
	return en_editor_newpage(inputs)
});