import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_CopylinkInputs */

const en_blog_copylink = /** @type {(inputs: Blog_CopylinkInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Copy article link`)
};

const zh_cn2_blog_copylink = /** @type {(inputs: Blog_CopylinkInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Copy article link`)
};

const ja_blog_copylink = /** @type {(inputs: Blog_CopylinkInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`記事のリンクをコピーする`)
};

/**
* | output |
* | --- |
* | "Copy article link" |
*
* @param {Blog_CopylinkInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_copylink = /** @type {((inputs?: Blog_CopylinkInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_CopylinkInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_copylink(inputs)
	if (locale === "ja") return ja_blog_copylink(inputs)
	return en_blog_copylink(inputs)
});