import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Search_Suggestedquestions_EmptyInputs */

const en_settings_search_suggestedquestions_empty = /** @type {(inputs: Settings_Search_Suggestedquestions_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No suggested questions added yet. Click “Add question” below or “Load example questions” to restore defaults.`)
};

const zh_cn2_settings_search_suggestedquestions_empty = /** @type {(inputs: Settings_Search_Suggestedquestions_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`尚未添加推荐问题。点击下方的“添加问题”或“加载示例问题”以恢复默认设置。`)
};

const ja_settings_search_suggestedquestions_empty = /** @type {(inputs: Settings_Search_Suggestedquestions_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`提案された質問はまだ追加されていません。下の「質問を追加」をクリックするか、「サンプルの質問を読み込む」で初期設定に戻してください。`)
};

/**
* | output |
* | --- |
* | "No suggested questions added yet. Click “Add question” below or “Load example questions” to restore defaults." |
*
* @param {Settings_Search_Suggestedquestions_EmptyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_search_suggestedquestions_empty = /** @type {((inputs?: Settings_Search_Suggestedquestions_EmptyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Search_Suggestedquestions_EmptyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_search_suggestedquestions_empty(inputs)
	if (locale === "ja") return ja_settings_search_suggestedquestions_empty(inputs)
	return en_settings_search_suggestedquestions_empty(inputs)
});