import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Signup_SubtitleInputs */

const en_auth_signup_subtitle = /** @type {(inputs: Auth_Signup_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Create your workspace`)
};

const zh_cn2_auth_signup_subtitle = /** @type {(inputs: Auth_Signup_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`创建您的工作空间`)
};

const ja_auth_signup_subtitle = /** @type {(inputs: Auth_Signup_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ワークスペースを作成する`)
};

/**
* | output |
* | --- |
* | "Create your workspace" |
*
* @param {Auth_Signup_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_signup_subtitle = /** @type {((inputs?: Auth_Signup_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Signup_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_signup_subtitle(inputs)
	if (locale === "ja") return ja_auth_signup_subtitle(inputs)
	return en_auth_signup_subtitle(inputs)
});