import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ site: NonNullable<unknown> }} Admin_Sites_TakedowntitleInputs */

const en_admin_sites_takedowntitle = /** @type {(inputs: Admin_Sites_TakedowntitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Take down “${i?.site}”?`)
};

const zh_cn2_admin_sites_takedowntitle = /** @type {(inputs: Admin_Sites_TakedowntitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Take down “${i?.site}”?`)
};

const ja_admin_sites_takedowntitle = /** @type {(inputs: Admin_Sites_TakedowntitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`「${i?.site}」を削除しますか?`)
};

/**
* | output |
* | --- |
* | "Take down “{site}”?" |
*
* @param {Admin_Sites_TakedowntitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_sites_takedowntitle = /** @type {((inputs: Admin_Sites_TakedowntitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Sites_TakedowntitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_sites_takedowntitle(inputs)
	if (locale === "ja") return ja_admin_sites_takedowntitle(inputs)
	return en_admin_sites_takedowntitle(inputs)
});