import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Appearance_Language_DescriptionInputs */

const en_settings_appearance_language_description = /** @type {(inputs: Settings_Appearance_Language_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The language of the dashboard, editor, and settings. Published sites keep their own languages.`)
};

const zh_cn2_settings_appearance_language_description = /** @type {(inputs: Settings_Appearance_Language_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`仪表板、编辑器和设置所使用的语言。已发布的站点会保留各自的语言。`)
};

const ja_settings_appearance_language_description = /** @type {(inputs: Settings_Appearance_Language_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ダッシュボード、エディター、設定の言語。公開されたサイトは独自の言語を保持します。`)
};

/**
* | output |
* | --- |
* | "The language of the dashboard, editor, and settings. Published sites keep their own languages." |
*
* @param {Settings_Appearance_Language_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_appearance_language_description = /** @type {((inputs?: Settings_Appearance_Language_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Appearance_Language_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_appearance_language_description(inputs)
	if (locale === "ja") return ja_settings_appearance_language_description(inputs)
	return en_settings_appearance_language_description(inputs)
});