/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ start: NonNullable<unknown>, end: NonNullable<unknown> }} Settings_Usage_PeriodInputs */

const en_settings_usage_period = /** @type {(inputs: Settings_Usage_PeriodInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`UTC period: ${i?.start} – ${i?.end}`)
};

const zh_cn2_settings_usage_period = /** @type {(inputs: Settings_Usage_PeriodInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`UTC period: ${i?.start} – ${i?.end}`)
};

const ja_settings_usage_period = /** @type {(inputs: Settings_Usage_PeriodInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`UTC 期間: ${i?.start} – ${i?.end}`)
};

/**
* | output |
* | --- |
* | "UTC period: {start} – {end}" |
*
* @param {Settings_Usage_PeriodInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage_period = /** @type {((inputs: Settings_Usage_PeriodInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Usage_PeriodInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage_period(inputs)
	if (locale === "ja") return ja_settings_usage_period(inputs)
	return en_settings_usage_period(inputs)
});