/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown> }} Settings_Usage_LatestversionInputs */

const en_settings_usage_latestversion = /** @type {(inputs: Settings_Usage_LatestversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Latest v${i?.version}`)
};

const zh_cn2_settings_usage_latestversion = /** @type {(inputs: Settings_Usage_LatestversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最新 v${i?.version}`)
};

const ja_settings_usage_latestversion = /** @type {(inputs: Settings_Usage_LatestversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最新の v${i?.version}`)
};

/**
* | output |
* | --- |
* | "Latest v{version}" |
*
* @param {Settings_Usage_LatestversionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage_latestversion = /** @type {((inputs: Settings_Usage_LatestversionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Usage_LatestversionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage_latestversion(inputs)
	if (locale === "ja") return ja_settings_usage_latestversion(inputs)
	return en_settings_usage_latestversion(inputs)
});