import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Search_Scope_HintInputs */

const en_settings_search_scope_hint = /** @type {(inputs: Settings_Search_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose which language this search placeholder applies to. Leave it empty to use the default.`)
};

const zh_cn2_settings_search_scope_hint = /** @type {(inputs: Settings_Search_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择此搜索占位符适用的语言。将其留空以使用默认值。`)
};

const ja_settings_search_scope_hint = /** @type {(inputs: Settings_Search_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`この検索プレースホルダーが適用される言語を選択します。デフォルトを使用するには、空のままにしておきます。`)
};

/**
* | output |
* | --- |
* | "Choose which language this search placeholder applies to. Leave it empty to use the default." |
*
* @param {Settings_Search_Scope_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_search_scope_hint = /** @type {((inputs?: Settings_Search_Scope_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Search_Scope_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_search_scope_hint(inputs)
	if (locale === "ja") return ja_settings_search_scope_hint(inputs)
	return en_settings_search_scope_hint(inputs)
});