/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_Dns_HeadingInputs */

const en_settings_domain_dns_heading = /** @type {(inputs: Settings_Domain_Dns_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add this DNS record at your provider`)
};

const zh_cn2_settings_domain_dns_heading = /** @type {(inputs: Settings_Domain_Dns_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`在您的提供商处添加此 DNS 记录`)
};

const ja_settings_domain_dns_heading = /** @type {(inputs: Settings_Domain_Dns_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`この DNS レコードをプロバイダーに追加します`)
};

/**
* | output |
* | --- |
* | "Add this DNS record at your provider" |
*
* @param {Settings_Domain_Dns_HeadingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_dns_heading = /** @type {((inputs?: Settings_Domain_Dns_HeadingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_Dns_HeadingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_dns_heading(inputs)
	if (locale === "ja") return ja_settings_domain_dns_heading(inputs)
	return en_settings_domain_dns_heading(inputs)
});