/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ imported: NonNullable<unknown>, updated: NonNullable<unknown>, skipped: NonNullable<unknown> }} Settings_Import_ResultInputs */

const en_settings_import_result = /** @type {(inputs: Settings_Import_ResultInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Imported ${i?.imported} new, updated ${i?.updated}, skipped ${i?.skipped}.`)
};

const zh_cn2_settings_import_result = /** @type {(inputs: Settings_Import_ResultInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`导入了新的 ${i?.imported}，更新了 ${i?.updated}，跳过了 ${i?.skipped}。`)
};

const ja_settings_import_result = /** @type {(inputs: Settings_Import_ResultInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.imported} を新規にインポートし、${i?.updated} を更新し、${i?.skipped} をスキップしました。`)
};

/**
* | output |
* | --- |
* | "Imported {imported} new, updated {updated}, skipped {skipped}." |
*
* @param {Settings_Import_ResultInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_result = /** @type {((inputs: Settings_Import_ResultInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_ResultInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_result(inputs)
	if (locale === "ja") return ja_settings_import_result(inputs)
	return en_settings_import_result(inputs)
});