import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Admin_Site_AssetcountInputs */

const en_admin_site_assetcount = /** @type {(inputs: Admin_Site_AssetcountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} assets`)
};

const zh_cn2_admin_site_assetcount = /** @type {(inputs: Admin_Site_AssetcountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 个资源`)
};

const ja_admin_site_assetcount = /** @type {(inputs: Admin_Site_AssetcountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} アセット`)
};

/**
* | output |
* | --- |
* | "{count} assets" |
*
* @param {Admin_Site_AssetcountInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_site_assetcount = /** @type {((inputs: Admin_Site_AssetcountInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Site_AssetcountInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_site_assetcount(inputs)
	if (locale === "ja") return ja_admin_site_assetcount(inputs)
	return en_admin_site_assetcount(inputs)
});