import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_Toast_ProvisioningInputs */

const en_settings_domain_toast_provisioning = /** @type {(inputs: Settings_Domain_Toast_ProvisioningInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`DNS is ready; TLS is still provisioning`)
};

const zh_cn2_settings_domain_toast_provisioning = /** @type {(inputs: Settings_Domain_Toast_ProvisioningInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`DNS 已准备就绪； TLS 仍在配置中`)
};

const ja_settings_domain_toast_provisioning = /** @type {(inputs: Settings_Domain_Toast_ProvisioningInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`DNS の準備が完了しました。 TLS はまだプロビジョニング中です`)
};

/**
* | output |
* | --- |
* | "DNS is ready; TLS is still provisioning" |
*
* @param {Settings_Domain_Toast_ProvisioningInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_toast_provisioning = /** @type {((inputs?: Settings_Domain_Toast_ProvisioningInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_Toast_ProvisioningInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_toast_provisioning(inputs)
	if (locale === "ja") return ja_settings_domain_toast_provisioning(inputs)
	return en_settings_domain_toast_provisioning(inputs)
});