/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ days: NonNullable<unknown> }} Admin_Overview_NosignupsInputs */

const en_admin_overview_nosignups = /** @type {(inputs: Admin_Overview_NosignupsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`No sign-ups in the last ${i?.days} days`)
};

const zh_cn2_admin_overview_nosignups = /** @type {(inputs: Admin_Overview_NosignupsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`No sign-ups in the last ${i?.days} days`)
};

const ja_admin_overview_nosignups = /** @type {(inputs: Admin_Overview_NosignupsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`過去 ${i?.days} 日間にサインアップはありませんでした`)
};

/**
* | output |
* | --- |
* | "No sign-ups in the last {days} days" |
*
* @param {Admin_Overview_NosignupsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_overview_nosignups = /** @type {((inputs: Admin_Overview_NosignupsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Overview_NosignupsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_overview_nosignups(inputs)
	if (locale === "ja") return ja_admin_overview_nosignups(inputs)
	return en_admin_overview_nosignups(inputs)
});