import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Account_Language_NoresultsInputs */

const en_account_language_noresults = /** @type {(inputs: Account_Language_NoresultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No languages found.`)
};

const zh_cn2_account_language_noresults = /** @type {(inputs: Account_Language_NoresultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`未找到语言。`)
};

const ja_account_language_noresults = /** @type {(inputs: Account_Language_NoresultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語が見つかりません。`)
};

/**
* | output |
* | --- |
* | "No languages found." |
*
* @param {Account_Language_NoresultsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const account_language_noresults = /** @type {((inputs?: Account_Language_NoresultsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Account_Language_NoresultsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_account_language_noresults(inputs)
	if (locale === "ja") return ja_account_language_noresults(inputs)
	return en_account_language_noresults(inputs)
});