/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_FailedInputs */

const en_publish_failed = /** @type {(inputs: Publish_FailedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Publish failed`)
};

const zh_cn2_publish_failed = /** @type {(inputs: Publish_FailedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`发布失败`)
};

const ja_publish_failed = /** @type {(inputs: Publish_FailedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公開に失敗しました`)
};

/**
* | output |
* | --- |
* | "Publish failed" |
*
* @param {Publish_FailedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_failed = /** @type {((inputs?: Publish_FailedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_FailedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_failed(inputs)
	if (locale === "ja") return ja_publish_failed(inputs)
	return en_publish_failed(inputs)
});