import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Invite_SkipInputs */

const en_auth_invite_skip = /** @type {(inputs: Auth_Invite_SkipInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Skip for now`)
};

const zh_cn2_auth_invite_skip = /** @type {(inputs: Auth_Invite_SkipInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`暂时跳过`)
};

const ja_auth_invite_skip = /** @type {(inputs: Auth_Invite_SkipInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`今のところスキップしてください`)
};

/**
* | output |
* | --- |
* | "Skip for now" |
*
* @param {Auth_Invite_SkipInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_skip = /** @type {((inputs?: Auth_Invite_SkipInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_SkipInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_skip(inputs)
	if (locale === "ja") return ja_auth_invite_skip(inputs)
	return en_auth_invite_skip(inputs)
});