import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Account_SignoutInputs */

const en_account_signout = /** @type {(inputs: Account_SignoutInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Sign out`)
};

const zh_cn2_account_signout = /** @type {(inputs: Account_SignoutInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`退出`)
};

const ja_account_signout = /** @type {(inputs: Account_SignoutInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`サインアウト`)
};

/**
* | output |
* | --- |
* | "Sign out" |
*
* @param {Account_SignoutInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const account_signout = /** @type {((inputs?: Account_SignoutInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Account_SignoutInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_account_signout(inputs)
	if (locale === "ja") return ja_account_signout(inputs)
	return en_account_signout(inputs)
});