import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_PagetitleplaceholderInputs */

const en_editor_pagetitleplaceholder = /** @type {(inputs: Editor_PagetitleplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Page title`)
};

const zh_cn2_editor_pagetitleplaceholder = /** @type {(inputs: Editor_PagetitleplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`页面标题`)
};

const ja_editor_pagetitleplaceholder = /** @type {(inputs: Editor_PagetitleplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ページタイトル`)
};

/**
* | output |
* | --- |
* | "Page title" |
*
* @param {Editor_PagetitleplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_pagetitleplaceholder = /** @type {((inputs?: Editor_PagetitleplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_PagetitleplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_pagetitleplaceholder(inputs)
	if (locale === "ja") return ja_editor_pagetitleplaceholder(inputs)
	return en_editor_pagetitleplaceholder(inputs)
});