import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_DescriptionInputs */

const en_settings_import_ghost_description = /** @type {(inputs: Settings_Import_Ghost_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Upload a Ghost JSON export — published posts and pages are converted to Markdown.`)
};

const zh_cn2_settings_import_ghost_description = /** @type {(inputs: Settings_Import_Ghost_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`上传 Ghost JSON 导出 — 发布的帖子和页面将转换为 Markdown。`)
};

const ja_settings_import_ghost_description = /** @type {(inputs: Settings_Import_Ghost_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ghost JSON エクスポートをアップロードします。公開された投稿とページは Markdown に変換されます。`)
};

/**
* | output |
* | --- |
* | "Upload a Ghost JSON export — published posts and pages are converted to Markdown." |
*
* @param {Settings_Import_Ghost_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_description = /** @type {((inputs?: Settings_Import_Ghost_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_description(inputs)
	if (locale === "ja") return ja_settings_import_ghost_description(inputs)
	return en_settings_import_ghost_description(inputs)
});