/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_SecurityhintInputs */

const en_settings_openapi_securityhint = /** @type {(inputs: Settings_Openapi_SecurityhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms does not store API credentials or proxy try-it requests. Readers enter credentials in Scalar, and the API server must allow their site origin with CORS.`)
};

const zh_cn2_settings_openapi_securityhint = /** @type {(inputs: Settings_Openapi_SecurityhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms 不存储 API 凭据或代理尝试请求。读者在 Scalar 中输入凭据，并且 API 服务器必须允许其站点来源为 CORS。`)
};

const ja_settings_openapi_securityhint = /** @type {(inputs: Settings_Openapi_SecurityhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms は、API 認証情報やプロキシ try-it リクエストを保存しません。リーダーは Scalar で資格情報を入力し、API サーバーは CORS を使用したサイトのオリジンを許可する必要があります。`)
};

/**
* | output |
* | --- |
* | "cms does not store API credentials or proxy try-it requests. Readers enter credentials in Scalar, and the API server must allow their site origin with CORS." |
*
* @param {Settings_Openapi_SecurityhintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_securityhint = /** @type {((inputs?: Settings_Openapi_SecurityhintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_SecurityhintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_securityhint(inputs)
	if (locale === "ja") return ja_settings_openapi_securityhint(inputs)
	return en_settings_openapi_securityhint(inputs)
});