/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_AddedInputs */

const en_publish_added = /** @type {(inputs: Publish_AddedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`New`)
};

const zh_cn2_publish_added = /** @type {(inputs: Publish_AddedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新`)
};

const ja_publish_added = /** @type {(inputs: Publish_AddedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新しい`)
};

/**
* | output |
* | --- |
* | "New" |
*
* @param {Publish_AddedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_added = /** @type {((inputs?: Publish_AddedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_AddedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_added(inputs)
	if (locale === "ja") return ja_publish_added(inputs)
	return en_publish_added(inputs)
});