import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Workflow_LoadingInputs */

const en_settings_git_workflow_loading = /** @type {(inputs: Settings_Git_Workflow_LoadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Loading Git connection…`)
};

const zh_cn2_settings_git_workflow_loading = /** @type {(inputs: Settings_Git_Workflow_LoadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`正在加载 Git 连接...`)
};

const ja_settings_git_workflow_loading = /** @type {(inputs: Settings_Git_Workflow_LoadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (``)
};

/**
* | output |
* | --- |
* | "Loading Git connection…" |
*
* @param {Settings_Git_Workflow_LoadingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_workflow_loading = /** @type {((inputs?: Settings_Git_Workflow_LoadingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Workflow_LoadingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_workflow_loading(inputs)
	if (locale === "ja") return ja_settings_git_workflow_loading(inputs)
	return en_settings_git_workflow_loading(inputs)
});