import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_ContinueInputs */

const en_settings_import_continue = /** @type {(inputs: Settings_Import_ContinueInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Review import`)
};

const zh_cn2_settings_import_continue = /** @type {(inputs: Settings_Import_ContinueInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`审核导入`)
};

const ja_settings_import_continue = /** @type {(inputs: Settings_Import_ContinueInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`インポートのレビュー`)
};

/**
* | output |
* | --- |
* | "Review import" |
*
* @param {Settings_Import_ContinueInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_continue = /** @type {((inputs?: Settings_Import_ContinueInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_ContinueInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_continue(inputs)
	if (locale === "ja") return ja_settings_import_continue(inputs)
	return en_settings_import_continue(inputs)
});