import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Brand_StatusInputs */

const en_auth_brand_status = /** @type {(inputs: Auth_Brand_StatusInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Cloud deployment active`)
};

const zh_cn2_auth_brand_status = /** @type {(inputs: Auth_Brand_StatusInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`云部署活跃`)
};

const ja_auth_brand_status = /** @type {(inputs: Auth_Brand_StatusInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`クラウド展開がアクティブです`)
};

/**
* | output |
* | --- |
* | "Cloud deployment active" |
*
* @param {Auth_Brand_StatusInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_brand_status = /** @type {((inputs?: Auth_Brand_StatusInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Brand_StatusInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_brand_status(inputs)
	if (locale === "ja") return ja_auth_brand_status(inputs)
	return en_auth_brand_status(inputs)
});