import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_General_Url_ErrorInputs */

const en_settings_general_url_error = /** @type {(inputs: Settings_General_Url_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Use 1-63 lowercase letters, numbers, and hyphens.`)
};

const zh_cn2_settings_general_url_error = /** @type {(inputs: Settings_General_Url_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`使用 1-63 个小写字母、数字和连字符。`)
};

const ja_settings_general_url_error = /** @type {(inputs: Settings_General_Url_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`1 ～ 63 文字の小文字、数字、ハイフンを使用します。`)
};

/**
* | output |
* | --- |
* | "Use 1-63 lowercase letters, numbers, and hyphens." |
*
* @param {Settings_General_Url_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_general_url_error = /** @type {((inputs?: Settings_General_Url_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_General_Url_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_general_url_error(inputs)
	if (locale === "ja") return ja_settings_general_url_error(inputs)
	return en_settings_general_url_error(inputs)
});