/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Dashboard_Empty_TitleInputs */

const en_dashboard_empty_title = /** @type {(inputs: Dashboard_Empty_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No projects yet`)
};

const zh_cn2_dashboard_empty_title = /** @type {(inputs: Dashboard_Empty_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`还没有项目`)
};

const ja_dashboard_empty_title = /** @type {(inputs: Dashboard_Empty_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだプロジェクトはありません`)
};

/**
* | output |
* | --- |
* | "No projects yet" |
*
* @param {Dashboard_Empty_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const dashboard_empty_title = /** @type {((inputs?: Dashboard_Empty_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Dashboard_Empty_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_dashboard_empty_title(inputs)
	if (locale === "ja") return ja_dashboard_empty_title(inputs)
	return en_dashboard_empty_title(inputs)
});