/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Editor_Branch_CreatedInputs */

const en_editor_branch_created = /** @type {(inputs: Editor_Branch_CreatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Created version “${i?.name}”`)
};

const zh_cn2_editor_branch_created = /** @type {(inputs: Editor_Branch_CreatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`创建版本“${i?.name}”`)
};

const ja_editor_branch_created = /** @type {(inputs: Editor_Branch_CreatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`作成されたバージョン「${i?.name}」`)
};

/**
* | output |
* | --- |
* | "Created version “{name}”" |
*
* @param {Editor_Branch_CreatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_branch_created = /** @type {((inputs: Editor_Branch_CreatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Branch_CreatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_branch_created(inputs)
	if (locale === "ja") return ja_editor_branch_created(inputs)
	return en_editor_branch_created(inputs)
});