/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Settings_Danger_Transfer_ConfirmInputs */

const en_settings_danger_transfer_confirm = /** @type {(inputs: Settings_Danger_Transfer_ConfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Transfer ownership to ${i?.name}? Your role will change to admin.`)
};

const zh_cn2_settings_danger_transfer_confirm = /** @type {(inputs: Settings_Danger_Transfer_ConfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`将所有权转让给 ${i?.name}？您的角色将更改为管理员。`)
};

const ja_settings_danger_transfer_confirm = /** @type {(inputs: Settings_Danger_Transfer_ConfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`所有権を ${i?.name} に譲渡しますか?あなたの役割は管理者に変更されます。`)
};

/**
* | output |
* | --- |
* | "Transfer ownership to {name}? Your role will change to admin." |
*
* @param {Settings_Danger_Transfer_ConfirmInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_danger_transfer_confirm = /** @type {((inputs: Settings_Danger_Transfer_ConfirmInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Danger_Transfer_ConfirmInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_danger_transfer_confirm(inputs)
	if (locale === "ja") return ja_settings_danger_transfer_confirm(inputs)
	return en_settings_danger_transfer_confirm(inputs)
});