import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Settings_Members_Count_OneInputs */

const en_settings_members_count_one = /** @type {(inputs: Settings_Members_Count_OneInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} member`)
};

const zh_cn2_settings_members_count_one = /** @type {(inputs: Settings_Members_Count_OneInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 成员`)
};

const ja_settings_members_count_one = /** @type {(inputs: Settings_Members_Count_OneInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} メンバー`)
};

/**
* | output |
* | --- |
* | "{count} member" |
*
* @param {Settings_Members_Count_OneInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_members_count_one = /** @type {((inputs: Settings_Members_Count_OneInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Members_Count_OneInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_members_count_one(inputs)
	if (locale === "ja") return ja_settings_members_count_one(inputs)
	return en_settings_members_count_one(inputs)
});