import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Branding_TitleInputs */

const en_settings_branding_title = /** @type {(inputs: Settings_Branding_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Branding`)
};

const zh_cn2_settings_branding_title = /** @type {(inputs: Settings_Branding_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`品牌推广`)
};

const ja_settings_branding_title = /** @type {(inputs: Settings_Branding_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ブランディング`)
};

/**
* | output |
* | --- |
* | "Branding" |
*
* @param {Settings_Branding_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_branding_title = /** @type {((inputs?: Settings_Branding_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Branding_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_branding_title(inputs)
	if (locale === "ja") return ja_settings_branding_title(inputs)
	return en_settings_branding_title(inputs)
});