/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ImporttitleInputs */

const en_settings_theme_importtitle = /** @type {(inputs: Settings_Theme_ImporttitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import safely`)
};

const zh_cn2_settings_theme_importtitle = /** @type {(inputs: Settings_Theme_ImporttitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`安全进口`)
};

const ja_settings_theme_importtitle = /** @type {(inputs: Settings_Theme_ImporttitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`安全に輸入する`)
};

/**
* | output |
* | --- |
* | "Import safely" |
*
* @param {Settings_Theme_ImporttitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_importtitle = /** @type {((inputs?: Settings_Theme_ImporttitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ImporttitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_importtitle(inputs)
	if (locale === "ja") return ja_settings_theme_importtitle(inputs)
	return en_settings_theme_importtitle(inputs)
});