/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ percent: NonNullable<unknown> }} Settings_Languages_Coverage_PercentInputs */

const en_settings_languages_coverage_percent = /** @type {(inputs: Settings_Languages_Coverage_PercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.percent}% coverage`)
};

const zh_cn2_settings_languages_coverage_percent = /** @type {(inputs: Settings_Languages_Coverage_PercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.percent}% 覆盖率`)
};

const ja_settings_languages_coverage_percent = /** @type {(inputs: Settings_Languages_Coverage_PercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.percent}% カバレッジ`)
};

/**
* | output |
* | --- |
* | "{percent}% coverage" |
*
* @param {Settings_Languages_Coverage_PercentInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_coverage_percent = /** @type {((inputs: Settings_Languages_Coverage_PercentInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_Coverage_PercentInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_coverage_percent(inputs)
	if (locale === "ja") return ja_settings_languages_coverage_percent(inputs)
	return en_settings_languages_coverage_percent(inputs)
});