/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_SubtitleInputs */

const en_publish_subtitle = /** @type {(inputs: Publish_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Your changes go live instantly on your domain.`)
};

const zh_cn2_publish_subtitle = /** @type {(inputs: Publish_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您的更改会立即在您的域上生效。`)
};

const ja_publish_subtitle = /** @type {(inputs: Publish_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`変更はドメイン上で即座に有効になります。`)
};

/**
* | output |
* | --- |
* | "Your changes go live instantly on your domain." |
*
* @param {Publish_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_subtitle = /** @type {((inputs?: Publish_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_subtitle(inputs)
	if (locale === "ja") return ja_publish_subtitle(inputs)
	return en_publish_subtitle(inputs)
});