import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_CloseInputs */

const en_deploy_close = /** @type {(inputs: Deploy_CloseInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Close`)
};

const zh_cn2_deploy_close = /** @type {(inputs: Deploy_CloseInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`关闭`)
};

const ja_deploy_close = /** @type {(inputs: Deploy_CloseInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`近い`)
};

/**
* | output |
* | --- |
* | "Close" |
*
* @param {Deploy_CloseInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_close = /** @type {((inputs?: Deploy_CloseInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_CloseInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_close(inputs)
	if (locale === "ja") return ja_deploy_close(inputs)
	return en_deploy_close(inputs)
});