/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ when: NonNullable<unknown> }} Admin_Site_LastsyncedInputs */

const en_admin_site_lastsynced = /** @type {(inputs: Admin_Site_LastsyncedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Last synced ${i?.when}`)
};

const zh_cn2_admin_site_lastsynced = /** @type {(inputs: Admin_Site_LastsyncedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`上次同步于 ${i?.when}`)
};

const ja_admin_site_lastsynced = /** @type {(inputs: Admin_Site_LastsyncedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最後に同期した${i?.when}`)
};

/**
* | output |
* | --- |
* | "Last synced {when}" |
*
* @param {Admin_Site_LastsyncedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_site_lastsynced = /** @type {((inputs: Admin_Site_LastsyncedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Site_LastsyncedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_site_lastsynced(inputs)
	if (locale === "ja") return ja_admin_site_lastsynced(inputs)
	return en_admin_site_lastsynced(inputs)
});