import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_Import_AppliedInputs */

const en_settings_theme_import_applied = /** @type {(inputs: Settings_Theme_Import_AppliedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Theme template applied to the draft`)
};

const zh_cn2_settings_theme_import_applied = /** @type {(inputs: Settings_Theme_Import_AppliedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`应用于草稿的主题模板`)
};

const ja_settings_theme_import_applied = /** @type {(inputs: Settings_Theme_Import_AppliedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドラフトに適用されたテーマ テンプレート`)
};

/**
* | output |
* | --- |
* | "Theme template applied to the draft" |
*
* @param {Settings_Theme_Import_AppliedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_import_applied = /** @type {((inputs?: Settings_Theme_Import_AppliedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_Import_AppliedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_import_applied(inputs)
	if (locale === "ja") return ja_settings_theme_import_applied(inputs)
	return en_settings_theme_import_applied(inputs)
});