import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_Nudge_DismissInputs */

const en_overview_nudge_dismiss = /** @type {(inputs: Overview_Nudge_DismissInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Dismiss`)
};

const zh_cn2_overview_nudge_dismiss = /** @type {(inputs: Overview_Nudge_DismissInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`解雇`)
};

const ja_overview_nudge_dismiss = /** @type {(inputs: Overview_Nudge_DismissInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`却下する`)
};

/**
* | output |
* | --- |
* | "Dismiss" |
*
* @param {Overview_Nudge_DismissInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_nudge_dismiss = /** @type {((inputs?: Overview_Nudge_DismissInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_Nudge_DismissInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_nudge_dismiss(inputs)
	if (locale === "ja") return ja_overview_nudge_dismiss(inputs)
	return en_overview_nudge_dismiss(inputs)
});