import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ExporterrorInputs */

const en_settings_theme_exporterror = /** @type {(inputs: Settings_Theme_ExporterrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not export the theme template`)
};

const zh_cn2_settings_theme_exporterror = /** @type {(inputs: Settings_Theme_ExporterrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法导出主题模板`)
};

const ja_settings_theme_exporterror = /** @type {(inputs: Settings_Theme_ExporterrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`テーマテンプレートをエクスポートできませんでした`)
};

/**
* | output |
* | --- |
* | "Could not export the theme template" |
*
* @param {Settings_Theme_ExporterrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_exporterror = /** @type {((inputs?: Settings_Theme_ExporterrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ExporterrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_exporterror(inputs)
	if (locale === "ja") return ja_settings_theme_exporterror(inputs)
	return en_settings_theme_exporterror(inputs)
});