/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ when: NonNullable<unknown> }} Settings_Git_Import_LastimportedInputs */

const en_settings_git_import_lastimported = /** @type {(inputs: Settings_Git_Import_LastimportedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Last imported ${i?.when}`)
};

const zh_cn2_settings_git_import_lastimported = /** @type {(inputs: Settings_Git_Import_LastimportedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最后导入 ${i?.when}`)
};

const ja_settings_git_import_lastimported = /** @type {(inputs: Settings_Git_Import_LastimportedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最後にインポートされた${i?.when}`)
};

/**
* | output |
* | --- |
* | "Last imported {when}" |
*
* @param {Settings_Git_Import_LastimportedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_import_lastimported = /** @type {((inputs: Settings_Git_Import_LastimportedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Import_LastimportedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_import_lastimported(inputs)
	if (locale === "ja") return ja_settings_git_import_lastimported(inputs)
	return en_settings_git_import_lastimported(inputs)
});