/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Members_TitleInputs */

const en_members_title = /** @type {(inputs: Members_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Members`)
};

const zh_cn2_members_title = /** @type {(inputs: Members_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`会员`)
};

const ja_members_title = /** @type {(inputs: Members_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`メンバー`)
};

/**
* | output |
* | --- |
* | "Members" |
*
* @param {Members_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const members_title = /** @type {((inputs?: Members_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Members_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_members_title(inputs)
	if (locale === "ja") return ja_members_title(inputs)
	return en_members_title(inputs)
});