/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Google_SubmittingInputs */

const en_auth_google_submitting = /** @type {(inputs: Auth_Google_SubmittingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Opening Google…`)
};

const zh_cn2_auth_google_submitting = /** @type {(inputs: Auth_Google_SubmittingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`打开 Google...`)
};

const ja_auth_google_submitting = /** @type {(inputs: Auth_Google_SubmittingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Googleを開いて…`)
};

/**
* | output |
* | --- |
* | "Opening Google…" |
*
* @param {Auth_Google_SubmittingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_google_submitting = /** @type {((inputs?: Auth_Google_SubmittingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Google_SubmittingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_google_submitting(inputs)
	if (locale === "ja") return ja_auth_google_submitting(inputs)
	return en_auth_google_submitting(inputs)
});