/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_HeadingInputs */

const en_settings_heading = /** @type {(inputs: Settings_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Site configurations`)
};

const zh_cn2_settings_heading = /** @type {(inputs: Settings_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`站点配置`)
};

const ja_settings_heading = /** @type {(inputs: Settings_HeadingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`サイト構成`)
};

/**
* | output |
* | --- |
* | "Site configurations" |
*
* @param {Settings_HeadingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_heading = /** @type {((inputs?: Settings_HeadingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_HeadingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_heading(inputs)
	if (locale === "ja") return ja_settings_heading(inputs)
	return en_settings_heading(inputs)
});