/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ label: NonNullable<unknown> }} Editor_Addlanguage_AddedInputs */

const en_editor_addlanguage_added = /** @type {(inputs: Editor_Addlanguage_AddedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Added ${i?.label}.`)
};

const zh_cn2_editor_addlanguage_added = /** @type {(inputs: Editor_Addlanguage_AddedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`添加了 ${i?.label}。`)
};

const ja_editor_addlanguage_added = /** @type {(inputs: Editor_Addlanguage_AddedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.label} を追加しました。`)
};

/**
* | output |
* | --- |
* | "Added {label}." |
*
* @param {Editor_Addlanguage_AddedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_addlanguage_added = /** @type {((inputs: Editor_Addlanguage_AddedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Addlanguage_AddedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_addlanguage_added(inputs)
	if (locale === "ja") return ja_editor_addlanguage_added(inputs)
	return en_editor_addlanguage_added(inputs)
});