import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ percent: NonNullable<unknown> }} Admin_Overview_SignuppercentInputs */

const en_admin_overview_signuppercent = /** @type {(inputs: Admin_Overview_SignuppercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.percent} of sign-ups`)
};

const zh_cn2_admin_overview_signuppercent = /** @type {(inputs: Admin_Overview_SignuppercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.percent} of sign-ups`)
};

const ja_admin_overview_signuppercent = /** @type {(inputs: Admin_Overview_SignuppercentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`登録数の ${i?.percent}`)
};

/**
* | output |
* | --- |
* | "{percent} of sign-ups" |
*
* @param {Admin_Overview_SignuppercentInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_overview_signuppercent = /** @type {((inputs: Admin_Overview_SignuppercentInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Overview_SignuppercentInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_overview_signuppercent(inputs)
	if (locale === "ja") return ja_admin_overview_signuppercent(inputs)
	return en_admin_overview_signuppercent(inputs)
});