/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_ChoosefileInputs */

const en_settings_openapi_choosefile = /** @type {(inputs: Settings_Openapi_ChoosefileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose an OpenAPI JSON or YAML file`)
};

const zh_cn2_settings_openapi_choosefile = /** @type {(inputs: Settings_Openapi_ChoosefileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择 OpenAPI JSON 或 YAML 文件`)
};

const ja_settings_openapi_choosefile = /** @type {(inputs: Settings_Openapi_ChoosefileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`OpenAPI JSON または YAML ファイルを選択してください`)
};

/**
* | output |
* | --- |
* | "Choose an OpenAPI JSON or YAML file" |
*
* @param {Settings_Openapi_ChoosefileInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_choosefile = /** @type {((inputs?: Settings_Openapi_ChoosefileInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_ChoosefileInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_choosefile(inputs)
	if (locale === "ja") return ja_settings_openapi_choosefile(inputs)
	return en_settings_openapi_choosefile(inputs)
});