/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ path: NonNullable<unknown> }} Settings_Addons_Editurl_HintInputs */

const en_settings_addons_editurl_hint = /** @type {(inputs: Settings_Addons_Editurl_HintInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Use ${i?.path} for the current docs path, for example a GitHub edit URL.`)
};

const zh_cn2_settings_addons_editurl_hint = /** @type {(inputs: Settings_Addons_Editurl_HintInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`使用 ${i?.path} 作为当前文档路径，例如 GitHub 编辑 URL。`)
};

const ja_settings_addons_editurl_hint = /** @type {(inputs: Settings_Addons_Editurl_HintInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`現在のドキュメント パスには ${i?.path} を使用します (GitHub 編集 URL など)。`)
};

/**
* | output |
* | --- |
* | "Use {path} for the current docs path, for example a GitHub edit URL." |
*
* @param {Settings_Addons_Editurl_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_addons_editurl_hint = /** @type {((inputs: Settings_Addons_Editurl_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Addons_Editurl_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_addons_editurl_hint(inputs)
	if (locale === "ja") return ja_settings_addons_editurl_hint(inputs)
	return en_settings_addons_editurl_hint(inputs)
});