import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_PathInputs */

const en_settings_openapi_path = /** @type {(inputs: Settings_Openapi_PathInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Published path`)
};

const zh_cn2_settings_openapi_path = /** @type {(inputs: Settings_Openapi_PathInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`发布路径`)
};

const ja_settings_openapi_path = /** @type {(inputs: Settings_Openapi_PathInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公開されたパス`)
};

/**
* | output |
* | --- |
* | "Published path" |
*
* @param {Settings_Openapi_PathInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_path = /** @type {((inputs?: Settings_Openapi_PathInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_PathInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_path(inputs)
	if (locale === "ja") return ja_settings_openapi_path(inputs)
	return en_settings_openapi_path(inputs)
});