import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_RedirectsblockedInputs */

const en_publish_redirectsblocked = /** @type {(inputs: Publish_RedirectsblockedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Redirects must be fixed before publishing`)
};

const zh_cn2_publish_redirectsblocked = /** @type {(inputs: Publish_RedirectsblockedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`发布前必须修复重定向`)
};

const ja_publish_redirectsblocked = /** @type {(inputs: Publish_RedirectsblockedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`リダイレクトは公開前に修正する必要があります`)
};

/**
* | output |
* | --- |
* | "Redirects must be fixed before publishing" |
*
* @param {Publish_RedirectsblockedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_redirectsblocked = /** @type {((inputs?: Publish_RedirectsblockedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_RedirectsblockedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_redirectsblocked(inputs)
	if (locale === "ja") return ja_publish_redirectsblocked(inputs)
	return en_publish_redirectsblocked(inputs)
});