/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Preview_DescriptionInputs */

const en_preview_description = /** @type {(inputs: Preview_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Review the current draft branch before publishing.`)
};

const zh_cn2_preview_description = /** @type {(inputs: Preview_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`在发布之前查看当前草稿分支。`)
};

const ja_preview_description = /** @type {(inputs: Preview_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公開する前に、現在のドラフト ブランチを確認してください。`)
};

/**
* | output |
* | --- |
* | "Review the current draft branch before publishing." |
*
* @param {Preview_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const preview_description = /** @type {((inputs?: Preview_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Preview_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_preview_description(inputs)
	if (locale === "ja") return ja_preview_description(inputs)
	return en_preview_description(inputs)
});