/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_DoneInputs */

const en_deploy_done = /** @type {(inputs: Deploy_DoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Done`)
};

const zh_cn2_deploy_done = /** @type {(inputs: Deploy_DoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`完成`)
};

const ja_deploy_done = /** @type {(inputs: Deploy_DoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`終わり`)
};

/**
* | output |
* | --- |
* | "Done" |
*
* @param {Deploy_DoneInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_done = /** @type {((inputs?: Deploy_DoneInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_DoneInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_done(inputs)
	if (locale === "ja") return ja_deploy_done(inputs)
	return en_deploy_done(inputs)
});