/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Invite_NotfoundInputs */

const en_auth_invite_notfound = /** @type {(inputs: Auth_Invite_NotfoundInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`This invitation could not be found. The link may be invalid or already used.`)
};

const zh_cn2_auth_invite_notfound = /** @type {(inputs: Auth_Invite_NotfoundInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`找不到此邀请。该链接可能无效或已被使用。`)
};

const ja_auth_invite_notfound = /** @type {(inputs: Auth_Invite_NotfoundInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`この招待状は見つかりませんでした。リンクが無効であるか、すでに使用されている可能性があります。`)
};

/**
* | output |
* | --- |
* | "This invitation could not be found. The link may be invalid or already used." |
*
* @param {Auth_Invite_NotfoundInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_notfound = /** @type {((inputs?: Auth_Invite_NotfoundInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_NotfoundInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_notfound(inputs)
	if (locale === "ja") return ja_auth_invite_notfound(inputs)
	return en_auth_invite_notfound(inputs)
});