import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_SyncedInputs */

const en_settings_openapi_synced = /** @type {(inputs: Settings_Openapi_SyncedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`OpenAPI source refreshed`)
};

const zh_cn2_settings_openapi_synced = /** @type {(inputs: Settings_Openapi_SyncedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`OpenAPI 源已刷新`)
};

const ja_settings_openapi_synced = /** @type {(inputs: Settings_Openapi_SyncedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`OpenAPI ソースが更新されました`)
};

/**
* | output |
* | --- |
* | "OpenAPI source refreshed" |
*
* @param {Settings_Openapi_SyncedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_synced = /** @type {((inputs?: Settings_Openapi_SyncedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_SyncedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_synced(inputs)
	if (locale === "ja") return ja_settings_openapi_synced(inputs)
	return en_settings_openapi_synced(inputs)
});