import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Steps_ChooseInputs */

const en_settings_import_steps_choose = /** @type {(inputs: Settings_Import_Steps_ChooseInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose source`)
};

const zh_cn2_settings_import_steps_choose = /** @type {(inputs: Settings_Import_Steps_ChooseInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择来源`)
};

const ja_settings_import_steps_choose = /** @type {(inputs: Settings_Import_Steps_ChooseInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ソースを選択してください`)
};

/**
* | output |
* | --- |
* | "Choose source" |
*
* @param {Settings_Import_Steps_ChooseInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_steps_choose = /** @type {((inputs?: Settings_Import_Steps_ChooseInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Steps_ChooseInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_steps_choose(inputs)
	if (locale === "ja") return ja_settings_import_steps_choose(inputs)
	return en_settings_import_steps_choose(inputs)
});