import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ created: NonNullable<unknown>, updated: NonNullable<unknown> }} Admin_Site_CreatedupdatedInputs */

const en_admin_site_createdupdated = /** @type {(inputs: Admin_Site_CreatedupdatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Created ${i?.created} · last updated ${i?.updated}`)
};

const zh_cn2_admin_site_createdupdated = /** @type {(inputs: Admin_Site_CreatedupdatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`创建于 ${i?.created} · 最后更新于 ${i?.updated}`)
};

const ja_admin_site_createdupdated = /** @type {(inputs: Admin_Site_CreatedupdatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`作成日 ${i?.created} · 最終更新日 ${i?.updated}`)
};

/**
* | output |
* | --- |
* | "Created {created} · last updated {updated}" |
*
* @param {Admin_Site_CreatedupdatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_site_createdupdated = /** @type {((inputs: Admin_Site_CreatedupdatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Site_CreatedupdatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_site_createdupdated(inputs)
	if (locale === "ja") return ja_admin_site_createdupdated(inputs)
	return en_admin_site_createdupdated(inputs)
});