import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Editor_Branch_MergeconfirmInputs */

const en_editor_branch_mergeconfirm = /** @type {(inputs: Editor_Branch_MergeconfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Promote “${i?.name}” into main? This replaces main’s pages with this version’s pages and removes the version.`)
};

const zh_cn2_editor_branch_mergeconfirm = /** @type {(inputs: Editor_Branch_MergeconfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`将“${i?.name}”提升到主干？这会将主页面替换为该版本的页面并删除该版本。`)
};

const ja_editor_branch_mergeconfirm = /** @type {(inputs: Editor_Branch_MergeconfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`「${i?.name}」をメインに昇格させますか?これにより、メインのページがこのバージョンのページに置き換えられ、バージョンが削除されます。`)
};

/**
* | output |
* | --- |
* | "Promote “{name}” into main? This replaces main’s pages with this version’s pages and removes the version." |
*
* @param {Editor_Branch_MergeconfirmInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_branch_mergeconfirm = /** @type {((inputs: Editor_Branch_MergeconfirmInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Branch_MergeconfirmInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_branch_mergeconfirm(inputs)
	if (locale === "ja") return ja_editor_branch_mergeconfirm(inputs)
	return en_editor_branch_mergeconfirm(inputs)
});