/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_RunningInputs */

const en_settings_import_running = /** @type {(inputs: Settings_Import_RunningInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Importing…`)
};

const zh_cn2_settings_import_running = /** @type {(inputs: Settings_Import_RunningInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`正在导入...`)
};

const ja_settings_import_running = /** @type {(inputs: Settings_Import_RunningInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`インポート中…`)
};

/**
* | output |
* | --- |
* | "Importing…" |
*
* @param {Settings_Import_RunningInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_running = /** @type {((inputs?: Settings_Import_RunningInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_RunningInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_running(inputs)
	if (locale === "ja") return ja_settings_import_running(inputs)
	return en_settings_import_running(inputs)
});