/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ matched: NonNullable<unknown>, total: NonNullable<unknown> }} Settings_Languages_Coverage_SummaryInputs */

const en_settings_languages_coverage_summary = /** @type {(inputs: Settings_Languages_Coverage_SummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.matched} of ${i?.total} source pages`)
};

const zh_cn2_settings_languages_coverage_summary = /** @type {(inputs: Settings_Languages_Coverage_SummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.matched}（共 ${i?.total} 个源页面）`)
};

const ja_settings_languages_coverage_summary = /** @type {(inputs: Settings_Languages_Coverage_SummaryInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.total} ソース ページ中 ${i?.matched}`)
};

/**
* | output |
* | --- |
* | "{matched} of {total} source pages" |
*
* @param {Settings_Languages_Coverage_SummaryInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_coverage_summary = /** @type {((inputs: Settings_Languages_Coverage_SummaryInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_Coverage_SummaryInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_coverage_summary(inputs)
	if (locale === "ja") return ja_settings_languages_coverage_summary(inputs)
	return en_settings_languages_coverage_summary(inputs)
});