/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Preview_TitleInputs */

const en_preview_title = /** @type {(inputs: Preview_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Draft preview`)
};

const zh_cn2_preview_title = /** @type {(inputs: Preview_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`草稿预览`)
};

const ja_preview_title = /** @type {(inputs: Preview_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドラフトプレビュー`)
};

/**
* | output |
* | --- |
* | "Draft preview" |
*
* @param {Preview_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const preview_title = /** @type {((inputs?: Preview_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Preview_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_preview_title(inputs)
	if (locale === "ja") return ja_preview_title(inputs)
	return en_preview_title(inputs)
});