import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Footer_Copyright_HintInputs */

const en_settings_footer_copyright_hint = /** @type {(inputs: Settings_Footer_Copyright_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Shown at the bottom of every page.`)
};

const zh_cn2_settings_footer_copyright_hint = /** @type {(inputs: Settings_Footer_Copyright_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`显示在每个页面的底部。`)
};

const ja_settings_footer_copyright_hint = /** @type {(inputs: Settings_Footer_Copyright_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`各ページの下部に表示されます。`)
};

/**
* | output |
* | --- |
* | "Shown at the bottom of every page." |
*
* @param {Settings_Footer_Copyright_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_footer_copyright_hint = /** @type {((inputs?: Settings_Footer_Copyright_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Footer_Copyright_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_footer_copyright_hint(inputs)
	if (locale === "ja") return ja_settings_footer_copyright_hint(inputs)
	return en_settings_footer_copyright_hint(inputs)
});