/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Admin_Signin_CodesentInputs */

const en_admin_signin_codesent = /** @type {(inputs: Admin_Signin_CodesentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`We sent a one-time code to ${i?.email}.`)
};

const zh_cn2_admin_signin_codesent = /** @type {(inputs: Admin_Signin_CodesentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`We sent a one-time code to ${i?.email}.`)
};

const ja_admin_signin_codesent = /** @type {(inputs: Admin_Signin_CodesentInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`ワンタイム コードを ${i?.email} に送信しました。`)
};

/**
* | output |
* | --- |
* | "We sent a one-time code to {email}." |
*
* @param {Admin_Signin_CodesentInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_signin_codesent = /** @type {((inputs: Admin_Signin_CodesentInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Signin_CodesentInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_signin_codesent(inputs)
	if (locale === "ja") return ja_admin_signin_codesent(inputs)
	return en_admin_signin_codesent(inputs)
});