import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Admin_Error_NotfoundInputs */

const en_admin_error_notfound = /** @type {(inputs: Admin_Error_NotfoundInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Page not found`)
};

const zh_cn2_admin_error_notfound = /** @type {(inputs: Admin_Error_NotfoundInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Page not found`)
};

const ja_admin_error_notfound = /** @type {(inputs: Admin_Error_NotfoundInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ページが見つかりません`)
};

/**
* | output |
* | --- |
* | "Page not found" |
*
* @param {Admin_Error_NotfoundInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_error_notfound = /** @type {((inputs?: Admin_Error_NotfoundInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Error_NotfoundInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_error_notfound(inputs)
	if (locale === "ja") return ja_admin_error_notfound(inputs)
	return en_admin_error_notfound(inputs)
});