/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_FaqtitleInputs */

const en_blog_faqtitle = /** @type {(inputs: Blog_FaqtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Frequently asked questions`)
};

const zh_cn2_blog_faqtitle = /** @type {(inputs: Blog_FaqtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Frequently asked questions`)
};

const ja_blog_faqtitle = /** @type {(inputs: Blog_FaqtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`よくある質問`)
};

/**
* | output |
* | --- |
* | "Frequently asked questions" |
*
* @param {Blog_FaqtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_faqtitle = /** @type {((inputs?: Blog_FaqtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_FaqtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_faqtitle(inputs)
	if (locale === "ja") return ja_blog_faqtitle(inputs)
	return en_blog_faqtitle(inputs)
});