import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Project_PublishingInputs */

const en_project_publishing = /** @type {(inputs: Project_PublishingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Publishing…`)
};

const zh_cn2_project_publishing = /** @type {(inputs: Project_PublishingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`出版…`)
};

const ja_project_publishing = /** @type {(inputs: Project_PublishingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公開中…`)
};

/**
* | output |
* | --- |
* | "Publishing…" |
*
* @param {Project_PublishingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const project_publishing = /** @type {((inputs?: Project_PublishingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Project_PublishingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_project_publishing(inputs)
	if (locale === "ja") return ja_project_publishing(inputs)
	return en_project_publishing(inputs)
});