/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Otp_SenderrorInputs */

const en_auth_otp_senderror = /** @type {(inputs: Auth_Otp_SenderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not send a one-time code`)
};

const zh_cn2_auth_otp_senderror = /** @type {(inputs: Auth_Otp_SenderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法发送一次性代码`)
};

const ja_auth_otp_senderror = /** @type {(inputs: Auth_Otp_SenderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ワンタイムコードを送信できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not send a one-time code" |
*
* @param {Auth_Otp_SenderrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_otp_senderror = /** @type {((inputs?: Auth_Otp_SenderrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Otp_SenderrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_otp_senderror(inputs)
	if (locale === "ja") return ja_auth_otp_senderror(inputs)
	return en_auth_otp_senderror(inputs)
});