/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_FirstpublishInputs */

const en_publish_firstpublish = /** @type {(inputs: Publish_FirstpublishInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`First publish`)
};

const zh_cn2_publish_firstpublish = /** @type {(inputs: Publish_FirstpublishInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`首次发布`)
};

const ja_publish_firstpublish = /** @type {(inputs: Publish_FirstpublishInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`最初の公開`)
};

/**
* | output |
* | --- |
* | "First publish" |
*
* @param {Publish_FirstpublishInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_firstpublish = /** @type {((inputs?: Publish_FirstpublishInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_FirstpublishInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_firstpublish(inputs)
	if (locale === "ja") return ja_publish_firstpublish(inputs)
	return en_publish_firstpublish(inputs)
});