import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Analytics_Empty_TrafficInputs */

const en_analytics_empty_traffic = /** @type {(inputs: Analytics_Empty_TrafficInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No traffic yet — publish a site and share it.`)
};

const zh_cn2_analytics_empty_traffic = /** @type {(inputs: Analytics_Empty_TrafficInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`还没有流量——发布一个网站并分享。`)
};

const ja_analytics_empty_traffic = /** @type {(inputs: Analytics_Empty_TrafficInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだトラフィックはありません。サイトを公開して共有してください。`)
};

/**
* | output |
* | --- |
* | "No traffic yet — publish a site and share it." |
*
* @param {Analytics_Empty_TrafficInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const analytics_empty_traffic = /** @type {((inputs?: Analytics_Empty_TrafficInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Analytics_Empty_TrafficInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_analytics_empty_traffic(inputs)
	if (locale === "ja") return ja_analytics_empty_traffic(inputs)
	return en_analytics_empty_traffic(inputs)
});