import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Langsettings_DescInputs */

const en_editor_langsettings_desc = /** @type {(inputs: Editor_Langsettings_DescInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`SEO defaults and behaviour for every page in this language.`)
};

const zh_cn2_editor_langsettings_desc = /** @type {(inputs: Editor_Langsettings_DescInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`该语言中每个页面的 SEO 默认值和行为。`)
};

const ja_editor_langsettings_desc = /** @type {(inputs: Editor_Langsettings_DescInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`この言語のすべてのページの SEO のデフォルトと動作。`)
};

/**
* | output |
* | --- |
* | "SEO defaults and behaviour for every page in this language." |
*
* @param {Editor_Langsettings_DescInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_langsettings_desc = /** @type {((inputs?: Editor_Langsettings_DescInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Langsettings_DescInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_langsettings_desc(inputs)
	if (locale === "ja") return ja_editor_langsettings_desc(inputs)
	return en_editor_langsettings_desc(inputs)
});