import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_UrlInputs */

const en_settings_openapi_url = /** @type {(inputs: Settings_Openapi_UrlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Public document URL`)
};

const zh_cn2_settings_openapi_url = /** @type {(inputs: Settings_Openapi_UrlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公开文档网址`)
};

const ja_settings_openapi_url = /** @type {(inputs: Settings_Openapi_UrlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`公開文書の URL`)
};

/**
* | output |
* | --- |
* | "Public document URL" |
*
* @param {Settings_Openapi_UrlInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_url = /** @type {((inputs?: Settings_Openapi_UrlInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_UrlInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_url(inputs)
	if (locale === "ja") return ja_settings_openapi_url(inputs)
	return en_settings_openapi_url(inputs)
});