/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Link_InvalidInputs */

const en_editor_link_invalid = /** @type {(inputs: Editor_Link_InvalidInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Enter a valid URL: https, mailto, tel, #anchor, or a path starting with /.`)
};

const zh_cn2_editor_link_invalid = /** @type {(inputs: Editor_Link_InvalidInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`输入有效的 URL：https、mailto、tel、#anchor 或以 / 开头的路径。`)
};

const ja_editor_link_invalid = /** @type {(inputs: Editor_Link_InvalidInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`有効な URL: https、mailto、tel、#anchor、または / で始まるパスを入力します。`)
};

/**
* | output |
* | --- |
* | "Enter a valid URL: https, mailto, tel, #anchor, or a path starting with /." |
*
* @param {Editor_Link_InvalidInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_link_invalid = /** @type {((inputs?: Editor_Link_InvalidInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Link_InvalidInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_link_invalid(inputs)
	if (locale === "ja") return ja_editor_link_invalid(inputs)
	return en_editor_link_invalid(inputs)
});