import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_Live_UnavailableInputs */

const en_overview_live_unavailable = /** @type {(inputs: Overview_Live_UnavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Not published yet`)
};

const zh_cn2_overview_live_unavailable = /** @type {(inputs: Overview_Live_UnavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`尚未发布`)
};

const ja_overview_live_unavailable = /** @type {(inputs: Overview_Live_UnavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだ公開されていません`)
};

/**
* | output |
* | --- |
* | "Not published yet" |
*
* @param {Overview_Live_UnavailableInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_live_unavailable = /** @type {((inputs?: Overview_Live_UnavailableInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_Live_UnavailableInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_live_unavailable(inputs)
	if (locale === "ja") return ja_overview_live_unavailable(inputs)
	return en_overview_live_unavailable(inputs)
});