/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown>, record: NonNullable<unknown> }} Admin_Operations_ShowingInputs */

const en_admin_operations_showing = /** @type {(inputs: Admin_Operations_ShowingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Showing ${i?.count} ${i?.record} records from the bounded recent queue.`)
};

const zh_cn2_admin_operations_showing = /** @type {(inputs: Admin_Operations_ShowingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Showing ${i?.count} ${i?.record} records from the bounded recent queue.`)
};

const ja_admin_operations_showing = /** @type {(inputs: Admin_Operations_ShowingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`制限された最近のキューからの ${i?.count} ${i?.record} レコードを表示しています。`)
};

/**
* | output |
* | --- |
* | "Showing {count} {record} records from the bounded recent queue." |
*
* @param {Admin_Operations_ShowingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_operations_showing = /** @type {((inputs: Admin_Operations_ShowingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Operations_ShowingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_operations_showing(inputs)
	if (locale === "ja") return ja_admin_operations_showing(inputs)
	return en_admin_operations_showing(inputs)
});