/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Settings_Theme_ImportchangesInputs */

const en_settings_theme_importchanges = /** @type {(inputs: Settings_Theme_ImportchangesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} proposed changes`)
};

const zh_cn2_settings_theme_importchanges = /** @type {(inputs: Settings_Theme_ImportchangesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 提议的更改`)
};

const ja_settings_theme_importchanges = /** @type {(inputs: Settings_Theme_ImportchangesInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 件の変更提案`)
};

/**
* | output |
* | --- |
* | "{count} proposed changes" |
*
* @param {Settings_Theme_ImportchangesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_importchanges = /** @type {((inputs: Settings_Theme_ImportchangesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ImportchangesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_importchanges(inputs)
	if (locale === "ja") return ja_settings_theme_importchanges(inputs)
	return en_settings_theme_importchanges(inputs)
});