/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_NoneInputs */

const en_publish_none = /** @type {(inputs: Publish_NoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No changes since the last publish.`)
};

const zh_cn2_publish_none = /** @type {(inputs: Publish_NoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`自上次发布以来没有任何变化。`)
};

const ja_publish_none = /** @type {(inputs: Publish_NoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`前回の公開以降、変更はありません。`)
};

/**
* | output |
* | --- |
* | "No changes since the last publish." |
*
* @param {Publish_NoneInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_none = /** @type {((inputs?: Publish_NoneInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_NoneInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_none(inputs)
	if (locale === "ja") return ja_publish_none(inputs)
	return en_publish_none(inputs)
});