/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_NopagesInputs */

const en_overview_nopages = /** @type {(inputs: Overview_NopagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No pages yet.`)
};

const zh_cn2_overview_nopages = /** @type {(inputs: Overview_NopagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`还没有页面。`)
};

const ja_overview_nopages = /** @type {(inputs: Overview_NopagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだページがありません。`)
};

/**
* | output |
* | --- |
* | "No pages yet." |
*
* @param {Overview_NopagesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_nopages = /** @type {((inputs?: Overview_NopagesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_NopagesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_nopages(inputs)
	if (locale === "ja") return ja_overview_nopages(inputs)
	return en_overview_nopages(inputs)
});