/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ domain: NonNullable<unknown> }} Settings_Domain_RemoveconfirmInputs */

const en_settings_domain_removeconfirm = /** @type {(inputs: Settings_Domain_RemoveconfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Remove ${i?.domain}? Your site will stop serving at that address.`)
};

const zh_cn2_settings_domain_removeconfirm = /** @type {(inputs: Settings_Domain_RemoveconfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`删除 ${i?.domain}？您的网站将停止在该地址上提供服务。`)
};

const ja_settings_domain_removeconfirm = /** @type {(inputs: Settings_Domain_RemoveconfirmInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.domain} を削除しますか?サイトはそのアドレスでのサービスを停止します。`)
};

/**
* | output |
* | --- |
* | "Remove {domain}? Your site will stop serving at that address." |
*
* @param {Settings_Domain_RemoveconfirmInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_removeconfirm = /** @type {((inputs: Settings_Domain_RemoveconfirmInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_RemoveconfirmInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_removeconfirm(inputs)
	if (locale === "ja") return ja_settings_domain_removeconfirm(inputs)
	return en_settings_domain_removeconfirm(inputs)
});