import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Pagesettings_SaveerrorInputs */

const en_editor_pagesettings_saveerror = /** @type {(inputs: Editor_Pagesettings_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not save settings`)
};

const zh_cn2_editor_pagesettings_saveerror = /** @type {(inputs: Editor_Pagesettings_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法保存设置`)
};

const ja_editor_pagesettings_saveerror = /** @type {(inputs: Editor_Pagesettings_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`設定を保存できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not save settings" |
*
* @param {Editor_Pagesettings_SaveerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_pagesettings_saveerror = /** @type {((inputs?: Editor_Pagesettings_SaveerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Pagesettings_SaveerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_pagesettings_saveerror(inputs)
	if (locale === "ja") return ja_editor_pagesettings_saveerror(inputs)
	return en_editor_pagesettings_saveerror(inputs)
});