import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Settings_Members_InvitecreatedInputs */

const en_settings_members_invitecreated = /** @type {(inputs: Settings_Members_InvitecreatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Invitation ready for ${i?.email}`)
};

const zh_cn2_settings_members_invitecreated = /** @type {(inputs: Settings_Members_InvitecreatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`已准备好 ${i?.email} 的邀请`)
};

const ja_settings_members_invitecreated = /** @type {(inputs: Settings_Members_InvitecreatedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.email} への招待状の準備ができました`)
};

/**
* | output |
* | --- |
* | "Invitation ready for {email}" |
*
* @param {Settings_Members_InvitecreatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_members_invitecreated = /** @type {((inputs: Settings_Members_InvitecreatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Members_InvitecreatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_members_invitecreated(inputs)
	if (locale === "ja") return ja_settings_members_invitecreated(inputs)
	return en_settings_members_invitecreated(inputs)
});