/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ provider: NonNullable<unknown> }} Settings_Git_Import_ButtonInputs */

const en_settings_git_import_button = /** @type {(inputs: Settings_Git_Import_ButtonInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Import from ${i?.provider}`)
};

const zh_cn2_settings_git_import_button = /** @type {(inputs: Settings_Git_Import_ButtonInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`从 ${i?.provider} 导入`)
};

const ja_settings_git_import_button = /** @type {(inputs: Settings_Git_Import_ButtonInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.provider} からインポート`)
};

/**
* | output |
* | --- |
* | "Import from {provider}" |
*
* @param {Settings_Git_Import_ButtonInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_import_button = /** @type {((inputs: Settings_Git_Import_ButtonInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Import_ButtonInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_import_button(inputs)
	if (locale === "ja") return ja_settings_git_import_button(inputs)
	return en_settings_git_import_button(inputs)
});