import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_PasteplaceholderInputs */

const en_settings_openapi_pasteplaceholder = /** @type {(inputs: Settings_Openapi_PasteplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Or paste an OpenAPI JSON/YAML document…`)
};

const zh_cn2_settings_openapi_pasteplaceholder = /** @type {(inputs: Settings_Openapi_PasteplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`或者粘贴 OpenAPI JSON/YAML 文档...`)
};

const ja_settings_openapi_pasteplaceholder = /** @type {(inputs: Settings_Openapi_PasteplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`または、OpenAPI JSON/YAML ドキュメントを貼り付けます…`)
};

/**
* | output |
* | --- |
* | "Or paste an OpenAPI JSON/YAML document…" |
*
* @param {Settings_Openapi_PasteplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_pasteplaceholder = /** @type {((inputs?: Settings_Openapi_PasteplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_PasteplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_pasteplaceholder(inputs)
	if (locale === "ja") return ja_settings_openapi_pasteplaceholder(inputs)
	return en_settings_openapi_pasteplaceholder(inputs)
});