import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Slash_EmptyInputs */

const en_editor_slash_empty = /** @type {(inputs: Editor_Slash_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No blocks found`)
};

const zh_cn2_editor_slash_empty = /** @type {(inputs: Editor_Slash_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`没有找到块`)
};

const ja_editor_slash_empty = /** @type {(inputs: Editor_Slash_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ブロックが見つかりませんでした`)
};

/**
* | output |
* | --- |
* | "No blocks found" |
*
* @param {Editor_Slash_EmptyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_slash_empty = /** @type {((inputs?: Editor_Slash_EmptyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Slash_EmptyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_slash_empty(inputs)
	if (locale === "ja") return ja_editor_slash_empty(inputs)
	return en_editor_slash_empty(inputs)
});