/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Danger_TitleInputs */

const en_settings_danger_title = /** @type {(inputs: Settings_Danger_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Danger zone`)
};

const zh_cn2_settings_danger_title = /** @type {(inputs: Settings_Danger_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`危险区域`)
};

const ja_settings_danger_title = /** @type {(inputs: Settings_Danger_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`危険地帯`)
};

/**
* | output |
* | --- |
* | "Danger zone" |
*
* @param {Settings_Danger_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_danger_title = /** @type {((inputs?: Settings_Danger_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Danger_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_danger_title(inputs)
	if (locale === "ja") return ja_settings_danger_title(inputs)
	return en_settings_danger_title(inputs)
});