import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ customerName: NonNullable<unknown> }} Support_Banner_ViewingasInputs */

const en_support_banner_viewingas = /** @type {(inputs: Support_Banner_ViewingasInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Viewing cms as ${i?.customerName}. The session expires within one hour.`)
};

const zh_cn2_support_banner_viewingas = /** @type {(inputs: Support_Banner_ViewingasInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`正在以 ${i?.customerName} 的身份查看 cms。会话将在一小时内过期。`)
};

const ja_support_banner_viewingas = /** @type {(inputs: Support_Banner_ViewingasInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (` ${i?.customerName}`)
};

/**
* | output |
* | --- |
* | "Viewing cms as {customerName}. The session expires within one hour." |
*
* @param {Support_Banner_ViewingasInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const support_banner_viewingas = /** @type {((inputs: Support_Banner_ViewingasInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Support_Banner_ViewingasInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_support_banner_viewingas(inputs)
	if (locale === "ja") return ja_support_banner_viewingas(inputs)
	return en_support_banner_viewingas(inputs)
});