import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_MessageplaceholderInputs */

const en_publish_messageplaceholder = /** @type {(inputs: Publish_MessageplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Describe this release (optional)`)
};

const zh_cn2_publish_messageplaceholder = /** @type {(inputs: Publish_MessageplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`描述此版本（可选）`)
};

const ja_publish_messageplaceholder = /** @type {(inputs: Publish_MessageplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このリリースについて説明します (オプション)`)
};

/**
* | output |
* | --- |
* | "Describe this release (optional)" |
*
* @param {Publish_MessageplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_messageplaceholder = /** @type {((inputs?: Publish_MessageplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_MessageplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_messageplaceholder(inputs)
	if (locale === "ja") return ja_publish_messageplaceholder(inputs)
	return en_publish_messageplaceholder(inputs)
});