/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_AgainInputs */

const en_settings_import_again = /** @type {(inputs: Settings_Import_AgainInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import another`)
};

const zh_cn2_settings_import_again = /** @type {(inputs: Settings_Import_AgainInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导入另一个`)
};

const ja_settings_import_again = /** @type {(inputs: Settings_Import_AgainInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`別のインポート`)
};

/**
* | output |
* | --- |
* | "Import another" |
*
* @param {Settings_Import_AgainInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_again = /** @type {((inputs?: Settings_Import_AgainInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_AgainInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_again(inputs)
	if (locale === "ja") return ja_settings_import_again(inputs)
	return en_settings_import_again(inputs)
});