/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Settings_Languages_Coverage_ExtraInputs */

const en_settings_languages_coverage_extra = /** @type {(inputs: Settings_Languages_Coverage_ExtraInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} language-only`)
};

const zh_cn2_settings_languages_coverage_extra = /** @type {(inputs: Settings_Languages_Coverage_ExtraInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 仅语言`)
};

const ja_settings_languages_coverage_extra = /** @type {(inputs: Settings_Languages_Coverage_ExtraInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 言語のみ`)
};

/**
* | output |
* | --- |
* | "{count} language-only" |
*
* @param {Settings_Languages_Coverage_ExtraInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_coverage_extra = /** @type {((inputs: Settings_Languages_Coverage_ExtraInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_Coverage_ExtraInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_coverage_extra(inputs)
	if (locale === "ja") return ja_settings_languages_coverage_extra(inputs)
	return en_settings_languages_coverage_extra(inputs)
});