/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Blog_UpdatedInputs */

const en_blog_updated = /** @type {(inputs: Blog_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Updated`)
};

const zh_cn2_blog_updated = /** @type {(inputs: Blog_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Updated`)
};

const ja_blog_updated = /** @type {(inputs: Blog_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`更新されました`)
};

/**
* | output |
* | --- |
* | "Updated" |
*
* @param {Blog_UpdatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_updated = /** @type {((inputs?: Blog_UpdatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_UpdatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_updated(inputs)
	if (locale === "ja") return ja_blog_updated(inputs)
	return en_blog_updated(inputs)
});