/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_ManageInputs */

const en_overview_manage = /** @type {(inputs: Overview_ManageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Manage this site`)
};

const zh_cn2_overview_manage = /** @type {(inputs: Overview_ManageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`管理这个网站`)
};

const ja_overview_manage = /** @type {(inputs: Overview_ManageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このサイトを管理する`)
};

/**
* | output |
* | --- |
* | "Manage this site" |
*
* @param {Overview_ManageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_manage = /** @type {((inputs?: Overview_ManageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_ManageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_manage(inputs)
	if (locale === "ja") return ja_overview_manage(inputs)
	return en_overview_manage(inputs)
});