import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Usage_DescriptionInputs */

const en_settings_usage_description = /** @type {(inputs: Settings_Usage_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`A provider-neutral view of measurable product usage and limits. Missing measurements stay unknown instead of being shown as zero.`)
};

const zh_cn2_settings_usage_description = /** @type {(inputs: Settings_Usage_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`此网站使用的内容不受 Cloud Beta 限制。限制很慷慨，并且在测试期间不会强制执行。`)
};

const ja_settings_usage_description = /** @type {(inputs: Settings_Usage_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`測定可能な製品の使用状況と制限について、プロバイダーに依存しないビュー。欠落している測定値はゼロとして表示されるのではなく、不明のままです。`)
};

/**
* | output |
* | --- |
* | "A provider-neutral view of measurable product usage and limits. Missing measurements stay unknown instead of being shown as zero." |
*
* @param {Settings_Usage_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage_description = /** @type {((inputs?: Settings_Usage_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Usage_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage_description(inputs)
	if (locale === "ja") return ja_settings_usage_description(inputs)
	return en_settings_usage_description(inputs)
});