import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_ReviewdiffInputs */

const en_publish_reviewdiff = /** @type {(inputs: Publish_ReviewdiffInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Review diff`)
};

const zh_cn2_publish_reviewdiff = /** @type {(inputs: Publish_ReviewdiffInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`查看差异`)
};

const ja_publish_reviewdiff = /** @type {(inputs: Publish_ReviewdiffInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`差分を確認する`)
};

/**
* | output |
* | --- |
* | "Review diff" |
*
* @param {Publish_ReviewdiffInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_reviewdiff = /** @type {((inputs?: Publish_ReviewdiffInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_ReviewdiffInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_reviewdiff(inputs)
	if (locale === "ja") return ja_publish_reviewdiff(inputs)
	return en_publish_reviewdiff(inputs)
});