import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_HiderailInputs */

const en_editor_hiderail = /** @type {(inputs: Editor_HiderailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Hide AI & comments`)
};

const zh_cn2_editor_hiderail = /** @type {(inputs: Editor_HiderailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`隐藏人工智能和评论`)
};

const ja_editor_hiderail = /** @type {(inputs: Editor_HiderailInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`AI とコメントを非表示にする`)
};

/**
* | output |
* | --- |
* | "Hide AI & comments" |
*
* @param {Editor_HiderailInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_hiderail = /** @type {((inputs?: Editor_HiderailInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_HiderailInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_hiderail(inputs)
	if (locale === "ja") return ja_editor_hiderail(inputs)
	return en_editor_hiderail(inputs)
});