import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_NocommentsInputs */

const en_editor_nocomments = /** @type {(inputs: Editor_NocommentsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No comments yet.`)
};

const zh_cn2_editor_nocomments = /** @type {(inputs: Editor_NocommentsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`还没有评论。`)
};

const ja_editor_nocomments = /** @type {(inputs: Editor_NocommentsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コメントはまだありません。`)
};

/**
* | output |
* | --- |
* | "No comments yet." |
*
* @param {Editor_NocommentsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_nocomments = /** @type {((inputs?: Editor_NocommentsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_NocommentsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_nocomments(inputs)
	if (locale === "ja") return ja_editor_nocomments(inputs)
	return en_editor_nocomments(inputs)
});