/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Passwordless_SubtitleInputs */

const en_auth_passwordless_subtitle = /** @type {(inputs: Auth_Passwordless_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms is passwordless`)
};

const zh_cn2_auth_passwordless_subtitle = /** @type {(inputs: Auth_Passwordless_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms 是无密码的`)
};

const ja_auth_passwordless_subtitle = /** @type {(inputs: Auth_Passwordless_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cmsはパスワードレスです`)
};

/**
* | output |
* | --- |
* | "cms is passwordless" |
*
* @param {Auth_Passwordless_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_passwordless_subtitle = /** @type {((inputs?: Auth_Passwordless_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Passwordless_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_passwordless_subtitle(inputs)
	if (locale === "ja") return ja_auth_passwordless_subtitle(inputs)
	return en_auth_passwordless_subtitle(inputs)
});