import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Usage_NotpublishedInputs */

const en_settings_usage_notpublished = /** @type {(inputs: Settings_Usage_NotpublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Not published yet`)
};

const zh_cn2_settings_usage_notpublished = /** @type {(inputs: Settings_Usage_NotpublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`尚未发布`)
};

const ja_settings_usage_notpublished = /** @type {(inputs: Settings_Usage_NotpublishedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだ公開されていません`)
};

/**
* | output |
* | --- |
* | "Not published yet" |
*
* @param {Settings_Usage_NotpublishedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_usage_notpublished = /** @type {((inputs?: Settings_Usage_NotpublishedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Usage_NotpublishedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_usage_notpublished(inputs)
	if (locale === "ja") return ja_settings_usage_notpublished(inputs)
	return en_settings_usage_notpublished(inputs)
});