/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Auth_Invite_WrongaccountInputs */

const en_auth_invite_wrongaccount = /** @type {(inputs: Auth_Invite_WrongaccountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`This invitation was sent to ${i?.email}. Log in with that address to accept it.`)
};

const zh_cn2_auth_invite_wrongaccount = /** @type {(inputs: Auth_Invite_WrongaccountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`此邀请已发送至 ${i?.email}。使用该地址登录以接受它。`)
};

const ja_auth_invite_wrongaccount = /** @type {(inputs: Auth_Invite_WrongaccountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`この招待状は ${i?.email} に送信されました。承認するには、そのアドレスでログインしてください。`)
};

/**
* | output |
* | --- |
* | "This invitation was sent to {email}. Log in with that address to accept it." |
*
* @param {Auth_Invite_WrongaccountInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_wrongaccount = /** @type {((inputs: Auth_Invite_WrongaccountInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_WrongaccountInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_wrongaccount(inputs)
	if (locale === "ja") return ja_auth_invite_wrongaccount(inputs)
	return en_auth_invite_wrongaccount(inputs)
});