/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Settings_Integrations_ConnectedtoastInputs */

const en_settings_integrations_connectedtoast = /** @type {(inputs: Settings_Integrations_ConnectedtoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.name} connected`)
};

const zh_cn2_settings_integrations_connectedtoast = /** @type {(inputs: Settings_Integrations_ConnectedtoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.name}已连接`)
};

const ja_settings_integrations_connectedtoast = /** @type {(inputs: Settings_Integrations_ConnectedtoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.name} が接続されました`)
};

/**
* | output |
* | --- |
* | "{name} connected" |
*
* @param {Settings_Integrations_ConnectedtoastInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_connectedtoast = /** @type {((inputs: Settings_Integrations_ConnectedtoastInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_ConnectedtoastInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_connectedtoast(inputs)
	if (locale === "ja") return ja_settings_integrations_connectedtoast(inputs)
	return en_settings_integrations_connectedtoast(inputs)
});