/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown> }} Deploy_Rollback_ConfirmdescInputs */

const en_deploy_rollback_confirmdesc = /** @type {(inputs: Deploy_Rollback_ConfirmdescInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Roll back to v${i?.version}? Your live site will revert to that version.`)
};

const zh_cn2_deploy_rollback_confirmdesc = /** @type {(inputs: Deploy_Rollback_ConfirmdescInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`回滚到 v${i?.version}？您的实时网站将恢复到该版本。`)
};

const ja_deploy_rollback_confirmdesc = /** @type {(inputs: Deploy_Rollback_ConfirmdescInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} にロールバックしますか?ライブサイトはそのバージョンに戻ります。`)
};

/**
* | output |
* | --- |
* | "Roll back to v{version}? Your live site will revert to that version." |
*
* @param {Deploy_Rollback_ConfirmdescInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_rollback_confirmdesc = /** @type {((inputs: Deploy_Rollback_ConfirmdescInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_Rollback_ConfirmdescInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_rollback_confirmdesc(inputs)
	if (locale === "ja") return ja_deploy_rollback_confirmdesc(inputs)
	return en_deploy_rollback_confirmdesc(inputs)
});