import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_LoaderrorInputs */

const en_settings_integrations_loaderror = /** @type {(inputs: Settings_Integrations_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Integrations could not be loaded`)
};

const zh_cn2_settings_integrations_loaderror = /** @type {(inputs: Settings_Integrations_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法装入整合`)
};

const ja_settings_integrations_loaderror = /** @type {(inputs: Settings_Integrations_LoaderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`統合をロードできませんでした`)
};

/**
* | output |
* | --- |
* | "Integrations could not be loaded" |
*
* @param {Settings_Integrations_LoaderrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_loaderror = /** @type {((inputs?: Settings_Integrations_LoaderrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_LoaderrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_loaderror(inputs)
	if (locale === "ja") return ja_settings_integrations_loaderror(inputs)
	return en_settings_integrations_loaderror(inputs)
});