/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Settings_Import_Warnings_ShowInputs */

const en_settings_import_warnings_show = /** @type {(inputs: Settings_Import_Warnings_ShowInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Show warnings (${i?.count})`)
};

const zh_cn2_settings_import_warnings_show = /** @type {(inputs: Settings_Import_Warnings_ShowInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`显示警告 (${i?.count})`)
};

const ja_settings_import_warnings_show = /** @type {(inputs: Settings_Import_Warnings_ShowInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`警告を表示 (${i?.count})`)
};

/**
* | output |
* | --- |
* | "Show warnings ({count})" |
*
* @param {Settings_Import_Warnings_ShowInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_warnings_show = /** @type {((inputs: Settings_Import_Warnings_ShowInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Warnings_ShowInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_warnings_show(inputs)
	if (locale === "ja") return ja_settings_import_warnings_show(inputs)
	return en_settings_import_warnings_show(inputs)
});