import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Invite_AcceptedtoastInputs */

const en_auth_invite_acceptedtoast = /** @type {(inputs: Auth_Invite_AcceptedtoastInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Invitation accepted`)
};

const zh_cn2_auth_invite_acceptedtoast = /** @type {(inputs: Auth_Invite_AcceptedtoastInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已接受邀请`)
};

const ja_auth_invite_acceptedtoast = /** @type {(inputs: Auth_Invite_AcceptedtoastInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`招待を受諾しました`)
};

/**
* | output |
* | --- |
* | "Invitation accepted" |
*
* @param {Auth_Invite_AcceptedtoastInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_acceptedtoast = /** @type {((inputs?: Auth_Invite_AcceptedtoastInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_AcceptedtoastInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_acceptedtoast(inputs)
	if (locale === "ja") return ja_auth_invite_acceptedtoast(inputs)
	return en_auth_invite_acceptedtoast(inputs)
});