import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_ConfigurehintInputs */

const en_settings_import_configurehint = /** @type {(inputs: Settings_Import_ConfigurehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose the source settings, then import when ready.`)
};

const zh_cn2_settings_import_configurehint = /** @type {(inputs: Settings_Import_ConfigurehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择源设置，然后在准备好后导入。`)
};

const ja_settings_import_configurehint = /** @type {(inputs: Settings_Import_ConfigurehintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ソース設定を選択し、準備ができたらインポートします。`)
};

/**
* | output |
* | --- |
* | "Choose the source settings, then import when ready." |
*
* @param {Settings_Import_ConfigurehintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_configurehint = /** @type {((inputs?: Settings_Import_ConfigurehintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_ConfigurehintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_configurehint(inputs)
	if (locale === "ja") return ja_settings_import_configurehint(inputs)
	return en_settings_import_configurehint(inputs)
});