import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_InvalidcodeInputs */

const en_auth_verify_invalidcode = /** @type {(inputs: Auth_Verify_InvalidcodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Enter the valid 6-digit code from your email.`)
};

const zh_cn2_auth_verify_invalidcode = /** @type {(inputs: Auth_Verify_InvalidcodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`输入电子邮件中的有效 6 位数代码。`)
};

const ja_auth_verify_invalidcode = /** @type {(inputs: Auth_Verify_InvalidcodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`メールに記載されている有効な 6 桁のコードを入力してください。`)
};

/**
* | output |
* | --- |
* | "Enter the valid 6-digit code from your email." |
*
* @param {Auth_Verify_InvalidcodeInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_invalidcode = /** @type {((inputs?: Auth_Verify_InvalidcodeInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_InvalidcodeInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_invalidcode(inputs)
	if (locale === "ja") return ja_auth_verify_invalidcode(inputs)
	return en_auth_verify_invalidcode(inputs)
});