import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Dashboard_Empty_BodyInputs */

const en_dashboard_empty_body = /** @type {(inputs: Dashboard_Empty_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Create your first documentation site to get started.`)
};

const zh_cn2_dashboard_empty_body = /** @type {(inputs: Dashboard_Empty_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`创建您的第一个文档站点以开始使用。`)
};

const ja_dashboard_empty_body = /** @type {(inputs: Dashboard_Empty_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まずは最初のドキュメント サイトを作成してください。`)
};

/**
* | output |
* | --- |
* | "Create your first documentation site to get started." |
*
* @param {Dashboard_Empty_BodyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const dashboard_empty_body = /** @type {((inputs?: Dashboard_Empty_BodyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Dashboard_Empty_BodyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_dashboard_empty_body(inputs)
	if (locale === "ja") return ja_dashboard_empty_body(inputs)
	return en_dashboard_empty_body(inputs)
});