/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ org: NonNullable<unknown> }} Auth_Invite_JoinpromptInputs */

const en_auth_invite_joinprompt = /** @type {(inputs: Auth_Invite_JoinpromptInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Join ${i?.org} to collaborate on its documentation.`)
};

const zh_cn2_auth_invite_joinprompt = /** @type {(inputs: Auth_Invite_JoinpromptInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`加入 ${i?.org} 来协作编写其文档。`)
};

const ja_auth_invite_joinprompt = /** @type {(inputs: Auth_Invite_JoinpromptInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.org} に参加して、ドキュメントの共同作業を行ってください。`)
};

/**
* | output |
* | --- |
* | "Join {org} to collaborate on its documentation." |
*
* @param {Auth_Invite_JoinpromptInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_joinprompt = /** @type {((inputs: Auth_Invite_JoinpromptInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_JoinpromptInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_joinprompt(inputs)
	if (locale === "ja") return ja_auth_invite_joinprompt(inputs)
	return en_auth_invite_joinprompt(inputs)
});