/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ shown: NonNullable<unknown>, total: NonNullable<unknown> }} Admin_Users_ShowingInputs */

const en_admin_users_showing = /** @type {(inputs: Admin_Users_ShowingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Showing ${i?.shown} of ${i?.total} customers`)
};

const zh_cn2_admin_users_showing = /** @type {(inputs: Admin_Users_ShowingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Showing ${i?.shown} of ${i?.total} customers`)
};

const ja_admin_users_showing = /** @type {(inputs: Admin_Users_ShowingInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.total} 件の顧客のうち ${i?.shown} を表示しています`)
};

/**
* | output |
* | --- |
* | "Showing {shown} of {total} customers" |
*
* @param {Admin_Users_ShowingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_users_showing = /** @type {((inputs: Admin_Users_ShowingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Users_ShowingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_users_showing(inputs)
	if (locale === "ja") return ja_admin_users_showing(inputs)
	return en_admin_users_showing(inputs)
});