/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_Live_TitleInputs */

const en_overview_live_title = /** @type {(inputs: Overview_Live_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Live domain`)
};

const zh_cn2_overview_live_title = /** @type {(inputs: Overview_Live_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`实时域名`)
};

const ja_overview_live_title = /** @type {(inputs: Overview_Live_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ライブドメイン`)
};

/**
* | output |
* | --- |
* | "Live domain" |
*
* @param {Overview_Live_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_live_title = /** @type {((inputs?: Overview_Live_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_Live_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_live_title(inputs)
	if (locale === "ja") return ja_overview_live_title(inputs)
	return en_overview_live_title(inputs)
});