import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Placeholder_BodyInputs */

const en_editor_placeholder_body = /** @type {(inputs: Editor_Placeholder_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Write something, or press '/' for commands`)
};

const zh_cn2_editor_placeholder_body = /** @type {(inputs: Editor_Placeholder_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`输入内容，或按 '/' 打开命令`)
};

const ja_editor_placeholder_body = /** @type {(inputs: Editor_Placeholder_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (``)
};

/**
* | output |
* | --- |
* | "Write something, or press '/' for commands" |
*
* @param {Editor_Placeholder_BodyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_placeholder_body = /** @type {((inputs?: Editor_Placeholder_BodyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Placeholder_BodyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_placeholder_body(inputs)
	if (locale === "ja") return ja_editor_placeholder_body(inputs)
	return en_editor_placeholder_body(inputs)
});