import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Access_TitleInputs */

const en_settings_git_access_title = /** @type {(inputs: Settings_Git_Access_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Git access`)
};

const zh_cn2_settings_git_access_title = /** @type {(inputs: Settings_Git_Access_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Git 访问`)
};

const ja_settings_git_access_title = /** @type {(inputs: Settings_Git_Access_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Git アクセス`)
};

/**
* | output |
* | --- |
* | "Git access" |
*
* @param {Settings_Git_Access_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_access_title = /** @type {((inputs?: Settings_Git_Access_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Access_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_access_title(inputs)
	if (locale === "ja") return ja_settings_git_access_title(inputs)
	return en_settings_git_access_title(inputs)
});