import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Search_ChooseiconInputs */

const en_settings_search_chooseicon = /** @type {(inputs: Settings_Search_ChooseiconInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose icon`)
};

const zh_cn2_settings_search_chooseicon = /** @type {(inputs: Settings_Search_ChooseiconInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择图标`)
};

const ja_settings_search_chooseicon = /** @type {(inputs: Settings_Search_ChooseiconInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`アイコンを選択`)
};

/**
* | output |
* | --- |
* | "Choose icon" |
*
* @param {Settings_Search_ChooseiconInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_search_chooseicon = /** @type {((inputs?: Settings_Search_ChooseiconInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Search_ChooseiconInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_search_chooseicon(inputs)
	if (locale === "ja") return ja_settings_search_chooseicon(inputs)
	return en_settings_search_chooseicon(inputs)
});