import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_Dns_PropagationInputs */

const en_settings_domain_dns_propagation = /** @type {(inputs: Settings_Domain_Dns_PropagationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`DNS can take a few minutes to propagate.`)
};

const zh_cn2_settings_domain_dns_propagation = /** @type {(inputs: Settings_Domain_Dns_PropagationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`DNS 可能需要几分钟的时间来传播。`)
};

const ja_settings_domain_dns_propagation = /** @type {(inputs: Settings_Domain_Dns_PropagationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`DNS が伝播するまでに数分かかる場合があります。`)
};

/**
* | output |
* | --- |
* | "DNS can take a few minutes to propagate." |
*
* @param {Settings_Domain_Dns_PropagationInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_dns_propagation = /** @type {((inputs?: Settings_Domain_Dns_PropagationInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_Dns_PropagationInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_dns_propagation(inputs)
	if (locale === "ja") return ja_settings_domain_dns_propagation(inputs)
	return en_settings_domain_dns_propagation(inputs)
});