/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_SenttoInputs */

const en_auth_verify_sentto = /** @type {(inputs: Auth_Verify_SenttoInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Enter the 6-digit code we sent to`)
};

const zh_cn2_auth_verify_sentto = /** @type {(inputs: Auth_Verify_SenttoInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`输入我们发送至的 6 位数代码`)
};

const ja_auth_verify_sentto = /** @type {(inputs: Auth_Verify_SenttoInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`送信した6桁のコードを入力してください`)
};

/**
* | output |
* | --- |
* | "Enter the 6-digit code we sent to" |
*
* @param {Auth_Verify_SenttoInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_sentto = /** @type {((inputs?: Auth_Verify_SenttoInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_SenttoInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_sentto(inputs)
	if (locale === "ja") return ja_auth_verify_sentto(inputs)
	return en_auth_verify_sentto(inputs)
});