import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Footer_Copyright_PlaceholderInputs */

const en_settings_footer_copyright_placeholder = /** @type {(inputs: Settings_Footer_Copyright_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`© 2026 Acme. All rights reserved.`)
};

const zh_cn2_settings_footer_copyright_placeholder = /** @type {(inputs: Settings_Footer_Copyright_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`© 2026 Acme。版权所有。`)
};

const ja_settings_footer_copyright_placeholder = /** @type {(inputs: Settings_Footer_Copyright_PlaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`© 2026 アクメ.無断転載を禁じます。`)
};

/**
* | output |
* | --- |
* | "© 2026 Acme. All rights reserved." |
*
* @param {Settings_Footer_Copyright_PlaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_footer_copyright_placeholder = /** @type {((inputs?: Settings_Footer_Copyright_PlaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Footer_Copyright_PlaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_footer_copyright_placeholder(inputs)
	if (locale === "ja") return ja_settings_footer_copyright_placeholder(inputs)
	return en_settings_footer_copyright_placeholder(inputs)
});