/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_ErrorInputs */

const en_settings_import_error = /** @type {(inputs: Settings_Import_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import failed`)
};

const zh_cn2_settings_import_error = /** @type {(inputs: Settings_Import_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导入失败`)
};

const ja_settings_import_error = /** @type {(inputs: Settings_Import_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`インポートに失敗しました`)
};

/**
* | output |
* | --- |
* | "Import failed" |
*
* @param {Settings_Import_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_error = /** @type {((inputs?: Settings_Import_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_error(inputs)
	if (locale === "ja") return ja_settings_import_error(inputs)
	return en_settings_import_error(inputs)
});