/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_BacktosigninInputs */

const en_auth_backtosignin = /** @type {(inputs: Auth_BacktosigninInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Back to log in`)
};

const zh_cn2_auth_backtosignin = /** @type {(inputs: Auth_BacktosigninInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`返回登录`)
};

const ja_auth_backtosignin = /** @type {(inputs: Auth_BacktosigninInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ログインに戻る`)
};

/**
* | output |
* | --- |
* | "Back to log in" |
*
* @param {Auth_BacktosigninInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_backtosignin = /** @type {((inputs?: Auth_BacktosigninInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_BacktosigninInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_backtosignin(inputs)
	if (locale === "ja") return ja_auth_backtosignin(inputs)
	return en_auth_backtosignin(inputs)
});