/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Admin_Meta_TitleInputs */

const en_admin_meta_title = /** @type {(inputs: Admin_Meta_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms Admin`)
};

const zh_cn2_admin_meta_title = /** @type {(inputs: Admin_Meta_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms Admin`)
};

const ja_admin_meta_title = /** @type {(inputs: Admin_Meta_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`cms管理者`)
};

/**
* | output |
* | --- |
* | "cms Admin" |
*
* @param {Admin_Meta_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_meta_title = /** @type {((inputs?: Admin_Meta_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Meta_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_meta_title(inputs)
	if (locale === "ja") return ja_admin_meta_title(inputs)
	return en_admin_meta_title(inputs)
});