import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_RollbackInputs */

const en_deploy_rollback = /** @type {(inputs: Deploy_RollbackInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Roll back`)
};

const zh_cn2_deploy_rollback = /** @type {(inputs: Deploy_RollbackInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`回滚`)
};

const ja_deploy_rollback = /** @type {(inputs: Deploy_RollbackInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ロールバック`)
};

/**
* | output |
* | --- |
* | "Roll back" |
*
* @param {Deploy_RollbackInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_rollback = /** @type {((inputs?: Deploy_RollbackInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_RollbackInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_rollback(inputs)
	if (locale === "ja") return ja_deploy_rollback(inputs)
	return en_deploy_rollback(inputs)
});