import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_ActionerrorInputs */

const en_settings_integrations_actionerror = /** @type {(inputs: Settings_Integrations_ActionerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The integration action could not be completed. Refresh and try again.`)
};

const zh_cn2_settings_integrations_actionerror = /** @type {(inputs: Settings_Integrations_ActionerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法完成集成操作。请刷新后重试。`)
};

const ja_settings_integrations_actionerror = /** @type {(inputs: Settings_Integrations_ActionerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`統合アクションを完了できませんでした。更新して再試行してください。`)
};

/**
* | output |
* | --- |
* | "The integration action could not be completed. Refresh and try again." |
*
* @param {Settings_Integrations_ActionerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_actionerror = /** @type {((inputs?: Settings_Integrations_ActionerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_ActionerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_actionerror(inputs)
	if (locale === "ja") return ja_settings_integrations_actionerror(inputs)
	return en_settings_integrations_actionerror(inputs)
});