/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Google_SignupInputs */

const en_auth_google_signup = /** @type {(inputs: Auth_Google_SignupInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Create account with Google`)
};

const zh_cn2_auth_google_signup = /** @type {(inputs: Auth_Google_SignupInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`使用 Google 创建帐户`)
};

const ja_auth_google_signup = /** @type {(inputs: Auth_Google_SignupInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Googleでアカウントを作成する`)
};

/**
* | output |
* | --- |
* | "Create account with Google" |
*
* @param {Auth_Google_SignupInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_google_signup = /** @type {((inputs?: Auth_Google_SignupInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Google_SignupInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_google_signup(inputs)
	if (locale === "ja") return ja_auth_google_signup(inputs)
	return en_auth_google_signup(inputs)
});