/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ date: NonNullable<unknown> }} Settings_Domain_LastcheckedInputs */

const en_settings_domain_lastchecked = /** @type {(inputs: Settings_Domain_LastcheckedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Last checked ${i?.date}`)
};

const zh_cn2_settings_domain_lastchecked = /** @type {(inputs: Settings_Domain_LastcheckedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最后检查 ${i?.date}`)
};

const ja_settings_domain_lastchecked = /** @type {(inputs: Settings_Domain_LastcheckedInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`最終チェック日 ${i?.date}`)
};

/**
* | output |
* | --- |
* | "Last checked {date}" |
*
* @param {Settings_Domain_LastcheckedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_lastchecked = /** @type {((inputs: Settings_Domain_LastcheckedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_LastcheckedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_lastchecked(inputs)
	if (locale === "ja") return ja_settings_domain_lastchecked(inputs)
	return en_settings_domain_lastchecked(inputs)
});