/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_RemovedInputs */

const en_publish_removed = /** @type {(inputs: Publish_RemovedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Removed`)
};

const zh_cn2_publish_removed = /** @type {(inputs: Publish_RemovedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已删除`)
};

const ja_publish_removed = /** @type {(inputs: Publish_RemovedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`削除されました`)
};

/**
* | output |
* | --- |
* | "Removed" |
*
* @param {Publish_RemovedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_removed = /** @type {((inputs?: Publish_RemovedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_RemovedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_removed(inputs)
	if (locale === "ja") return ja_publish_removed(inputs)
	return en_publish_removed(inputs)
});