/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_Rollback_NoneInputs */

const en_deploy_rollback_none = /** @type {(inputs: Deploy_Rollback_NoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No previous deployment to roll back to.`)
};

const zh_cn2_deploy_rollback_none = /** @type {(inputs: Deploy_Rollback_NoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`没有可以回滚到的先前部署。`)
};

const ja_deploy_rollback_none = /** @type {(inputs: Deploy_Rollback_NoneInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ロールバックできる以前のデプロイメントがありません。`)
};

/**
* | output |
* | --- |
* | "No previous deployment to roll back to." |
*
* @param {Deploy_Rollback_NoneInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_rollback_none = /** @type {((inputs?: Deploy_Rollback_NoneInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_Rollback_NoneInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_rollback_none(inputs)
	if (locale === "ja") return ja_deploy_rollback_none(inputs)
	return en_deploy_rollback_none(inputs)
});