/**
* | output |
* | --- |
* | "No API keys yet." |
*
* @param {Settings_Apikeys_EmptyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_apikeys_empty = /** @type {((inputs?: Settings_Apikeys_EmptyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Apikeys_EmptyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_apikeys_empty(inputs)
	if (locale === "ja") return ja_settings_apikeys_empty(inputs)
	return en_settings_apikeys_empty(inputs)
});