import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_RecentpagesInputs */

const en_overview_recentpages = /** @type {(inputs: Overview_RecentpagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Recent pages`)
};

const zh_cn2_overview_recentpages = /** @type {(inputs: Overview_RecentpagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`最近的页面`)
};

const ja_overview_recentpages = /** @type {(inputs: Overview_RecentpagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`最近のページ`)
};

/**
* | output |
* | --- |
* | "Recent pages" |
*
* @param {Overview_RecentpagesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_recentpages = /** @type {((inputs?: Overview_RecentpagesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_RecentpagesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_recentpages(inputs)
	if (locale === "ja") return ja_overview_recentpages(inputs)
	return en_overview_recentpages(inputs)
});