import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Langsettings_MetatitleInputs */

const en_editor_langsettings_metatitle = /** @type {(inputs: Editor_Langsettings_MetatitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Site title`)
};

const zh_cn2_editor_langsettings_metatitle = /** @type {(inputs: Editor_Langsettings_MetatitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`网站标题`)
};

const ja_editor_langsettings_metatitle = /** @type {(inputs: Editor_Langsettings_MetatitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`サイトタイトル`)
};

/**
* | output |
* | --- |
* | "Site title" |
*
* @param {Editor_Langsettings_MetatitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_langsettings_metatitle = /** @type {((inputs?: Editor_Langsettings_MetatitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Langsettings_MetatitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_langsettings_metatitle(inputs)
	if (locale === "ja") return ja_editor_langsettings_metatitle(inputs)
	return en_editor_langsettings_metatitle(inputs)
});