/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_SubtitleInputs */

const en_settings_subtitle = /** @type {(inputs: Settings_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Your account across every workspace: profile, email, and how the dashboard looks.`)
};

const zh_cn2_settings_subtitle = /** @type {(inputs: Settings_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您在所有工作区中的账户：个人资料、邮箱以及仪表板的外观。`)
};

const ja_settings_subtitle = /** @type {(inputs: Settings_SubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`すべてのワークスペースにわたるアカウント: プロフィール、電子メール、ダッシュボードの外観。`)
};

/**
* | output |
* | --- |
* | "Your account across every workspace: profile, email, and how the dashboard looks." |
*
* @param {Settings_SubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_subtitle = /** @type {((inputs?: Settings_SubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_SubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_subtitle(inputs)
	if (locale === "ja") return ja_settings_subtitle(inputs)
	return en_settings_subtitle(inputs)
});