/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Publish_MoreInputs */

const en_publish_more = /** @type {(inputs: Publish_MoreInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`+${i?.count} more`)
};

const zh_cn2_publish_more = /** @type {(inputs: Publish_MoreInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`+${i?.count} 更多`)
};

const ja_publish_more = /** @type {(inputs: Publish_MoreInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`+${i?.count} 詳細`)
};

/**
* | output |
* | --- |
* | "+{count} more" |
*
* @param {Publish_MoreInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_more = /** @type {((inputs: Publish_MoreInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_MoreInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_more(inputs)
	if (locale === "ja") return ja_publish_more(inputs)
	return en_publish_more(inputs)
});