/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Languages_HintInputs */

const en_settings_languages_hint = /** @type {(inputs: Settings_Languages_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The default language is always enabled — it is the fallback for every visitor.`)
};

const zh_cn2_settings_languages_hint = /** @type {(inputs: Settings_Languages_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`默认语言始终处于启用状态 - 这是每个访问者的后备语言。`)
};

const ja_settings_languages_hint = /** @type {(inputs: Settings_Languages_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`デフォルト言語は常に有効になっており、すべての訪問者のフォールバックとなります。`)
};

/**
* | output |
* | --- |
* | "The default language is always enabled — it is the fallback for every visitor." |
*
* @param {Settings_Languages_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_hint = /** @type {((inputs?: Settings_Languages_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_hint(inputs)
	if (locale === "ja") return ja_settings_languages_hint(inputs)
	return en_settings_languages_hint(inputs)
});