import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Nav_SitesInputs */

const en_nav_sites = /** @type {(inputs: Nav_SitesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Sites`)
};

const zh_cn2_nav_sites = /** @type {(inputs: Nav_SitesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`站点`)
};

const ja_nav_sites = /** @type {(inputs: Nav_SitesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`サイト`)
};

/**
* | output |
* | --- |
* | "Sites" |
*
* @param {Nav_SitesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const nav_sites = /** @type {((inputs?: Nav_SitesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Nav_SitesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_nav_sites(inputs)
	if (locale === "ja") return ja_nav_sites(inputs)
	return en_nav_sites(inputs)
});