/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown> }} Overview_Publishfailed_TitleInputs */

const en_overview_publishfailed_title = /** @type {(inputs: Overview_Publishfailed_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Publish v${i?.version} failed`)
};

const zh_cn2_overview_publishfailed_title = /** @type {(inputs: Overview_Publishfailed_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`发布 v${i?.version} 失败`)
};

const ja_overview_publishfailed_title = /** @type {(inputs: Overview_Publishfailed_TitleInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} の公開に失敗しました`)
};

/**
* | output |
* | --- |
* | "Publish v{version} failed" |
*
* @param {Overview_Publishfailed_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_publishfailed_title = /** @type {((inputs: Overview_Publishfailed_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_Publishfailed_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_publishfailed_title(inputs)
	if (locale === "ja") return ja_overview_publishfailed_title(inputs)
	return en_overview_publishfailed_title(inputs)
});