/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Import_DescriptionInputs */

const en_settings_git_import_description = /** @type {(inputs: Settings_Git_Import_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Connect a public Git repository and import its Markdown into your pages.`)
};

const zh_cn2_settings_git_import_description = /** @type {(inputs: Settings_Git_Import_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`连接公共 Git 存储库并将其 Markdown 导入到您的页面中。`)
};

const ja_settings_git_import_description = /** @type {(inputs: Settings_Git_Import_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`パブリック Git リポジトリに接続し、そのマークダウンをページにインポートします。`)
};

/**
* | output |
* | --- |
* | "Connect a public Git repository and import its Markdown into your pages." |
*
* @param {Settings_Git_Import_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_import_description = /** @type {((inputs?: Settings_Git_Import_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Import_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_import_description(inputs)
	if (locale === "ja") return ja_settings_git_import_description(inputs)
	return en_settings_git_import_description(inputs)
});