/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_DescriptionInputs */

const en_settings_import_description = /** @type {(inputs: Settings_Import_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Bring your existing docs into cms from another platform. Imports are one-way and safe to re-run.`)
};

const zh_cn2_settings_import_description = /** @type {(inputs: Settings_Import_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`将您现有的文档从另一个平台引入 cms 。导入是单向的并且可以安全地重新运行。`)
};

const ja_settings_import_description = /** @type {(inputs: Settings_Import_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`既存のドキュメントを別のプラットフォームから cms に取り込みます。インポートは一方向であり、安全に再実行できます。`)
};

/**
* | output |
* | --- |
* | "Bring your existing docs into cms from another platform. Imports are one-way and safe to re-run." |
*
* @param {Settings_Import_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_description = /** @type {((inputs?: Settings_Import_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_description(inputs)
	if (locale === "ja") return ja_settings_import_description(inputs)
	return en_settings_import_description(inputs)
});