/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_NolinediffInputs */

const en_publish_nolinediff = /** @type {(inputs: Publish_NolinediffInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No content diff for this page.`)
};

const zh_cn2_publish_nolinediff = /** @type {(inputs: Publish_NolinediffInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`此页面没有内容差异。`)
};

const ja_publish_nolinediff = /** @type {(inputs: Publish_NolinediffInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このページにはコンテンツの差分はありません。`)
};

/**
* | output |
* | --- |
* | "No content diff for this page." |
*
* @param {Publish_NolinediffInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_nolinediff = /** @type {((inputs?: Publish_NolinediffInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_NolinediffInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_nolinediff(inputs)
	if (locale === "ja") return ja_publish_nolinediff(inputs)
	return en_publish_nolinediff(inputs)
});