import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Git_OpenInputs */

const en_settings_import_git_open = /** @type {(inputs: Settings_Import_Git_OpenInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Configure in Git settings`)
};

const zh_cn2_settings_import_git_open = /** @type {(inputs: Settings_Import_Git_OpenInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`在 Git 设置中配置`)
};

const ja_settings_import_git_open = /** @type {(inputs: Settings_Import_Git_OpenInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Git設定で構成する`)
};

/**
* | output |
* | --- |
* | "Configure in Git settings" |
*
* @param {Settings_Import_Git_OpenInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_git_open = /** @type {((inputs?: Settings_Import_Git_OpenInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Git_OpenInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_git_open(inputs)
	if (locale === "ja") return ja_settings_import_git_open(inputs)
	return en_settings_import_git_open(inputs)
});