import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_FileInputs */

const en_settings_import_ghost_file = /** @type {(inputs: Settings_Import_Ghost_FileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Export file (.json)`)
};

const zh_cn2_settings_import_ghost_file = /** @type {(inputs: Settings_Import_Ghost_FileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导出文件（.json）`)
};

const ja_settings_import_ghost_file = /** @type {(inputs: Settings_Import_Ghost_FileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`エクスポートファイル(.json)`)
};

/**
* | output |
* | --- |
* | "Export file (.json)" |
*
* @param {Settings_Import_Ghost_FileInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_file = /** @type {((inputs?: Settings_Import_Ghost_FileInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_FileInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_file(inputs)
	if (locale === "ja") return ja_settings_import_ghost_file(inputs)
	return en_settings_import_ghost_file(inputs)
});