import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_BacktosummaryInputs */

const en_publish_backtosummary = /** @type {(inputs: Publish_BacktosummaryInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Back to summary`)
};

const zh_cn2_publish_backtosummary = /** @type {(inputs: Publish_BacktosummaryInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`返回总结`)
};

const ja_publish_backtosummary = /** @type {(inputs: Publish_BacktosummaryInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`概要に戻る`)
};

/**
* | output |
* | --- |
* | "Back to summary" |
*
* @param {Publish_BacktosummaryInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_backtosummary = /** @type {((inputs?: Publish_BacktosummaryInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_BacktosummaryInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_backtosummary(inputs)
	if (locale === "ja") return ja_publish_backtosummary(inputs)
	return en_publish_backtosummary(inputs)
});