/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Passwordless_DescriptionInputs */

const en_auth_passwordless_description = /** @type {(inputs: Auth_Passwordless_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`There is no password to reset. Enter your email on the login page and we will send you a secure one-time code.`)
};

const zh_cn2_auth_passwordless_description = /** @type {(inputs: Auth_Passwordless_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`没有密码可以重置。在登录页面上输入您的电子邮件，我们将向您发送一个安全的一次性代码。`)
};

const ja_auth_passwordless_description = /** @type {(inputs: Auth_Passwordless_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`リセットするパスワードはありません。ログインページにメールアドレスを入力すると、安全なワンタイムコードが送信されます。`)
};

/**
* | output |
* | --- |
* | "There is no password to reset. Enter your email on the login page and we will send you a secure one-time code." |
*
* @param {Auth_Passwordless_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_passwordless_description = /** @type {((inputs?: Auth_Passwordless_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Passwordless_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_passwordless_description(inputs)
	if (locale === "ja") return ja_auth_passwordless_description(inputs)
	return en_auth_passwordless_description(inputs)
});