import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_SyncerrorInputs */

const en_settings_openapi_syncerror = /** @type {(inputs: Settings_Openapi_SyncerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not refresh the OpenAPI source.`)
};

const zh_cn2_settings_openapi_syncerror = /** @type {(inputs: Settings_Openapi_SyncerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法刷新 OpenAPI 源。`)
};

const ja_settings_openapi_syncerror = /** @type {(inputs: Settings_Openapi_SyncerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`OpenAPI ソースを更新できませんでした。`)
};

/**
* | output |
* | --- |
* | "Could not refresh the OpenAPI source." |
*
* @param {Settings_Openapi_SyncerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_syncerror = /** @type {((inputs?: Settings_Openapi_SyncerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_SyncerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_syncerror(inputs)
	if (locale === "ja") return ja_settings_openapi_syncerror(inputs)
	return en_settings_openapi_syncerror(inputs)
});