import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_VerifyingInputs */

const en_auth_verify_verifying = /** @type {(inputs: Auth_Verify_VerifyingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Verifying your email…`)
};

const zh_cn2_auth_verify_verifying = /** @type {(inputs: Auth_Verify_VerifyingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`正在验证您的电子邮件...`)
};

const ja_auth_verify_verifying = /** @type {(inputs: Auth_Verify_VerifyingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`メールアドレスを確認しています…`)
};

/**
* | output |
* | --- |
* | "Verifying your email…" |
*
* @param {Auth_Verify_VerifyingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_verifying = /** @type {((inputs?: Auth_Verify_VerifyingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_VerifyingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_verifying(inputs)
	if (locale === "ja") return ja_auth_verify_verifying(inputs)
	return en_auth_verify_verifying(inputs)
});