/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_VariablesInputs */

const en_settings_variables = /** @type {(inputs: Settings_VariablesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Variables`)
};

const zh_cn2_settings_variables = /** @type {(inputs: Settings_VariablesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`变量`)
};

const ja_settings_variables = /** @type {(inputs: Settings_VariablesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`変数`)
};

/**
* | output |
* | --- |
* | "Variables" |
*
* @param {Settings_VariablesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_variables = /** @type {((inputs?: Settings_VariablesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_VariablesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_variables(inputs)
	if (locale === "ja") return ja_settings_variables(inputs)
	return en_settings_variables(inputs)
});