import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_VerifiedInputs */

const en_auth_verify_verified = /** @type {(inputs: Auth_Verify_VerifiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Your email is verified. Redirecting…`)
};

const zh_cn2_auth_verify_verified = /** @type {(inputs: Auth_Verify_VerifiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您的电子邮件已验证。正在重定向...`)
};

const ja_auth_verify_verified = /** @type {(inputs: Auth_Verify_VerifiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`あなたのメールアドレスが確認されました。リダイレクト中…`)
};

/**
* | output |
* | --- |
* | "Your email is verified. Redirecting…" |
*
* @param {Auth_Verify_VerifiedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_verified = /** @type {((inputs?: Auth_Verify_VerifiedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_VerifiedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_verified(inputs)
	if (locale === "ja") return ja_auth_verify_verified(inputs)
	return en_auth_verify_verified(inputs)
});