import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ResetInputs */

const en_settings_theme_reset = /** @type {(inputs: Settings_Theme_ResetInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Reset preset`)
};

const zh_cn2_settings_theme_reset = /** @type {(inputs: Settings_Theme_ResetInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`重置预设`)
};

const ja_settings_theme_reset = /** @type {(inputs: Settings_Theme_ResetInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`プリセットをリセット`)
};

/**
* | output |
* | --- |
* | "Reset preset" |
*
* @param {Settings_Theme_ResetInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_reset = /** @type {((inputs?: Settings_Theme_ResetInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ResetInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_reset(inputs)
	if (locale === "ja") return ja_settings_theme_reset(inputs)
	return en_settings_theme_reset(inputs)
});