import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Branding_UploadedInputs */

const en_settings_branding_uploaded = /** @type {(inputs: Settings_Branding_UploadedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Uploaded`)
};

const zh_cn2_settings_branding_uploaded = /** @type {(inputs: Settings_Branding_UploadedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已上传`)
};

const ja_settings_branding_uploaded = /** @type {(inputs: Settings_Branding_UploadedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`アップロードされました`)
};

/**
* | output |
* | --- |
* | "Uploaded" |
*
* @param {Settings_Branding_UploadedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_branding_uploaded = /** @type {((inputs?: Settings_Branding_UploadedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Branding_UploadedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_branding_uploaded(inputs)
	if (locale === "ja") return ja_settings_branding_uploaded(inputs)
	return en_settings_branding_uploaded(inputs)
});