/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ provider: NonNullable<unknown> }} Settings_Git_ConnectedtoastInputs */

const en_settings_git_connectedtoast = /** @type {(inputs: Settings_Git_ConnectedtoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Connected to ${i?.provider}`)
};

const zh_cn2_settings_git_connectedtoast = /** @type {(inputs: Settings_Git_ConnectedtoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`连接到 ${i?.provider}`)
};

const ja_settings_git_connectedtoast = /** @type {(inputs: Settings_Git_ConnectedtoastInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.provider} に接続しました`)
};

/**
* | output |
* | --- |
* | "Connected to {provider}" |
*
* @param {Settings_Git_ConnectedtoastInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_connectedtoast = /** @type {((inputs: Settings_Git_ConnectedtoastInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_ConnectedtoastInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_connectedtoast(inputs)
	if (locale === "ja") return ja_settings_git_connectedtoast(inputs)
	return en_settings_git_connectedtoast(inputs)
});