import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_RedirectsblockedhintInputs */

const en_publish_redirectsblockedhint = /** @type {(inputs: Publish_RedirectsblockedhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No changes will go live until every redirect points directly to a valid published page or permitted external URL.`)
};

const zh_cn2_publish_redirectsblockedhint = /** @type {(inputs: Publish_RedirectsblockedhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`在每个重定向直接指向有效的已发布页面或允许的外部 URL 之前，任何更改都不会生效。`)
};

const ja_publish_redirectsblockedhint = /** @type {(inputs: Publish_RedirectsblockedhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`すべてのリダイレクトが有効な公開ページまたは許可された外部 URL を直接ポイントするまで、変更は有効になりません。`)
};

/**
* | output |
* | --- |
* | "No changes will go live until every redirect points directly to a valid published page or permitted external URL." |
*
* @param {Publish_RedirectsblockedhintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_redirectsblockedhint = /** @type {((inputs?: Publish_RedirectsblockedhintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_RedirectsblockedhintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_redirectsblockedhint(inputs)
	if (locale === "ja") return ja_publish_redirectsblockedhint(inputs)
	return en_publish_redirectsblockedhint(inputs)
});