import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_Smtp_DescriptionInputs */

const en_settings_integrations_smtp_description = /** @type {(inputs: Settings_Integrations_Smtp_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Instance-managed SMTP email delivery.`)
};

const zh_cn2_settings_integrations_smtp_description = /** @type {(inputs: Settings_Integrations_Smtp_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`由实例管理的 SMTP 电子邮件发送服务。`)
};

const ja_settings_integrations_smtp_description = /** @type {(inputs: Settings_Integrations_Smtp_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`インスタンス管理の SMTP 電子メール配信。`)
};

/**
* | output |
* | --- |
* | "Instance-managed SMTP email delivery." |
*
* @param {Settings_Integrations_Smtp_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_smtp_description = /** @type {((inputs?: Settings_Integrations_Smtp_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_Smtp_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_smtp_description(inputs)
	if (locale === "ja") return ja_settings_integrations_smtp_description(inputs)
	return en_settings_integrations_smtp_description(inputs)
});