import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_RetryInputs */

const en_settings_domain_retry = /** @type {(inputs: Settings_Domain_RetryInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Retry check`)
};

const zh_cn2_settings_domain_retry = /** @type {(inputs: Settings_Domain_RetryInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`重试检查`)
};

const ja_settings_domain_retry = /** @type {(inputs: Settings_Domain_RetryInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`リトライチェック`)
};

/**
* | output |
* | --- |
* | "Retry check" |
*
* @param {Settings_Domain_RetryInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_retry = /** @type {((inputs?: Settings_Domain_RetryInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_RetryInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_retry(inputs)
	if (locale === "ja") return ja_settings_domain_retry(inputs)
	return en_settings_domain_retry(inputs)
});