/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ name: NonNullable<unknown> }} Settings_Addons_EnableInputs */

const en_settings_addons_enable = /** @type {(inputs: Settings_Addons_EnableInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Enable ${i?.name}`)
};

const zh_cn2_settings_addons_enable = /** @type {(inputs: Settings_Addons_EnableInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`启用 ${i?.name}`)
};

const ja_settings_addons_enable = /** @type {(inputs: Settings_Addons_EnableInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.name} を有効にする`)
};

/**
* | output |
* | --- |
* | "Enable {name}" |
*
* @param {Settings_Addons_EnableInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_addons_enable = /** @type {((inputs: Settings_Addons_EnableInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Addons_EnableInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_addons_enable(inputs)
	if (locale === "ja") return ja_settings_addons_enable(inputs)
	return en_settings_addons_enable(inputs)
});