import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Nav_OverviewInputs */

const en_nav_overview = /** @type {(inputs: Nav_OverviewInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Overview`)
};

const zh_cn2_nav_overview = /** @type {(inputs: Nav_OverviewInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`概述`)
};

const ja_nav_overview = /** @type {(inputs: Nav_OverviewInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`概要`)
};

/**
* | output |
* | --- |
* | "Overview" |
*
* @param {Nav_OverviewInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const nav_overview = /** @type {((inputs?: Nav_OverviewInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Nav_OverviewInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_nav_overview(inputs)
	if (locale === "ja") return ja_nav_overview(inputs)
	return en_nav_overview(inputs)
});