import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Invite_ExpirederrorInputs */

const en_auth_invite_expirederror = /** @type {(inputs: Auth_Invite_ExpirederrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`This invitation has expired. Ask the inviter to send a new one.`)
};

const zh_cn2_auth_invite_expirederror = /** @type {(inputs: Auth_Invite_ExpirederrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`此邀请已过期。请邀请者发送一份新的。`)
};

const ja_auth_invite_expirederror = /** @type {(inputs: Auth_Invite_ExpirederrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`この招待状の有効期限は切れています。招待者に新しい招待状を送信するよう依頼してください。`)
};

/**
* | output |
* | --- |
* | "This invitation has expired. Ask the inviter to send a new one." |
*
* @param {Auth_Invite_ExpirederrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_invite_expirederror = /** @type {((inputs?: Auth_Invite_ExpirederrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Invite_ExpirederrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_invite_expirederror(inputs)
	if (locale === "ja") return ja_auth_invite_expirederror(inputs)
	return en_auth_invite_expirederror(inputs)
});