/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_ShowpagesInputs */

const en_editor_showpages = /** @type {(inputs: Editor_ShowpagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Show pages`)
};

const zh_cn2_editor_showpages = /** @type {(inputs: Editor_ShowpagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`显示页面`)
};

const ja_editor_showpages = /** @type {(inputs: Editor_ShowpagesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ページを表示する`)
};

/**
* | output |
* | --- |
* | "Show pages" |
*
* @param {Editor_ShowpagesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_showpages = /** @type {((inputs?: Editor_ShowpagesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_ShowpagesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_showpages(inputs)
	if (locale === "ja") return ja_editor_showpages(inputs)
	return en_editor_showpages(inputs)
});