import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Seo_Scope_HintInputs */

const en_settings_seo_scope_hint = /** @type {(inputs: Settings_Seo_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose which language these SEO defaults apply to.`)
};

const zh_cn2_settings_seo_scope_hint = /** @type {(inputs: Settings_Seo_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择这些 SEO 默认值适用的语言。`)
};

const ja_settings_seo_scope_hint = /** @type {(inputs: Settings_Seo_Scope_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`これらの SEO デフォルトが適用される言語を選択します。`)
};

/**
* | output |
* | --- |
* | "Choose which language these SEO defaults apply to." |
*
* @param {Settings_Seo_Scope_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_seo_scope_hint = /** @type {((inputs?: Settings_Seo_Scope_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Seo_Scope_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_seo_scope_hint(inputs)
	if (locale === "ja") return ja_settings_seo_scope_hint(inputs)
	return en_settings_seo_scope_hint(inputs)
});