/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_ReviewtitleInputs */

const en_publish_reviewtitle = /** @type {(inputs: Publish_ReviewtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Review changes`)
};

const zh_cn2_publish_reviewtitle = /** @type {(inputs: Publish_ReviewtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`审查变更`)
};

const ja_publish_reviewtitle = /** @type {(inputs: Publish_ReviewtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`変更を確認する`)
};

/**
* | output |
* | --- |
* | "Review changes" |
*
* @param {Publish_ReviewtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_reviewtitle = /** @type {((inputs?: Publish_ReviewtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_ReviewtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_reviewtitle(inputs)
	if (locale === "ja") return ja_publish_reviewtitle(inputs)
	return en_publish_reviewtitle(inputs)
});