import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Access_DescriptionInputs */

const en_settings_git_access_description = /** @type {(inputs: Settings_Git_Access_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Manage your docs as Markdown files in a public Git repository, then pull updates into cms when needed.`)
};

const zh_cn2_settings_git_access_description = /** @type {(inputs: Settings_Git_Access_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`将您的文档作为公共 Git 存储库中的 Markdown 文件进行管理，然后在需要时将更新拉取到 cms 中。`)
};

const ja_settings_git_access_description = /** @type {(inputs: Settings_Git_Access_DescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドキュメントをパブリック Git リポジトリで Markdown ファイルとして管理し、必要に応じて更新を cms にプルします。`)
};

/**
* | output |
* | --- |
* | "Manage your docs as Markdown files in a public Git repository, then pull updates into cms when needed." |
*
* @param {Settings_Git_Access_DescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_access_description = /** @type {((inputs?: Settings_Git_Access_DescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Access_DescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_access_description(inputs)
	if (locale === "ja") return ja_settings_git_access_description(inputs)
	return en_settings_git_access_description(inputs)
});