import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ max: NonNullable<unknown>, current: NonNullable<unknown> }} Admin_Sites_ReasonlengthInputs */

const en_admin_sites_reasonlength = /** @type {(inputs: Admin_Sites_ReasonlengthInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Reason must be ${i?.max} characters or fewer (currently ${i?.current}).`)
};

const zh_cn2_admin_sites_reasonlength = /** @type {(inputs: Admin_Sites_ReasonlengthInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Reason must be ${i?.max} characters or fewer (currently ${i?.current}).`)
};

const ja_admin_sites_reasonlength = /** @type {(inputs: Admin_Sites_ReasonlengthInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`理由は ${i?.max} 文字以下である必要があります (現在は ${i?.current})。`)
};

/**
* | output |
* | --- |
* | "Reason must be {max} characters or fewer (currently {current})." |
*
* @param {Admin_Sites_ReasonlengthInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_sites_reasonlength = /** @type {((inputs: Admin_Sites_ReasonlengthInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Sites_ReasonlengthInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_sites_reasonlength(inputs)
	if (locale === "ja") return ja_admin_sites_reasonlength(inputs)
	return en_admin_sites_reasonlength(inputs)
});