/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_ReviewsubtitleInputs */

const en_publish_reviewsubtitle = /** @type {(inputs: Publish_ReviewsubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Compare the next publish against the current live site.`)
};

const zh_cn2_publish_reviewsubtitle = /** @type {(inputs: Publish_ReviewsubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`将下一个发布与当前的实时站点进行比较。`)
};

const ja_publish_reviewsubtitle = /** @type {(inputs: Publish_ReviewsubtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`次の公開サイトと現在のライブ サイトを比較します。`)
};

/**
* | output |
* | --- |
* | "Compare the next publish against the current live site." |
*
* @param {Publish_ReviewsubtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_reviewsubtitle = /** @type {((inputs?: Publish_ReviewsubtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_ReviewsubtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_reviewsubtitle(inputs)
	if (locale === "ja") return ja_publish_reviewsubtitle(inputs)
	return en_publish_reviewsubtitle(inputs)
});