/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ version: NonNullable<unknown> }} Publish_SinceversionInputs */

const en_publish_sinceversion = /** @type {(inputs: Publish_SinceversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Since v${i?.version}`)
};

const zh_cn2_publish_sinceversion = /** @type {(inputs: Publish_SinceversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`自 v${i?.version} 起`)
};

const ja_publish_sinceversion = /** @type {(inputs: Publish_SinceversionInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`v${i?.version} 以降`)
};

/**
* | output |
* | --- |
* | "Since v{version}" |
*
* @param {Publish_SinceversionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_sinceversion = /** @type {((inputs: Publish_SinceversionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_SinceversionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_sinceversion(inputs)
	if (locale === "ja") return ja_publish_sinceversion(inputs)
	return en_publish_sinceversion(inputs)
});