import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Languages_DeleteerrorInputs */

const en_settings_languages_deleteerror = /** @type {(inputs: Settings_Languages_DeleteerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not delete the language`)
};

const zh_cn2_settings_languages_deleteerror = /** @type {(inputs: Settings_Languages_DeleteerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法删除语言`)
};

const ja_settings_languages_deleteerror = /** @type {(inputs: Settings_Languages_DeleteerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を削除できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not delete the language" |
*
* @param {Settings_Languages_DeleteerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_languages_deleteerror = /** @type {((inputs?: Settings_Languages_DeleteerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Languages_DeleteerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_languages_deleteerror(inputs)
	if (locale === "ja") return ja_settings_languages_deleteerror(inputs)
	return en_settings_languages_deleteerror(inputs)
});