/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Theme_ChoosefileInputs */

const en_settings_theme_choosefile = /** @type {(inputs: Settings_Theme_ChoosefileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Choose JSON file`)
};

const zh_cn2_settings_theme_choosefile = /** @type {(inputs: Settings_Theme_ChoosefileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择 JSON 文件`)
};

const ja_settings_theme_choosefile = /** @type {(inputs: Settings_Theme_ChoosefileInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`JSONファイルを選択してください`)
};

/**
* | output |
* | --- |
* | "Choose JSON file" |
*
* @param {Settings_Theme_ChoosefileInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_theme_choosefile = /** @type {((inputs?: Settings_Theme_ChoosefileInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Theme_ChoosefileInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_theme_choosefile(inputs)
	if (locale === "ja") return ja_settings_theme_choosefile(inputs)
	return en_settings_theme_choosefile(inputs)
});