/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Preview_EmptyInputs */

const en_preview_empty = /** @type {(inputs: Preview_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`No draft pages are available to preview.`)
};

const zh_cn2_preview_empty = /** @type {(inputs: Preview_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`没有草稿页面可供预览。`)
};

const ja_preview_empty = /** @type {(inputs: Preview_EmptyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`プレビューできるドラフト ページはありません。`)
};

/**
* | output |
* | --- |
* | "No draft pages are available to preview." |
*
* @param {Preview_EmptyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const preview_empty = /** @type {((inputs?: Preview_EmptyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Preview_EmptyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_preview_empty(inputs)
	if (locale === "ja") return ja_preview_empty(inputs)
	return en_preview_empty(inputs)
});