/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ email: NonNullable<unknown> }} Auth_Otp_CheckemailInputs */

const en_auth_otp_checkemail = /** @type {(inputs: Auth_Otp_CheckemailInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`Enter the code sent to ${i?.email}`)
};

const zh_cn2_auth_otp_checkemail = /** @type {(inputs: Auth_Otp_CheckemailInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`输入发送到 ${i?.email} 的代码`)
};

const ja_auth_otp_checkemail = /** @type {(inputs: Auth_Otp_CheckemailInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.email} に送信されたコードを入力してください`)
};

/**
* | output |
* | --- |
* | "Enter the code sent to {email}" |
*
* @param {Auth_Otp_CheckemailInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_otp_checkemail = /** @type {((inputs: Auth_Otp_CheckemailInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Otp_CheckemailInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_otp_checkemail(inputs)
	if (locale === "ja") return ja_auth_otp_checkemail(inputs)
	return en_auth_otp_checkemail(inputs)
});