import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Publicimport_TitleInputs */

const en_settings_git_publicimport_title = /** @type {(inputs: Settings_Git_Publicimport_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import a public repository instead`)
};

const zh_cn2_settings_git_publicimport_title = /** @type {(inputs: Settings_Git_Publicimport_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`改为导入公共存储库`)
};

const ja_settings_git_publicimport_title = /** @type {(inputs: Settings_Git_Publicimport_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`代わりにパブリックリポジトリをインポートしてください`)
};

/**
* | output |
* | --- |
* | "Import a public repository instead" |
*
* @param {Settings_Git_Publicimport_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_publicimport_title = /** @type {((inputs?: Settings_Git_Publicimport_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Publicimport_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_publicimport_title(inputs)
	if (locale === "ja") return ja_settings_git_publicimport_title(inputs)
	return en_settings_git_publicimport_title(inputs)
});