/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_DeployedInputs */

const en_deploy_deployed = /** @type {(inputs: Deploy_DeployedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Deployed successfully`)
};

const zh_cn2_deploy_deployed = /** @type {(inputs: Deploy_DeployedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`部署成功`)
};

const ja_deploy_deployed = /** @type {(inputs: Deploy_DeployedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`正常に展開されました`)
};

/**
* | output |
* | --- |
* | "Deployed successfully" |
*
* @param {Deploy_DeployedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_deployed = /** @type {((inputs?: Deploy_DeployedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_DeployedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_deployed(inputs)
	if (locale === "ja") return ja_deploy_deployed(inputs)
	return en_deploy_deployed(inputs)
});