import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Openapi_SaveerrorInputs */

const en_settings_openapi_saveerror = /** @type {(inputs: Settings_Openapi_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not save the OpenAPI document.`)
};

const zh_cn2_settings_openapi_saveerror = /** @type {(inputs: Settings_Openapi_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法保存 OpenAPI 文档。`)
};

const ja_settings_openapi_saveerror = /** @type {(inputs: Settings_Openapi_SaveerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`OpenAPI ドキュメントを保存できませんでした。`)
};

/**
* | output |
* | --- |
* | "Could not save the OpenAPI document." |
*
* @param {Settings_Openapi_SaveerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_openapi_saveerror = /** @type {((inputs?: Settings_Openapi_SaveerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Openapi_SaveerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_openapi_saveerror(inputs)
	if (locale === "ja") return ja_settings_openapi_saveerror(inputs)
	return en_settings_openapi_saveerror(inputs)
});