/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Publish_ChangesInputs */

const en_publish_changes = /** @type {(inputs: Publish_ChangesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Changes`)
};

const zh_cn2_publish_changes = /** @type {(inputs: Publish_ChangesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`变化`)
};

const ja_publish_changes = /** @type {(inputs: Publish_ChangesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`変更点`)
};

/**
* | output |
* | --- |
* | "Changes" |
*
* @param {Publish_ChangesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const publish_changes = /** @type {((inputs?: Publish_ChangesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Publish_ChangesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_publish_changes(inputs)
	if (locale === "ja") return ja_publish_changes(inputs)
	return en_publish_changes(inputs)
});