import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ count: NonNullable<unknown> }} Settings_Authentication_Reader_SessioncountInputs */

const en_settings_authentication_reader_sessioncount = /** @type {(inputs: Settings_Authentication_Reader_SessioncountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} active sessions`)
};

const zh_cn2_settings_authentication_reader_sessioncount = /** @type {(inputs: Settings_Authentication_Reader_SessioncountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 活动会话`)
};

const ja_settings_authentication_reader_sessioncount = /** @type {(inputs: Settings_Authentication_Reader_SessioncountInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.count} 個のアクティブなセッション`)
};

/**
* | output |
* | --- |
* | "{count} active sessions" |
*
* @param {Settings_Authentication_Reader_SessioncountInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_authentication_reader_sessioncount = /** @type {((inputs: Settings_Authentication_Reader_SessioncountInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Authentication_Reader_SessioncountInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_authentication_reader_sessioncount(inputs)
	if (locale === "ja") return ja_settings_authentication_reader_sessioncount(inputs)
	return en_settings_authentication_reader_sessioncount(inputs)
});