import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_ConfiguredInputs */

const en_settings_integrations_configured = /** @type {(inputs: Settings_Integrations_ConfiguredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Configured`)
};

const zh_cn2_settings_integrations_configured = /** @type {(inputs: Settings_Integrations_ConfiguredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已配置`)
};

const ja_settings_integrations_configured = /** @type {(inputs: Settings_Integrations_ConfiguredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`設定済み`)
};

/**
* | output |
* | --- |
* | "Configured" |
*
* @param {Settings_Integrations_ConfiguredInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_configured = /** @type {((inputs?: Settings_Integrations_ConfiguredInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_ConfiguredInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_configured(inputs)
	if (locale === "ja") return ja_settings_integrations_configured(inputs)
	return en_settings_integrations_configured(inputs)
});