import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Addlanguage_RequiredInputs */

const en_editor_addlanguage_required = /** @type {(inputs: Editor_Addlanguage_RequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Select a language`)
};

const zh_cn2_editor_addlanguage_required = /** @type {(inputs: Editor_Addlanguage_RequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`选择语言`)
};

const ja_editor_addlanguage_required = /** @type {(inputs: Editor_Addlanguage_RequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を選択してください`)
};

/**
* | output |
* | --- |
* | "Select a language" |
*
* @param {Editor_Addlanguage_RequiredInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_addlanguage_required = /** @type {((inputs?: Editor_Addlanguage_RequiredInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Addlanguage_RequiredInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_addlanguage_required(inputs)
	if (locale === "ja") return ja_editor_addlanguage_required(inputs)
	return en_editor_addlanguage_required(inputs)
});