import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_ThemesInputs */

const en_settings_themes = /** @type {(inputs: Settings_ThemesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Themes`)
};

const zh_cn2_settings_themes = /** @type {(inputs: Settings_ThemesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`主题`)
};

const ja_settings_themes = /** @type {(inputs: Settings_ThemesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`テーマ`)
};

/**
* | output |
* | --- |
* | "Themes" |
*
* @param {Settings_ThemesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_themes = /** @type {((inputs?: Settings_ThemesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_ThemesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_themes(inputs)
	if (locale === "ja") return ja_settings_themes(inputs)
	return en_settings_themes(inputs)
});