import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Account_Email_ConfirmInputs */

const en_settings_account_email_confirm = /** @type {(inputs: Settings_Account_Email_ConfirmInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Confirm new email`)
};

const zh_cn2_settings_account_email_confirm = /** @type {(inputs: Settings_Account_Email_ConfirmInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`确认新电子邮件`)
};

const ja_settings_account_email_confirm = /** @type {(inputs: Settings_Account_Email_ConfirmInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`新しいメールを確認する`)
};

/**
* | output |
* | --- |
* | "Confirm new email" |
*
* @param {Settings_Account_Email_ConfirmInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_account_email_confirm = /** @type {((inputs?: Settings_Account_Email_ConfirmInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Account_Email_ConfirmInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_account_email_confirm(inputs)
	if (locale === "ja") return ja_settings_account_email_confirm(inputs)
	return en_settings_account_email_confirm(inputs)
});