import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Overview_Col_UpdatedInputs */

const en_overview_col_updated = /** @type {(inputs: Overview_Col_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Updated`)
};

const zh_cn2_overview_col_updated = /** @type {(inputs: Overview_Col_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已更新`)
};

const ja_overview_col_updated = /** @type {(inputs: Overview_Col_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`更新されました`)
};

/**
* | output |
* | --- |
* | "Updated" |
*
* @param {Overview_Col_UpdatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const overview_col_updated = /** @type {((inputs?: Overview_Col_UpdatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Overview_Col_UpdatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_overview_col_updated(inputs)
	if (locale === "ja") return ja_overview_col_updated(inputs)
	return en_overview_col_updated(inputs)
});