import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_SenderrorInputs */

const en_auth_verify_senderror = /** @type {(inputs: Auth_Verify_SenderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The code could not be sent. Please try sending a new one.`)
};

const zh_cn2_auth_verify_senderror = /** @type {(inputs: Auth_Verify_SenderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法发送代码。请尝试发送新的。`)
};

const ja_auth_verify_senderror = /** @type {(inputs: Auth_Verify_SenderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コードを送信できませんでした。新しいものを送信してみてください。`)
};

/**
* | output |
* | --- |
* | "The code could not be sent. Please try sending a new one." |
*
* @param {Auth_Verify_SenderrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_senderror = /** @type {((inputs?: Auth_Verify_SenderrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_SenderrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_senderror(inputs)
	if (locale === "ja") return ja_auth_verify_senderror(inputs)
	return en_auth_verify_senderror(inputs)
});