import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_InvalidurlInputs */

const en_settings_import_ghost_invalidurl = /** @type {(inputs: Settings_Import_Ghost_InvalidurlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Enter the full Ghost site URL, including https://.`)
};

const zh_cn2_settings_import_ghost_invalidurl = /** @type {(inputs: Settings_Import_Ghost_InvalidurlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`输入完整的 Ghost 站点 URL，包括 https://.`)
};

const ja_settings_import_ghost_invalidurl = /** @type {(inputs: Settings_Import_Ghost_InvalidurlInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`https:// を含む完全な Ghost サイト URL を入力します。`)
};

/**
* | output |
* | --- |
* | "Enter the full Ghost site URL, including https://." |
*
* @param {Settings_Import_Ghost_InvalidurlInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_invalidurl = /** @type {((inputs?: Settings_Import_Ghost_InvalidurlInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_InvalidurlInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_invalidurl(inputs)
	if (locale === "ja") return ja_settings_import_ghost_invalidurl(inputs)
	return en_settings_import_ghost_invalidurl(inputs)
});