import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Git_Import_TitleInputs */

const en_settings_git_import_title = /** @type {(inputs: Settings_Git_Import_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Import content`)
};

const zh_cn2_settings_git_import_title = /** @type {(inputs: Settings_Git_Import_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`导入内容`)
};

const ja_settings_git_import_title = /** @type {(inputs: Settings_Git_Import_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コンテンツをインポートする`)
};

/**
* | output |
* | --- |
* | "Import content" |
*
* @param {Settings_Git_Import_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_git_import_title = /** @type {((inputs?: Settings_Git_Import_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Git_Import_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_git_import_title(inputs)
	if (locale === "ja") return ja_settings_git_import_title(inputs)
	return en_settings_git_import_title(inputs)
});