/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_MarkdownplaceholderInputs */

const en_editor_markdownplaceholder = /** @type {(inputs: Editor_MarkdownplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Write Markdown / MDX…`)
};

const zh_cn2_editor_markdownplaceholder = /** @type {(inputs: Editor_MarkdownplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`写入 Markdown / MDX...`)
};

const ja_editor_markdownplaceholder = /** @type {(inputs: Editor_MarkdownplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`マークダウン/MDX の書き込み…`)
};

/**
* | output |
* | --- |
* | "Write Markdown / MDX…" |
*
* @param {Editor_MarkdownplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_markdownplaceholder = /** @type {((inputs?: Editor_MarkdownplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_MarkdownplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_markdownplaceholder(inputs)
	if (locale === "ja") return ja_editor_markdownplaceholder(inputs)
	return en_editor_markdownplaceholder(inputs)
});