import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Exports_Html_TitleInputs */

const en_settings_exports_html_title = /** @type {(inputs: Settings_Exports_Html_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Static HTML export`)
};

const zh_cn2_settings_exports_html_title = /** @type {(inputs: Settings_Exports_Html_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`静态 HTML 导出`)
};

const ja_settings_exports_html_title = /** @type {(inputs: Settings_Exports_Html_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`静的 HTML エクスポート`)
};

/**
* | output |
* | --- |
* | "Static HTML export" |
*
* @param {Settings_Exports_Html_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_exports_html_title = /** @type {((inputs?: Settings_Exports_Html_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Exports_Html_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_exports_html_title(inputs)
	if (locale === "ja") return ja_settings_exports_html_title(inputs)
	return en_settings_exports_html_title(inputs)
});