import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_Addlanguage_CustomInputs */

const en_editor_addlanguage_custom = /** @type {(inputs: Editor_Addlanguage_CustomInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Add a language not listed`)
};

const zh_cn2_editor_addlanguage_custom = /** @type {(inputs: Editor_Addlanguage_CustomInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`添加未列出的语言`)
};

const ja_editor_addlanguage_custom = /** @type {(inputs: Editor_Addlanguage_CustomInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`リストにない言語を追加する`)
};

/**
* | output |
* | --- |
* | "Add a language not listed" |
*
* @param {Editor_Addlanguage_CustomInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_addlanguage_custom = /** @type {((inputs?: Editor_Addlanguage_CustomInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_Addlanguage_CustomInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_addlanguage_custom(inputs)
	if (locale === "ja") return ja_editor_addlanguage_custom(inputs)
	return en_editor_addlanguage_custom(inputs)
});