import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Integrations_ConnectedInputs */

const en_settings_integrations_connected = /** @type {(inputs: Settings_Integrations_ConnectedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Connected`)
};

const zh_cn2_settings_integrations_connected = /** @type {(inputs: Settings_Integrations_ConnectedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已连接`)
};

const ja_settings_integrations_connected = /** @type {(inputs: Settings_Integrations_ConnectedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`接続済み`)
};

/**
* | output |
* | --- |
* | "Connected" |
*
* @param {Settings_Integrations_ConnectedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_integrations_connected = /** @type {((inputs?: Settings_Integrations_ConnectedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Integrations_ConnectedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_integrations_connected(inputs)
	if (locale === "ja") return ja_settings_integrations_connected(inputs)
	return en_settings_integrations_connected(inputs)
});