import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ organization: NonNullable<unknown>, plan: NonNullable<unknown> }} Admin_Sites_OrgplanInputs */

const en_admin_sites_orgplan = /** @type {(inputs: Admin_Sites_OrgplanInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.organization} · ${i?.plan} plan`)
};

const zh_cn2_admin_sites_orgplan = /** @type {(inputs: Admin_Sites_OrgplanInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.organization} · ${i?.plan} plan`)
};

const ja_admin_sites_orgplan = /** @type {(inputs: Admin_Sites_OrgplanInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`${i?.organization} · ${i?.plan} 計画`)
};

/**
* | output |
* | --- |
* | "{organization} · {plan} plan" |
*
* @param {Admin_Sites_OrgplanInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const admin_sites_orgplan = /** @type {((inputs: Admin_Sites_OrgplanInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Admin_Sites_OrgplanInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_admin_sites_orgplan(inputs)
	if (locale === "ja") return ja_admin_sites_orgplan(inputs)
	return en_admin_sites_orgplan(inputs)
});