import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Verify_SubmitInputs */

const en_auth_verify_submit = /** @type {(inputs: Auth_Verify_SubmitInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Verify email`)
};

const zh_cn2_auth_verify_submit = /** @type {(inputs: Auth_Verify_SubmitInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`验证电子邮件`)
};

const ja_auth_verify_submit = /** @type {(inputs: Auth_Verify_SubmitInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`メールの確認`)
};

/**
* | output |
* | --- |
* | "Verify email" |
*
* @param {Auth_Verify_SubmitInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_verify_submit = /** @type {((inputs?: Auth_Verify_SubmitInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Verify_SubmitInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_verify_submit(inputs)
	if (locale === "ja") return ja_auth_verify_submit(inputs)
	return en_auth_verify_submit(inputs)
});