import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Auth_Signin_SubmittingInputs */

const en_auth_signin_submitting = /** @type {(inputs: Auth_Signin_SubmittingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Logging in…`)
};

const zh_cn2_auth_signin_submitting = /** @type {(inputs: Auth_Signin_SubmittingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`正在登录...`)
};

const ja_auth_signin_submitting = /** @type {(inputs: Auth_Signin_SubmittingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ログイン中…`)
};

/**
* | output |
* | --- |
* | "Logging in…" |
*
* @param {Auth_Signin_SubmittingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const auth_signin_submitting = /** @type {((inputs?: Auth_Signin_SubmittingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Auth_Signin_SubmittingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_auth_signin_submitting(inputs)
	if (locale === "ja") return ja_auth_signin_submitting(inputs)
	return en_auth_signin_submitting(inputs)
});