/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{ query: NonNullable<unknown> }} Blog_NoresultsInputs */

const en_blog_noresults = /** @type {(inputs: Blog_NoresultsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`No articles match “${i?.query}”. Try another search.`)
};

const zh_cn2_blog_noresults = /** @type {(inputs: Blog_NoresultsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`No articles match “${i?.query}”. Try another search.`)
};

const ja_blog_noresults = /** @type {(inputs: Blog_NoresultsInputs) => LocalizedString} */ (i) => {
	return /** @type {LocalizedString} */ (`「${i?.query}」に一致する記事はありません。別の検索を試してください。`)
};

/**
* | output |
* | --- |
* | "No articles match “{query}”. Try another search." |
*
* @param {Blog_NoresultsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const blog_noresults = /** @type {((inputs: Blog_NoresultsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Blog_NoresultsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_blog_noresults(inputs)
	if (locale === "ja") return ja_blog_noresults(inputs)
	return en_blog_noresults(inputs)
});