/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Deploy_Rollback_ErrorInputs */

const en_deploy_rollback_error = /** @type {(inputs: Deploy_Rollback_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not roll back`)
};

const zh_cn2_deploy_rollback_error = /** @type {(inputs: Deploy_Rollback_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法回滚`)
};

const ja_deploy_rollback_error = /** @type {(inputs: Deploy_Rollback_ErrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ロールバックできませんでした`)
};

/**
* | output |
* | --- |
* | "Could not roll back" |
*
* @param {Deploy_Rollback_ErrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const deploy_rollback_error = /** @type {((inputs?: Deploy_Rollback_ErrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Deploy_Rollback_ErrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_deploy_rollback_error(inputs)
	if (locale === "ja") return ja_deploy_rollback_error(inputs)
	return en_deploy_rollback_error(inputs)
});