import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Search_Placeholder_HintInputs */

const en_settings_search_placeholder_hint = /** @type {(inputs: Settings_Search_Placeholder_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Leave empty to use the localized search prompt for the reader’s active language.`)
};

const zh_cn2_settings_search_placeholder_hint = /** @type {(inputs: Settings_Search_Placeholder_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`搜索字段内显示的提示文本。`)
};

const ja_settings_search_placeholder_hint = /** @type {(inputs: Settings_Search_Placeholder_HintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`読者のアクティブな言語のローカライズされた検索プロンプトを使用するには、空のままにします。`)
};

/**
* | output |
* | --- |
* | "Leave empty to use the localized search prompt for the reader’s active language." |
*
* @param {Settings_Search_Placeholder_HintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_search_placeholder_hint = /** @type {((inputs?: Settings_Search_Placeholder_HintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Search_Placeholder_HintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_search_placeholder_hint(inputs)
	if (locale === "ja") return ja_settings_search_placeholder_hint(inputs)
	return en_settings_search_placeholder_hint(inputs)
});