/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Editor_ShowsidebarInputs */

const en_editor_showsidebar = /** @type {(inputs: Editor_ShowsidebarInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Show sidebar`)
};

const zh_cn2_editor_showsidebar = /** @type {(inputs: Editor_ShowsidebarInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`显示侧边栏`)
};

const ja_editor_showsidebar = /** @type {(inputs: Editor_ShowsidebarInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`サイドバーを表示`)
};

/**
* | output |
* | --- |
* | "Show sidebar" |
*
* @param {Editor_ShowsidebarInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const editor_showsidebar = /** @type {((inputs?: Editor_ShowsidebarInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Editor_ShowsidebarInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_editor_showsidebar(inputs)
	if (locale === "ja") return ja_editor_showsidebar(inputs)
	return en_editor_showsidebar(inputs)
});