import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_Toast_AdderrorInputs */

const en_settings_domain_toast_adderror = /** @type {(inputs: Settings_Domain_Toast_AdderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Could not add the domain`)
};

const zh_cn2_settings_domain_toast_adderror = /** @type {(inputs: Settings_Domain_Toast_AdderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`无法添加域`)
};

const ja_settings_domain_toast_adderror = /** @type {(inputs: Settings_Domain_Toast_AdderrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドメインを追加できませんでした`)
};

/**
* | output |
* | --- |
* | "Could not add the domain" |
*
* @param {Settings_Domain_Toast_AdderrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_toast_adderror = /** @type {((inputs?: Settings_Domain_Toast_AdderrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_Toast_AdderrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_toast_adderror(inputs)
	if (locale === "ja") return ja_settings_domain_toast_adderror(inputs)
	return en_settings_domain_toast_adderror(inputs)
});