import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Domain_Toast_AddedInputs */

const en_settings_domain_toast_added = /** @type {(inputs: Settings_Domain_Toast_AddedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Domain added`)
};

const zh_cn2_settings_domain_toast_added = /** @type {(inputs: Settings_Domain_Toast_AddedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已添加域名`)
};

const ja_settings_domain_toast_added = /** @type {(inputs: Settings_Domain_Toast_AddedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドメインが追加されました`)
};

/**
* | output |
* | --- |
* | "Domain added" |
*
* @param {Settings_Domain_Toast_AddedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_domain_toast_added = /** @type {((inputs?: Settings_Domain_Toast_AddedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Domain_Toast_AddedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_domain_toast_added(inputs)
	if (locale === "ja") return ja_settings_domain_toast_added(inputs)
	return en_settings_domain_toast_added(inputs)
});