import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Settings_Import_Ghost_LanguagetitleInputs */

const en_settings_import_ghost_languagetitle = /** @type {(inputs: Settings_Import_Ghost_LanguagetitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Tag every Ghost article with its language`)
};

const zh_cn2_settings_import_ghost_languagetitle = /** @type {(inputs: Settings_Import_Ghost_LanguagetitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`用语言标记每篇 Ghost 文章`)
};

const ja_settings_import_ghost_languagetitle = /** @type {(inputs: Settings_Import_Ghost_LanguagetitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`すべての Ghost 記事にその言語のタグを付ける`)
};

/**
* | output |
* | --- |
* | "Tag every Ghost article with its language" |
*
* @param {Settings_Import_Ghost_LanguagetitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const settings_import_ghost_languagetitle = /** @type {((inputs?: Settings_Import_Ghost_LanguagetitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Settings_Import_Ghost_LanguagetitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_settings_import_ghost_languagetitle(inputs)
	if (locale === "ja") return ja_settings_import_ghost_languagetitle(inputs)
	return en_settings_import_ghost_languagetitle(inputs)
});